}
.nt-dsg-sync {
  font-family: var(--nd-font-mono);
  font-size: 11px;
  color: var(--nd-text-muted);
}
.nt-dsg-search {
  display: flex;
  gap: 8px;
  align-items: center;
  padding: 8px 12px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 16%, var(--nd-border-default));
  background: color-mix(in srgb, var(--nd-bg-raised) 90%, transparent);
  max-width: 420px;
}
.nt-dsg-search__input {
  flex: 1;
  border: none;
  background: transparent;
  color: var(--nd-text-primary);
  outline: none;
  font: inherit;
}
.nt-dsg-search__kbd {
  font-family: var(--nd-font-mono);
  font-size: 10px;
  padding: 2px 6px;
  border-radius: 6px;
  border: 1px solid var(--nd-border-subtle);
  color: var(--nd-text-muted);
}
.nt-dsg-user {
  display: flex;
  gap: 8px;
  align-items: center;
}
.nt-dsg-stats {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 10px;
}
.nt-dsg-main {
  display: flex;
  flex-direction: column;
  gap: 18px;
}
.nt-dsg-device-name {
  font-weight: 550;
}
.nt-dsg-nav-label {
  margin: 12px 0 6px;
  color: var(--nd-text-muted);
}

/* center pads */
.nt-center-pad,
.nt-center-pad-24,
.nt-center-pad-64 {
  display: grid;
  place-items: center;
  text-align: center;
  color: var(--nd-text-secondary);
}
.nt-center-pad-24 { padding: 24px; }
.nt-center-pad-64 { padding: 64px 24px; }

/* danger text utility */
.nt-danger-text,
.nt-hint-muted.nt-danger-text {
  color: var(--nd-danger);
}
.nt-warning-text { color: var(--nd-warning); }

html[data-nd-theme='light'] .nt-dsg-search {
  background: var(--nd-bg-raised);
}

/* ── Wave 19gd — mobile shell · print · reduced-motion floor ── */
@media (max-width: 860px) {
  .nd-shell--rail {
    grid-template-columns: 1fr;
  }
  .nd-shell__rail {
    position: sticky;
    top: 0;
    z-index: 8;
    display: flex;
    flex-direction: row;
    overflow-x: auto;
    gap: 4px;
    padding: 8px;
    border-right: none;
    border-bottom: 1px solid color-mix(in srgb, var(--nd-accent) 12%, var(--nd-border-subtle));
  }
  .nt-overview__layout,
  .nt-configure__layout,
  .nt-device-layout,
  .nt-tickets,
  .nt-compliance-grid,
  .nt-systems__lower-grid,
  .nt-auth-grid {
    grid-template-columns: 1fr !important;
  }
  .nt-device-layout__rail {
    position: static;
  }
  .nt-chat-scroll {
    max-height: 48vh;
  }
}

@media print {
  .nd-shell__rail,
  .nd-shell__topbar,
  .nt-shift-strip,
  .nt-chat-fab,
  .nd-skip-link,
  .nt-bulk-bar,
  .nt-filter-bar.nt-sticky-filters {
    display: none !important;
  }
  .nd-shell__content,
  .nt-recon-reveal {
    animation: none !important;
  }
  body {
    background: white !important;
    color: black !important;
  }
}

@media (prefers-reduced-motion: reduce) {
  .nt-recon-reveal,
  .nt-write-ritual--banner,
  .nt-chat-pending__pulse,
  .nt-auth-wake-bar,
  * {
    scroll-behavior: auto !important;
  }
}

/* high-contrast affordance for P1 heat */
.nt-p1-heat,
[data-pri='P1'] .nt-p1-heat {
  color: var(--nd-danger);
  font-weight: 600;
}

/* mono label polish */
.nt-mono-label,
.nd-micro-label {
  font-family: var(--nd-font-mono);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--nd-text-muted);
}

/* linkish rows */
.nt-linkish,
button.nt-linkish {
  background: none;
  border: none;
  padding: 0;
  color: var(--nd-accent-text, var(--nd-accent));
  cursor: pointer;
  font: inherit;
  text-align: left;
}
.nt-linkish:hover { text-decoration: underline; text-underline-offset: 2px; }

/* end-align user bubbles helper already; stack end */
.nt-end {
  display: flex;
  justify-content: flex-end;
}

/* ── Wave 19ge — floor · webhooks · SSE inventory densify ── */
.nt-floor-img {
  display: block;
  width: 100%;
  max-height: min(56vh, 520px);
  object-fit: contain;
  border-radius: var(--nd-radius-md);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 14%, var(--nd-border-default));
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--nd-accent) 5%, transparent), transparent 40%),
    var(--nd-bg-inset);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--nd-text-primary) 4%, transparent);
}
.nt-floor-plan {
  position: relative;
  border-radius: var(--nd-radius-md);
  overflow: hidden;
}
.nt-floor-ap {
  position: absolute;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  border: 1px solid color-mix(in srgb, var(--nd-text-primary) 40%, transparent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--nd-bg-canvas) 50%, transparent);
  transform: translate(-50%, -50%);
}

.nt-webhook-row {
  display: grid;
  gap: 6px;
  padding: 10px 12px;
  border-radius: var(--nd-radius-md);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 10%, var(--nd-border-subtle));
  background: var(--nd-bg-raised);
  margin-bottom: 8px;
}
.nt-webhook-row[data-state='active'] {
  box-shadow: inset 3px 0 0 var(--nd-success);
}
.nt-webhook-row[data-state='failing'] {
  box-shadow: inset 3px 0 0 var(--nd-danger);
}
.nt-webhook-pre,
pre.nt-webhook-pre {
  font-family: var(--nd-font-mono);
  font-size: 11px;
  padding: 10px 12px;
  border-radius: var(--nd-radius-sm);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 10%, var(--nd-border-subtle));
  background: var(--nd-bg-inset);
  overflow: auto;
  max-height: 240px;
  color: var(--nd-text-secondary);
}

.nt-sse-banner {
  padding: 10px 12px;
  border-radius: var(--nd-radius-md);
  border: 1px solid color-mix(in srgb, var(--nd-warning) 28%, var(--nd-border-default));
  background: color-mix(in srgb, var(--nd-warning) 8%, var(--nd-bg-raised));
  margin-bottom: 10px;
  font-size: var(--nd-text-12);
}
.nt-sse-banner.nt-border-success,
.nt-border-success.nt-sse-banner {
  border-color: color-mix(in srgb, var(--nd-success) 32%, var(--nd-border-default));
  background: color-mix(in srgb, var(--nd-success) 8%, var(--nd-bg-raised));
}
.nt-sse-banner.nt-border-warning,
.nt-border-warning.nt-sse-banner {
  border-color: color-mix(in srgb, var(--nd-warning) 32%, var(--nd-border-default));
}
.nt-warn-box {
  padding: 10px 12px;
  border-radius: var(--nd-radius-md);
  border: 1px solid color-mix(in srgb, var(--nd-warning) 26%, var(--nd-border-default));
  background: color-mix(in srgb, var(--nd-warning) 7%, var(--nd-bg-raised));
