}
.nt-warn-text-125 {
  font-size: var(--nd-text-12);
  color: var(--nd-text-secondary);
  line-height: 1.45;
}
.nt-panel-skel {
  padding: 16px;
  border-radius: var(--nd-radius-md);
  border: 1px dashed color-mix(in srgb, var(--nd-accent) 16%, var(--nd-border-default));
  background: color-mix(in srgb, var(--nd-bg-inset) 40%, transparent);
}

.nt-end-gap-6,
.nt-end-wrap-10 {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  justify-content: flex-end;
  align-items: center;
}
.nt-end-wrap-10 { gap: 10px; }

html[data-nd-theme='light'] .nt-floor-img {
  background: var(--nd-bg-surface);
}

/* ── Wave 19gf — form controls · tables · tabs copper floor ── */
.nd-input,
.nd-select,
.nd-textarea,
input.nd-input,
select.nd-select,
textarea.nd-textarea {
  border-radius: var(--nd-radius-sm);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 12%, var(--nd-border-default));
  background: color-mix(in srgb, var(--nd-bg-inset) 55%, var(--nd-bg-raised));
  color: var(--nd-text-primary);
  transition: border-color 120ms ease, box-shadow 120ms ease;
}
.nd-input:hover,
.nd-select:hover,
.nd-textarea:hover {
  border-color: color-mix(in srgb, var(--nd-accent) 22%, var(--nd-border-default));
}
.nd-input:focus-visible,
.nd-select:focus-visible,
.nd-textarea:focus-visible {
  outline: none;
  border-color: color-mix(in srgb, var(--nd-accent) 55%, var(--nd-border-default));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--nd-accent) 18%, transparent);
}

.nd-btn,
button.nd-btn {
  border-radius: var(--nd-radius-sm);
  transition: background 120ms ease, border-color 120ms ease, box-shadow 120ms ease, transform 80ms ease;
}
.nd-btn--primary {
  background: linear-gradient(180deg, color-mix(in srgb, var(--nd-accent) 88%, var(--nd-text-primary)), var(--nd-accent));
  border-color: color-mix(in srgb, var(--nd-accent) 70%, var(--nd-border-default));
  color: var(--nd-bg-inset);
  font-weight: 600;
}
.nd-btn--primary:hover {
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--nd-accent) 40%, transparent), 0 8px 20px color-mix(in srgb, var(--nd-accent) 22%, transparent);
}
.nd-btn--primary:active { transform: translateY(1px); }

.nd-tabs__list {
  display: flex;
  gap: 2px;
  border-bottom: 1px solid color-mix(in srgb, var(--nd-accent) 10%, var(--nd-border-subtle));
  margin-bottom: 12px;
}
.nd-tabs__tab[aria-selected='true'],
.nd-tabs__tab[data-state='active'] {
  color: var(--nd-text-primary);
  box-shadow: inset 0 -2px 0 var(--nd-accent);
}

.nd-table {
  border-collapse: separate;
  border-spacing: 0;
  width: 100%;
}
.nd-table thead th {
  font-family: var(--nd-font-mono);
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--nd-text-muted);
  border-bottom: 1px solid color-mix(in srgb, var(--nd-accent) 12%, var(--nd-border-subtle));
  background: color-mix(in srgb, var(--nd-bg-raised) 92%, transparent);
  position: sticky;
  top: 0;
  z-index: 1;
}
.nd-table tbody tr:hover td {
  background: color-mix(in srgb, var(--nd-bg-hover) 40%, transparent);
}
.nd-table__tr--tone[data-tone='danger'] td:first-child,
.nd-table tbody tr[data-tone='danger'] td:first-child {
  box-shadow: inset 3px 0 0 var(--nd-danger);
}
.nd-table__tr--tone[data-tone='warning'] td:first-child,
.nd-table tbody tr[data-tone='warning'] td:first-child {
  box-shadow: inset 3px 0 0 var(--nd-warning);
}
.nd-table__tr--tone[data-tone='success'] td:first-child,
.nd-table tbody tr[data-tone='success'] td:first-child {
  box-shadow: inset 3px 0 0 color-mix(in srgb, var(--nd-success) 75%, transparent);
}

.nd-badge--plane,
.nd-badge[data-plane],
span.nd-badge.plane {
  background: color-mix(in srgb, var(--nd-bg-inset) 50%, var(--nd-bg-hover));
  color: var(--nd-text-secondary);
  border: 1px solid color-mix(in srgb, var(--nd-border-default) 80%, transparent);
  font-family: var(--nd-font-mono);
  font-size: 10px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

@media (prefers-reduced-motion: reduce) {
  .nd-btn--primary:active { transform: none; }
}
html[data-nd-theme='light'] .nd-input,
html[data-nd-theme='light'] .nd-select,
html[data-nd-theme='light'] .nd-textarea {
  background: var(--nd-bg-raised);
}

/* ── Wave 19gg — stat cards · sparkline · modal · menu elevation ── */
.nd-stat,
.nd-stat-card,
.nt-stat-card {
  padding: 12px 14px;
  border-radius: var(--nd-radius-md);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 12%, var(--nd-border-subtle));
  background:
    linear-gradient(165deg, color-mix(in srgb, var(--nd-accent) 7%, transparent), transparent 50%),
    var(--nd-bg-raised);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--nd-text-primary) 4%, transparent);
}
.nd-stat__label,
.nt-stat-card__label {
  font-family: var(--nd-font-mono);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--nd-text-muted);
}
.nd-stat__value,
.nt-stat-card__value {
  font-size: var(--nd-text-22, 1.35rem);
  font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--nd-text-primary);
  margin-top: 4px;
}
.nd-stat[data-tone='danger'],
.nt-stat-card[data-tone='danger'] {
  box-shadow: inset 3px 0 0 var(--nd-danger), inset 0 1px 0 color-mix(in srgb, var(--nd-text-primary) 4%, transparent);
}
.nd-stat[data-tone='warning'],
.nt-stat-card[data-tone='warning'] {
  box-shadow: inset 3px 0 0 var(--nd-warning), inset 0 1px 0 color-mix(in srgb, var(--nd-text-primary) 4%, transparent);
}
.nd-stat[data-tone='success'],
.nt-stat-card[data-tone='success'] {
  box-shadow: inset 3px 0 0 var(--nd-success), inset 0 1px 0 color-mix(in srgb, var(--nd-text-primary) 4%, transparent);
}

.nd-sparkline path,
.nt-sparkline path {
  stroke: color-mix(in srgb, var(--nd-accent) 80%, var(--nd-text-secondary));
  fill: none;
  stroke-width: 1.5;
}
.nd-sparkline[data-tone='danger'] path { stroke: var(--nd-danger); }
.nd-sparkline[data-tone='success'] path { stroke: var(--nd-success); }
.nd-sparkline[data-tone='warning'] path { stroke: var(--nd-warning); }

.nd-modal__panel,
.nd-dialog__panel {
  border: 1px solid color-mix(in srgb, var(--nd-accent) 20%, var(--nd-border-default));
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--nd-accent) 8%, transparent), transparent 40%),
    var(--nd-bg-raised);
  box-shadow:
    0 32px 90px color-mix(in srgb, var(--nd-bg-inset) 70%, transparent),
    inset 0 1px 0 color-mix(in srgb, var(--nd-text-primary) 6%, transparent);
  border-radius: var(--nd-radius-lg, 14px);
}
.nd-modal__header,
.nd-dialog__header {
  border-bottom: 1px solid color-mix(in srgb, var(--nd-accent) 10%, var(--nd-border-subtle));
}
.nd-modal__footer,
.nd-dialog__footer {
  border-top: 1px solid color-mix(in srgb, var(--nd-accent) 10%, var(--nd-border-subtle));
  background: color-mix(in srgb, var(--nd-bg-inset) 35%, transparent);
}

.nd-menu,
.nd-dropdown-menu {
  border: 1px solid color-mix(in srgb, var(--nd-accent) 16%, var(--nd-border-default));
  background: color-mix(in srgb, var(--nd-bg-raised) 96%, transparent);
  backdrop-filter: blur(12px);
  box-shadow: 0 16px 40px color-mix(in srgb, var(--nd-bg-inset) 50%, transparent);
  border-radius: var(--nd-radius-md);
  padding: 4px;
}
.nd-menu__item[data-active='true'],
.nd-menu__item[aria-selected='true'],
.nd-menu__item:focus-visible {
  background: color-mix(in srgb, var(--nd-accent) 14%, var(--nd-bg-hover));
  outline: none;
}
.nd-menu__item[data-danger='true'],
.nd-menu__item--danger {
  color: var(--nd-danger);
}

.nd-tooltip {
  border: 1px solid color-mix(in srgb, var(--nd-accent) 18%, var(--nd-border-default));
  background: color-mix(in srgb, var(--nd-bg-raised) 94%, var(--nd-bg-inset));
  color: var(--nd-text-primary);
  box-shadow: 0 10px 28px color-mix(in srgb, var(--nd-bg-inset) 45%, transparent);
  border-radius: var(--nd-radius-sm);
  font-size: 12px;
}

html[data-nd-theme='light'] .nd-stat,
html[data-nd-theme='light'] .nd-modal__panel {
  box-shadow: 0 12px 32px color-mix(in srgb, var(--nd-bg-inset) 12%, transparent);
}

/* ── Wave 19gh — rail nav · progress · skeleton · badge tones ── */
.nd-shell__rail .nd-nav-item,
.nd-rail__item,
a.nd-nav-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border-radius: var(--nd-radius-sm);
  color: var(--nd-text-secondary);
  text-decoration: none;
  border: 1px solid transparent;
  transition: background 100ms ease, color 100ms ease, border-color 100ms ease;
}
.nd-shell__rail .nd-nav-item:hover,
.nd-rail__item:hover,
a.nd-nav-item:hover {
  background: color-mix(in srgb, var(--nd-bg-hover) 55%, transparent);
  color: var(--nd-text-primary);
}
.nd-shell__rail .nd-nav-item[aria-current='page'],
.nd-rail__item[aria-current='page'],
.nd-nav-item--active {
  background: color-mix(in srgb, var(--nd-accent) 12%, var(--nd-bg-hover));
  color: var(--nd-text-primary);
  border-color: color-mix(in srgb, var(--nd-accent) 18%, transparent);
  box-shadow: inset 2px 0 0 var(--nd-accent);
}
.nd-shell__rail .nd-nav-group__label {
  font-family: var(--nd-font-mono);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--nd-text-muted);
  padding: 12px 10px 6px;
}

.nd-progress,
.nd-progress__track {
  height: 6px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--nd-bg-inset) 65%, var(--nd-border-subtle));
  overflow: hidden;
}
.nd-progress__fill {
  height: 100%;
  width: var(--nd-health, 0%);
  border-radius: inherit;
  background: linear-gradient(90deg, color-mix(in srgb, var(--nd-accent) 55%, var(--nd-success)), var(--nd-accent));
  transition: width 200ms ease;
}
.nd-progress__fill--success { background: var(--nd-success); }
.nd-progress__fill--warning { background: var(--nd-warning); }
.nd-progress__fill--danger { background: var(--nd-danger); }

.nd-skeleton {
  border-radius: var(--nd-radius-sm);
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--nd-bg-hover) 50%, transparent),
    color-mix(in srgb, var(--nd-accent) 10%, var(--nd-bg-hover)),
    color-mix(in srgb, var(--nd-bg-hover) 50%, transparent)
  );
  background-size: 200% 100%;
  animation: nd-skel 1.4s ease-in-out infinite;
}
@keyframes nd-skel {
  0% { background-position: 100% 0; }
  100% { background-position: -100% 0; }
}
@media (prefers-reduced-motion: reduce) {
  .nd-skeleton { animation: none; opacity: 0.7; }
  .nd-progress__fill { transition: none; }
}

.nd-badge[data-tone='danger'],
.nd-badge--danger { color: var(--nd-danger); border-color: color-mix(in srgb, var(--nd-danger) 35%, transparent); background: color-mix(in srgb, var(--nd-danger) 12%, transparent); }
.nd-badge[data-tone='warning'],
.nd-badge--warning { color: var(--nd-warning); border-color: color-mix(in srgb, var(--nd-warning) 35%, transparent); background: color-mix(in srgb, var(--nd-warning) 12%, transparent); }
.nd-badge[data-tone='success'],
.nd-badge--success { color: var(--nd-success); border-color: color-mix(in srgb, var(--nd-success) 35%, transparent); background: color-mix(in srgb, var(--nd-success) 12%, transparent); }
.nd-badge[data-tone='info'],
.nd-badge--info { color: var(--nd-info, var(--nd-accent)); border-color: color-mix(in srgb, var(--nd-info, var(--nd-accent)) 30%, transparent); background: color-mix(in srgb, var(--nd-info, var(--nd-accent)) 10%, transparent); }

/* topbar glass reinforce */
.nd-shell__topbar {
  backdrop-filter: blur(14px) saturate(1.15);
  background: color-mix(in srgb, var(--nd-bg-canvas) 72%, transparent);
  border-bottom: 1px solid color-mix(in srgb, var(--nd-accent) 12%, var(--nd-border-subtle));
  box-shadow: 0 1px 0 color-mix(in srgb, var(--nd-text-primary) 3%, transparent);
}

/* shift strip live pulse reinforce */
.nt-shift-strip[data-mode='live']::before,
.nd-shift-strip[data-mode='live']::before {
  content: '';
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--nd-success);
  box-shadow: 0 0 0 0 color-mix(in srgb, var(--nd-success) 50%, transparent);
  animation: nt-live-pulse 1.8s ease-out infinite;
  margin-right: 6px;
}
@keyframes nt-live-pulse {
  0% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--nd-success) 45%, transparent); }
  70% { box-shadow: 0 0 0 8px transparent; }
  100% { box-shadow: 0 0 0 0 transparent; }
}
@media (prefers-reduced-motion: reduce) {
  .nt-shift-strip[data-mode='live']::before,
  .nd-shift-strip[data-mode='live']::before { animation: none; }
}

html[data-nd-theme='light'] .nd-shell__topbar {
  background: color-mix(in srgb, var(--nd-bg-canvas) 88%, transparent);
}

/* ── Wave 19gi — shift strip mode rails ── */
.nt-shift-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 10px;
  align-items: center;
  padding: 8px 12px;
  border-radius: var(--nd-radius-md);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 14%, var(--nd-border-subtle));
  background: color-mix(in srgb, var(--nd-bg-raised) 78%, transparent);
  backdrop-filter: blur(12px) saturate(1.1);
  margin-bottom: 10px;
  font-size: 12px;
}
.nt-shift-strip--hot,
.nt-shift-strip[data-p1='1'] {
  border-color: color-mix(in srgb, var(--nd-danger) 35%, var(--nd-border-default));
  box-shadow: inset 3px 0 0 var(--nd-danger);
}
.nt-shift-strip[data-degraded='1']:not([data-p1='1']) {
  box-shadow: inset 3px 0 0 var(--nd-warning);
}
.nt-shift-strip__brand {
  font-family: var(--nd-font-mono);
  font-size: 10px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--nd-accent-text, var(--nd-accent));
  font-weight: 600;
}
.nt-shift-strip__chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 2px 8px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 12%, var(--nd-border-subtle));
  background: color-mix(in srgb, var(--nd-bg-inset) 40%, transparent);
  color: var(--nd-text-secondary);
}
.nt-shift-strip__dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--nd-text-muted);
}
.nt-shift-strip__dot--live {
  background: var(--nd-success);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--nd-success) 22%, transparent);
}
.nt-shift-strip__spacer { flex: 1; min-width: 8px; }
.nt-shift-strip__meta {
  font-family: var(--nd-font-mono);
  font-size: 11px;
  color: var(--nd-text-muted);
}

html[data-nd-theme='light'] .nt-shift-strip {
  background: color-mix(in srgb, var(--nd-bg-raised) 92%, transparent);
}

/* ── Wave 19gj — visual refs · maintenance · code/diff · kpi chips ── */
.nt-visual-ref,
.nt-visual-reference {
  border: 1px solid color-mix(in srgb, var(--nd-accent) 12%, var(--nd-border-subtle));
  border-radius: var(--nd-radius-md);
  background: var(--nd-bg-raised);
  padding: 12px;
  margin-top: 14px;
}
.nt-visual-ref__head,
.nt-visual-reference__head {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  margin-bottom: 10px;
  padding-bottom: 8px;
  border-bottom: 1px solid color-mix(in srgb, var(--nd-accent) 10%, var(--nd-border-subtle));
}
.nt-visual-ref__lane {
  display: grid;
  gap: 8px;
}
.nt-visual-ref__item {
  padding: 8px 10px;
  border-radius: var(--nd-radius-sm);
  border: 1px solid transparent;
  background: color-mix(in srgb, var(--nd-bg-inset) 35%, transparent);
}
.nt-visual-ref__item:hover {
  border-color: color-mix(in srgb, var(--nd-accent) 14%, transparent);
}

.nt-diff-code,
.nt-code-block,
pre.nt-diff-code {
  font-family: var(--nd-font-mono);
  font-size: 11.5px;
  line-height: 1.45;
  padding: 12px 14px;
  border-radius: var(--nd-radius-md);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 12%, var(--nd-border-subtle));
  background: var(--nd-bg-inset);
  overflow: auto;
  max-height: min(50vh, 480px);
  color: var(--nd-text-secondary);
  white-space: pre-wrap;
}
.nt-diff-code .add,
.nt-diff-line--add { color: var(--nd-success); }
.nt-diff-code .del,
.nt-diff-line--del { color: var(--nd-danger); }

.nt-kpi-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 14%, var(--nd-border-subtle));
  background: color-mix(in srgb, var(--nd-bg-inset) 40%, transparent);
  font-family: var(--nd-font-mono);
  font-size: 11px;
  color: var(--nd-text-secondary);
}
.nt-kpi-chip[data-tone='danger'] {
  border-color: color-mix(in srgb, var(--nd-danger) 30%, transparent);
  color: var(--nd-danger);
  background: color-mix(in srgb, var(--nd-danger) 10%, transparent);
}
.nt-kpi-chip[data-tone='warning'] {
  border-color: color-mix(in srgb, var(--nd-warning) 30%, transparent);
  color: var(--nd-warning);
}
.nt-kpi-chip[data-tone='success'] {
  border-color: color-mix(in srgb, var(--nd-success) 30%, transparent);
  color: var(--nd-success);
}

/* maintenance windows */
.nt-maint-row,
.nt-maintenance-row {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 8px;
  padding: 10px 12px;
  border-radius: var(--nd-radius-md);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 10%, var(--nd-border-subtle));
  background: var(--nd-bg-raised);
  margin-bottom: 8px;
}
.nt-maint-row[data-active='true'] {
  box-shadow: inset 3px 0 0 var(--nd-info, var(--nd-accent));
  border-color: color-mix(in srgb, var(--nd-accent) 22%, var(--nd-border-default));
}

/* card default elevation ladder */
.nd-card,
.nt-card {
  border: 1px solid color-mix(in srgb, var(--nd-accent) 10%, var(--nd-border-subtle));
  background: var(--nd-bg-raised);
  border-radius: var(--nd-radius-md);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--nd-text-primary) 3%, transparent);
}
.nd-card:hover {
  border-color: color-mix(in srgb, var(--nd-accent) 18%, var(--nd-border-default));
}

html[data-nd-theme='light'] .nt-diff-code,
html[data-nd-theme='light'] pre.nt-diff-code {
  background: var(--nd-bg-surface);
}

/* ── Wave 19gk — screen header actions · loading veil · hop cleanup guard ── */
.nt-screen-header {
  display: flex;
  flex-wrap: wrap;
  gap: 12px 16px;
  align-items: flex-start;
  justify-content: space-between;
  padding-bottom: 12px;
  margin-bottom: 8px;
  border-bottom: 1px solid transparent;
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--nd-accent) 55%, transparent), transparent 42%) bottom / 100% 1px no-repeat;
}
.nt-screen-header__titles {
  min-width: 0;
  flex: 1;
}
.nt-screen-header__title {
  margin: 0;
  font-size: clamp(1.25rem, 1.8vw, 1.55rem);
  font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--nd-text-primary);
}
.nt-screen-header__subtitle {
  margin: 4px 0 0;
  color: var(--nd-text-secondary);
  font-size: var(--nd-text-13);
  max-width: 62ch;
  line-height: 1.45;
}
.nt-screen-header__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  justify-content: flex-end;
}

/* loading veil over panels */
.nt-loading-veil,
[aria-busy='true'].nt-panel-busy {
  position: relative;
}
.nt-loading-veil::after,
[aria-busy='true'].nt-panel-busy::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: color-mix(in srgb, var(--nd-bg-canvas) 35%, transparent);
  pointer-events: none;
}

/* divider utility */
.nt-rule,
.nt-divider {
  height: 1px;
  border: 0;
  background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--nd-accent) 28%, var(--nd-border-subtle)), transparent);
  margin: 12px 0;
}

/* pill filters */
.nt-pill-filter,
.nt-chip-filter {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 12%, var(--nd-border-subtle));
  background: transparent;
  color: var(--nd-text-secondary);
  font-size: 12px;
  cursor: pointer;
}
.nt-pill-filter[aria-pressed='true'],
.nt-pill-filter[data-active='true'],
.nt-chip-filter[aria-pressed='true'] {
  background: color-mix(in srgb, var(--nd-accent) 14%, var(--nd-bg-hover));
  border-color: color-mix(in srgb, var(--nd-accent) 28%, var(--nd-border-default));
  color: var(--nd-text-primary);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--nd-accent) 10%, transparent);
}

/* offline / degraded banner */
.nt-banner-degraded,
.nt-banner-offline {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  padding: 10px 12px;
  border-radius: var(--nd-radius-md);
  margin-bottom: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-warning) 30%, var(--nd-border-default));
  background: color-mix(in srgb, var(--nd-warning) 9%, var(--nd-bg-raised));
}
.nt-banner-offline {
  border-color: color-mix(in srgb, var(--nd-danger) 30%, var(--nd-border-default));
  background: color-mix(in srgb, var(--nd-danger) 9%, var(--nd-bg-raised));
}

html[data-nd-theme='light'] .nt-screen-header {
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--nd-accent) 45%, transparent), transparent 42%) bottom / 100% 1px no-repeat;
}

/* ── Wave 19gl — screen header real BEM densify ── */
.nt-screen-header__copy {
  min-width: 0;
  flex: 1;
}
.nt-screen-header__brand {
  margin: 0 0 4px;
  font-family: var(--nd-font-mono);
  font-size: 10px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--nd-accent-text);
}
.nt-screen-header__overline {
  margin: 0 0 6px;
  font-family: var(--nd-font-mono);
  font-size: 11px;
  letter-spacing: 0.08em;
  color: var(--nd-text-muted);
}
.nt-screen-header[data-path] .nt-screen-header__overline {
  opacity: 0.92;
}

/* elevation shadows as utilities */
.nt-elev-1 {
  box-shadow: 0 1px 0 color-mix(in srgb, var(--nd-text-primary) 4%, transparent),
    0 8px 20px color-mix(in srgb, var(--nd-bg-inset) 25%, transparent);
}
.nt-elev-2 {
  box-shadow: 0 1px 0 color-mix(in srgb, var(--nd-text-primary) 5%, transparent),
    0 16px 40px color-mix(in srgb, var(--nd-bg-inset) 40%, transparent);
}
.nt-elev-3 {
  box-shadow: 0 1px 0 color-mix(in srgb, var(--nd-text-primary) 6%, transparent),
    0 28px 72px color-mix(in srgb, var(--nd-bg-inset) 55%, transparent);
}

/* glass utility */
.nt-glass {
  background: var(--nd-bg-glass, color-mix(in srgb, var(--nd-bg-canvas) 74%, transparent));
  backdrop-filter: blur(12px) saturate(1.1);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 12%, var(--nd-border-subtle));
}

/* prose density for long notes */
.nt-prose-sm {
  font-size: var(--nd-text-13);
  line-height: var(--nd-leading-body);
  color: var(--nd-text-secondary);
  max-width: 68ch;
}
.nt-prose-sm strong { color: var(--nd-text-primary); font-weight: 600; }
.nt-prose-sm code {
  font-family: var(--nd-font-mono);
  font-size: 0.92em;
  padding: 1px 5px;
  border-radius: 4px;
  background: color-mix(in srgb, var(--nd-bg-inset) 60%, transparent);
  border: 1px solid color-mix(in srgb, var(--nd-border-subtle) 80%, transparent);
}

/* ── Wave 19gm — consume elevation tokens · z ladder · motion ── */
.nd-card,
.nt-card,
.nt-metric-tile,
.nt-configure__col,
.nt-tickets__workspace,
.nt-device-layout__rail {
  box-shadow: var(--nd-shadow-soft), var(--nd-shadow-sm);
}
.nd-modal__panel,
.nd-dialog__panel,
.nd-cmdk,
.nt-cmdk,
.nt-auth-card {
  box-shadow: var(--nd-shadow-overlay);
  transition: box-shadow var(--nd-duration-base) var(--nd-ease);
}
.nd-menu,
.nd-dropdown-menu,
.nd-tooltip {
  z-index: var(--nd-z-dropdown);
  box-shadow: var(--nd-shadow-raised);
}
.nd-toast {
  z-index: var(--nd-z-toast);
}
.nd-shell__topbar {
  z-index: var(--nd-z-topbar);
}
.nt-shift-strip {
  z-index: var(--nd-z-shift);
}
.nt-filter-bar.nt-sticky-filters,
.nt-bulk-bar {
  z-index: var(--nd-z-sticky);
}
.nt-chat-fab,
button.nt-chat-fab {
  z-index: calc(var(--nd-z-topbar) + 10);
  transition: transform var(--nd-duration-fast) var(--nd-ease), border-color var(--nd-duration-fast) var(--nd-ease);
}
.nd-btn,
button.nd-btn,
.nt-configure-row,
.nt-plane-mini,
.nt-license-row {
  transition:
    background var(--nd-duration-fast) var(--nd-ease),
    border-color var(--nd-duration-fast) var(--nd-ease),
    box-shadow var(--nd-duration-fast) var(--nd-ease),
    transform var(--nd-duration-fast) var(--nd-ease);
}
.nt-recon-reveal {
  animation: nt-recon-in var(--nd-duration-slow) var(--nd-ease) both;
}

/* copper glow on primary focus surfaces */
.nd-btn--primary:focus-visible {
  box-shadow: var(--nd-shadow-glow);
}
.nd-input:focus-visible,
.nd-select:focus-visible,
.nd-textarea:focus-visible {
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--nd-ring-color) 55%, transparent);
}

/* content padding from tokens */
.nd-shell__content {
  padding: var(--nd-content-pad-y) var(--nd-content-pad-x);
  gap: var(--nd-screen-gap);
}

html[data-nd-theme='light'] .nd-card,
html[data-nd-theme='light'] .nt-card {
  box-shadow: var(--nd-shadow-sm);
}

/* ── Wave 19gn — topology 2D/3D cinema densify ── */
.nt-topo3d {
  position: relative;
  min-height: min(62vh, 640px);
  border-radius: var(--nd-radius-lg);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 16%, var(--nd-border-default));
  overflow: hidden;
  background:
    radial-gradient(70% 60% at 50% 0%, color-mix(in srgb, var(--nd-accent) 12%, transparent), transparent 55%),
    var(--nd-bg-inset);
  box-shadow: var(--nd-shadow-raised);
}
.nt-topo3d__brand {
  position: absolute;
  top: 10px;
  left: 12px;
  z-index: 2;
  font-family: var(--nd-font-mono);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--nd-accent-text) 85%, var(--nd-text-muted));
  pointer-events: none;
}
.nt-topo3d__canvas {
  width: 100%;
  height: min(62vh, 640px);
  display: block;
}
.nt-topo3d__glass {
  position: absolute;
  z-index: 2;
  padding: 10px 12px;
  border-radius: var(--nd-radius-md);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 18%, var(--nd-border-default));
  background: var(--nd-bg-glass-strong, color-mix(in srgb, var(--nd-bg-raised) 92%, transparent));
  backdrop-filter: blur(12px);
  box-shadow: var(--nd-shadow-sm);
  max-width: min(280px, 70%);
}
.nt-topo3d__glass--tl { top: 36px; left: 12px; }
.nt-topo3d__glass--tr { top: 12px; right: 12px; }
.nt-topo3d__glass--bl { bottom: 12px; left: 12px; }
.nt-topo3d__title {
  font-weight: 600;
  color: var(--nd-text-primary);
  margin-bottom: 2px;
}
.nt-topo3d__meta {
  font-size: 12px;
  color: var(--nd-text-secondary);
}

.nt-topo-node-card {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 140px;
  max-width: 200px;
  padding: 8px 10px;
  border-radius: var(--nd-radius-md);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 14%, var(--nd-border-default));
  background: color-mix(in srgb, var(--nd-bg-raised) 92%, transparent);
  box-shadow: var(--nd-shadow-sm);
  color: inherit;
  text-align: left;
  cursor: pointer;
}
.nt-topo-node-card:hover,
.nt-topo-node-card:focus-visible {
  border-color: color-mix(in srgb, var(--nd-accent) 32%, var(--nd-border-default));
  box-shadow: var(--nd-shadow-glow);
  outline: none;
}
.nt-topo-node-card--danger {
  box-shadow: inset 3px 0 0 var(--nd-danger), var(--nd-shadow-sm);
}
.nt-topo-node-card--warning {
  box-shadow: inset 3px 0 0 var(--nd-warning), var(--nd-shadow-sm);
