  font-weight: 600;
}
.nt-status-dot,
.nd-badge__dot.nt-status-dot {
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: currentColor;
  box-shadow: 0 0 0 2px color-mix(in srgb, currentColor 22%, transparent);
}
.nt-status-dot[data-tone='success'] { color: var(--nd-success); background: var(--nd-success); }
.nt-status-dot[data-tone='danger'] { color: var(--nd-danger); background: var(--nd-danger); }
.nt-status-dot[data-tone='warning'] { color: var(--nd-warning); background: var(--nd-warning); }
.nt-status-dot[data-tone='info'] { color: var(--nd-info, var(--nd-accent)); background: var(--nd-info, var(--nd-accent)); }
.nt-text-link,
.nd-link.nt-text-link {
  color: var(--nd-accent-text, var(--nd-accent));
  text-decoration: none;
  border-bottom: 1px solid color-mix(in srgb, var(--nd-accent) 35%, transparent);
  transition: color 140ms var(--nd-ease, ease), border-color 140ms var(--nd-ease, ease);
}
.nt-text-link:hover,
.nd-link.nt-text-link:hover {
  color: var(--nd-text-primary);
  border-bottom-color: color-mix(in srgb, var(--nd-accent) 70%, transparent);
}
html[data-nd-theme='light'] .nt-toast,
html[data-nd-theme='light'] .nd-toast.nt-toast,
html[data-nd-theme='light'] .nt-modal-panel,
html[data-nd-theme='light'] .nd-modal.nt-modal-panel {
  background: linear-gradient(165deg, color-mix(in srgb, var(--nd-surface-0, white) 72%, var(--nd-surface-1)), var(--nd-surface-1));
}

/* ── ** ── ** Wave 20jc — ** callout glass · stat tiles ── ** ── */
.nt-callout-glass,
.nd-alert.nt-callout-glass {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 14px;
  border-radius: var(--nd-radius-md, 10px);
  border: 1px solid color-mix(in srgb, var(--nd-border) 80%, transparent);
  background:
    linear-gradient(165deg, color-mix(in srgb, var(--nd-surface-2) 88%, transparent), var(--nd-surface-1));
  box-shadow: inset 3px 0 0 color-mix(in srgb, var(--nd-accent) 55%, transparent);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}
.nt-callout-glass[data-tone='success'],
.nd-alert--success.nt-callout-glass {
  box-shadow: inset 3px 0 0 var(--nd-success);
}
.nt-callout-glass[data-tone='danger'],
.nd-alert--danger.nt-callout-glass {
  box-shadow: inset 3px 0 0 var(--nd-danger);
}
.nt-callout-glass[data-tone='warning'],
.nd-alert--warning.nt-callout-glass {
  box-shadow: inset 3px 0 0 var(--nd-warning);
}
.nt-callout-glass[data-tone='info'],
.nd-alert--info.nt-callout-glass {
  box-shadow: inset 3px 0 0 var(--nd-info, var(--nd-accent));
}
.nt-callout-glass__title,
.nd-alert__title.nt-callout-glass__title {
  font-weight: 650;
  color: var(--nd-text-primary);
  font-size: var(--nd-text-13, 13px);
}
.nt-callout-glass__body,
.nd-alert__body.nt-callout-glass__body {
  margin-top: 2px;
  color: var(--nd-text-secondary);
  font-size: var(--nd-text-12, 12px);
  line-height: 1.45;
}
.nt-callout-glass__dismiss,
.nd-alert__dismiss.nt-callout-glass__dismiss {
  flex-shrink: 0;
  font-size: var(--nd-text-11, 11px);
  color: var(--nd-text-muted);
  background: transparent;
  border: 0;
  cursor: pointer;
  text-decoration: underline;
  text-underline-offset: 2px;
}
.nt-stat-tile,
.nd-stat.nt-stat-tile {
  position: relative;
  padding: 12px 14px 14px;
  border-radius: var(--nd-radius-md, 10px);
  border: 1px solid color-mix(in srgb, var(--nd-border) 78%, transparent);
  background:
    linear-gradient(165deg, color-mix(in srgb, var(--nd-surface-2) 70%, transparent), var(--nd-surface-1));
  box-shadow: var(--nd-shadow-sm);
  overflow: hidden;
  transition: border-color 160ms var(--nd-ease, ease), box-shadow 160ms var(--nd-ease, ease);
}
.nt-stat-tile:hover,
.nd-stat.nt-stat-tile:hover {
  border-color: color-mix(in srgb, var(--nd-accent) 26%, var(--nd-border));
  box-shadow:
    var(--nd-shadow-sm),
    0 0 0 1px color-mix(in srgb, var(--nd-accent) 10%, transparent);
}
.nd-stat.nt-stat-tile .nd-stat__rule,
.nt-metric-tile__rule {
  height: 2px;
  width: 28px;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--nd-accent), transparent);
  margin-bottom: 10px;
}
.nd-stat.nt-stat-tile .nd-stat__value,
.nt-stat-tile .nt-metric-tile__v {
  font-size: var(--nd-text-22, 22px);
  font-weight: 650;
  letter-spacing: -0.02em;
  color: var(--nd-text-primary);
  line-height: 1.15;
}
.nd-stat.nt-stat-tile .nd-stat__delta--positive {
  color: var(--nd-success);
}
.nd-stat.nt-stat-tile .nd-stat__delta--negative {
  color: var(--nd-danger);
}
html[data-nd-theme='light'] .nt-callout-glass,
html[data-nd-theme='light'] .nd-alert.nt-callout-glass,
html[data-nd-theme='light'] .nt-stat-tile,
html[data-nd-theme='light'] .nd-stat.nt-stat-tile {
  background: linear-gradient(165deg, color-mix(in srgb, var(--nd-surface-0, white) 70%, var(--nd-surface-1)), var(--nd-surface-1));
}

/* ── ** ── ** Wave 20jd — ** controls field polish ── ** ── */
.nt-btn,
.nd-btn.nt-btn {
  border-radius: 999px;
  font-weight: 600;
  letter-spacing: 0.01em;
  transition:
    background 140ms var(--nd-ease, ease),
    border-color 140ms var(--nd-ease, ease),
    box-shadow 140ms var(--nd-ease, ease),
    color 140ms var(--nd-ease, ease),
    transform 140ms var(--nd-ease, ease);
}
.nt-btn:active:not(:disabled),
.nd-btn.nt-btn:active:not(:disabled) {
  transform: translateY(1px);
}
.nd-btn--primary.nt-btn {
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--nd-accent) 35%, transparent),
    0 8px 22px color-mix(in srgb, var(--nd-accent) 18%, transparent);
}
.nd-btn--primary.nt-btn:hover:not(:disabled) {
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--nd-accent) 50%, transparent),
    0 10px 28px color-mix(in srgb, var(--nd-accent) 26%, transparent);
}
.nt-field,
.nd-input.nt-field,
.nd-select.nt-field,
.nd-textarea.nt-field {
  border-radius: var(--nd-radius-sm, 8px);
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2) 88%, transparent);
  transition:
    border-color 140ms var(--nd-ease, ease),
    box-shadow 140ms var(--nd-ease, ease),
    background 140ms var(--nd-ease, ease);
}
.nt-field:hover:not(:disabled):not(:focus),
.nd-input.nt-field:hover:not(:disabled):not(:focus),
.nd-select.nt-field:hover:not(:disabled):not(:focus) {
  border-color: color-mix(in srgb, var(--nd-border) 70%, var(--nd-accent) 20%);
}
.nt-field:focus,
.nt-field:focus-visible,
.nd-input.nt-field:focus,
.nd-input.nt-field:focus-visible,
.nd-select.nt-field:focus,
.nd-select.nt-field:focus-visible,
.nd-textarea.nt-field:focus,
.nd-textarea.nt-field:focus-visible {
  outline: none;
  border-color: color-mix(in srgb, var(--nd-accent) 55%, var(--nd-border));
  box-shadow: var(--nd-focus-ring, 0 0 0 3px color-mix(in srgb, var(--nd-accent) 28%, transparent));
  background: color-mix(in srgb, var(--nd-surface-1) 92%, transparent);
}
.nt-field--area,
.nd-textarea.nt-field--area {
  min-height: 88px;
  line-height: 1.45;
  resize: vertical;
}
.nt-select-wrap,
.nd-select-wrap.nt-select-wrap {
  position: relative;
  display: inline-flex;
  min-width: 0;
}
.nt-select-wrap::after,
.nd-select-wrap.nt-select-wrap::after {
  content: '';
  position: absolute;
  right: 10px;
  top: 50%;
  width: 6px;
  height: 6px;
  border-right: 1.5px solid var(--nd-text-muted);
  border-bottom: 1.5px solid var(--nd-text-muted);
  transform: translateY(-65%) rotate(45deg);
  pointer-events: none;
  opacity: 0.85;
}
.nt-check,
.nd-checkbox.nt-check {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  color: var(--nd-text-secondary);
  font-size: var(--nd-text-13, 13px);
}
.nt-check input,
.nd-checkbox.nt-check input {
  accent-color: var(--nd-accent);
  width: 14px;
  height: 14px;
}
.nt-switch,
.nd-switch.nt-switch {
  --nt-switch-track: color-mix(in srgb, var(--nd-surface-3) 80%, transparent);
  --nt-switch-on: var(--nd-accent);
}
html[data-nd-theme='light'] .nt-field,
html[data-nd-theme='light'] .nd-input.nt-field,
html[data-nd-theme='light'] .nd-select.nt-field,
html[data-nd-theme='light'] .nd-textarea.nt-field {
  background: color-mix(in srgb, var(--nd-surface-0, white) 78%, var(--nd-surface-1));
}

/* ── ** ── ** Wave 20je — ** tooltip · tabs · quiet empty ── ** ── */
.nt-tooltip,
.nd-tooltip.nt-tooltip {
  position: relative;
  display: inline-flex;
  max-width: 100%;
}
.nt-tooltip__bubble,
.nd-tooltip__bubble.nt-tooltip__bubble {
  position: absolute;
  z-index: var(--nd-z-tooltip, 90);
  left: 50%;
  transform: translateX(-50%);
  min-width: max-content;
  max-width: min(280px, 70vw);
  padding: 6px 9px;
  border-radius: 8px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 80%, var(--nd-accent) 14%);
  background:
    linear-gradient(165deg, color-mix(in srgb, var(--nd-surface-3) 88%, transparent), var(--nd-surface-2));
  color: var(--nd-text-primary);
  font-size: var(--nd-text-11, 11px);
  line-height: 1.35;
  box-shadow:
    var(--nd-shadow-md, 0 10px 28px color-mix(in srgb, var(--nd-ink, black) 42%, transparent)),
    0 0 0 1px color-mix(in srgb, var(--nd-accent) 10%, transparent);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  pointer-events: none;
}
.nd-tooltip__bubble--top.nt-tooltip__bubble { bottom: calc(100% + 8px); }
.nd-tooltip__bubble--bottom.nt-tooltip__bubble { top: calc(100% + 8px); }
.nt-tabs,
.nd-tabs.nt-tabs {
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-width: 0;
}
.nt-nothing-reported {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 10px 12px;
  border-radius: var(--nd-radius-md, 10px);
  border: 1px dashed color-mix(in srgb, var(--nd-border) 75%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2) 45%, transparent);
}
.nt-nothing-reported__mark {
  flex-shrink: 0;
  width: 22px;
  height: 22px;
  border-radius: 7px;
  display: inline-grid;
  place-items: center;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: color-mix(in srgb, var(--nd-accent-text, var(--nd-accent)) 85%, var(--nd-text-primary));
  background: color-mix(in srgb, var(--nd-accent) 16%, transparent);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 28%, transparent);
}
.nt-progress-rail__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 6px;
}
.nt-progress-rail__note,
.nd-progress__note.nt-progress-rail__note {
  font-family: var(--nd-font-mono);
  font-size: var(--nd-text-11, 11px);
  color: var(--nd-text-muted);
}
/* license row copper rail */
.nt-license-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  border-radius: var(--nd-radius-md, 10px);
  border: 1px solid color-mix(in srgb, var(--nd-border) 78%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 88%, transparent);
  transition: border-color 140ms var(--nd-ease, ease), box-shadow 140ms var(--nd-ease, ease);
}
.nt-license-row:hover {
  border-color: color-mix(in srgb, var(--nd-accent) 24%, var(--nd-border));
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--nd-accent) 10%, transparent);
}
html[data-nd-theme='light'] .nt-tooltip__bubble,
html[data-nd-theme='light'] .nd-tooltip__bubble.nt-tooltip__bubble {
  background: color-mix(in srgb, var(--nd-surface-0, white) 82%, var(--nd-surface-2));
}
html[data-nd-theme='light'] .nt-nothing-reported {
  background: color-mix(in srgb, var(--nd-surface-0, white) 70%, var(--nd-surface-1));
}

/* ── ** ── ** Wave 20jf — ** avatar · spinner · menu glass ── ** ── */
.nt-avatar,
.nd-avatar.nt-avatar {
  display: inline-grid;
  place-items: center;
  border-radius: 999px;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--nd-text-primary);
  background:
    radial-gradient(circle at 30% 25%, color-mix(in srgb, var(--nd-accent) 28%, transparent), transparent 55%),
    color-mix(in srgb, var(--nd-surface-3) 85%, transparent);
  border: 1px solid color-mix(in srgb, var(--nd-border) 80%, var(--nd-accent) 16%);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--nd-accent) 12%, transparent);
}
.nt-spinner,
.nd-spinner.nt-spinner {
  display: inline-block;
  border-radius: 999px;
  border: 2px solid color-mix(in srgb, var(--nd-border) 75%, transparent);
  border-top-color: var(--nd-accent);
  animation: nt-spin 0.7s linear infinite;
}
@keyframes nt-spin {
  to { transform: rotate(360deg); }
}
.nt-menu,
.nd-menu.nt-menu {
  position: relative;
  display: inline-flex;
}
.nt-menu__panel,
.nd-menu__panel.nt-menu__panel {
  min-width: 168px;
  padding: 6px;
  border-radius: var(--nd-radius-md, 10px);
  border: 1px solid color-mix(in srgb, var(--nd-border) 82%, var(--nd-accent) 12%);
  background:
    linear-gradient(165deg, color-mix(in srgb, var(--nd-surface-2) 92%, transparent), var(--nd-surface-1));
  box-shadow:
    var(--nd-shadow-lg, 0 18px 48px color-mix(in srgb, var(--nd-ink, black) 45%, transparent)),
    0 0 0 1px color-mix(in srgb, var(--nd-accent) 10%, transparent);
  backdrop-filter: blur(12px) saturate(1.06);
  -webkit-backdrop-filter: blur(12px) saturate(1.06);
  z-index: var(--nd-z-menu, 60);
}
.nt-menu__item,
.nd-menu__item.nt-menu__item {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  text-align: left;
  border: 0;
  background: transparent;
  color: var(--nd-text-primary);
  font: inherit;
  font-size: var(--nd-text-13, 13px);
  padding: 8px 10px;
  border-radius: 8px;
  cursor: pointer;
}
.nt-menu__item:hover,
.nd-menu__item.nt-menu__item:hover {
  background: color-mix(in srgb, var(--nd-accent) 12%, transparent);
}
.nd-menu__item--danger.nt-menu__item {
  color: var(--nd-danger-text, var(--nd-danger));
}
.nt-menu__sep,
.nd-menu__sep.nt-menu__sep {
  height: 1px;
  margin: 5px 6px;
  background: color-mix(in srgb, var(--nd-border) 80%, transparent);
}
html[data-nd-theme='light'] .nt-menu__panel,
html[data-nd-theme='light'] .nd-menu__panel.nt-menu__panel {
  background: linear-gradient(165deg, color-mix(in srgb, var(--nd-surface-0, white) 78%, var(--nd-surface-1)), var(--nd-surface-1));
}

/* ── ** ── ** Wave 20jg — ** inventory · reco · topo surface ── ** ── */
.nt-inventory {
  display: flex;
  flex-direction: column;
  gap: var(--nd-space-4, 16px);
  min-width: 0;
}
.nt-inventory__search {
  padding: 12px 14px;
  border-radius: var(--nd-radius-lg, 14px);
  border: 1px solid color-mix(in srgb, var(--nd-border) 80%, transparent);
  background:
    linear-gradient(165deg, color-mix(in srgb, var(--nd-surface-2) 75%, transparent), var(--nd-surface-1));
  box-shadow: var(--nd-shadow-sm);
}
.nt-inventory-result {
  display: flex;
  width: 100%;
  text-align: left;
  gap: 10px;
  padding: 10px 12px;
  border-radius: 10px;
  border: 1px solid transparent;
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
}
.nt-inventory-result:hover,
.nt-inventory-result:focus-visible {
  border-color: color-mix(in srgb, var(--nd-accent) 28%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-accent) 8%, transparent);
  outline: none;
}
.nt-inventory__tree-panel,
.nt-inventory__detail {
  border-radius: var(--nd-radius-lg, 14px);
  border: 1px solid color-mix(in srgb, var(--nd-border) 78%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 92%, transparent);
  box-shadow: var(--nd-shadow-sm);
  min-width: 0;
  overflow: hidden;
}
.nt-inventory__panel-head {
  padding: 10px 14px;
  border-bottom: 1px solid color-mix(in srgb, var(--nd-border) 75%, transparent);
  background: linear-gradient(180deg, color-mix(in srgb, var(--nd-surface-2) 55%, transparent), transparent);
  font-size: var(--nd-text-12, 12px);
  font-weight: 650;
  color: var(--nd-text-secondary);
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.nt-inventory__panel-body {
  padding: 10px 12px 14px;
}
.nt-api-error {
  display: flex;
  flex-direction: column;
  gap: 14px;
  max-width: 520px;
  margin: 12vh auto 0;
  padding: 18px;
  border-radius: var(--nd-radius-lg, 14px);
  border: 1px solid color-mix(in srgb, var(--nd-danger) 28%, var(--nd-border));
  background:
    linear-gradient(165deg, color-mix(in srgb, var(--nd-surface-2) 88%, transparent), var(--nd-surface-1));
  box-shadow:
    var(--nd-shadow-md),
    inset 3px 0 0 var(--nd-danger);
}
.nt-api-error__kicker {
  font-size: var(--nd-text-10, 10px);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--nd-text-muted);
}
.nt-topo-surface {
  min-width: 0;
}
.nt-topo-node-card {
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 80%, transparent);
  background:
    linear-gradient(165deg, color-mix(in srgb, var(--nd-surface-2) 70%, transparent), var(--nd-surface-1));
  box-shadow: var(--nd-shadow-sm);
  transition: border-color 140ms var(--nd-ease, ease), box-shadow 140ms var(--nd-ease, ease);
}
.nt-topo-node-card:hover {
  border-color: color-mix(in srgb, var(--nd-accent) 26%, var(--nd-border));
  box-shadow:
    var(--nd-shadow-sm),
    0 0 0 1px color-mix(in srgb, var(--nd-accent) 12%, transparent);
}
.nt-topo-node-card--danger {
  box-shadow: inset 3px 0 0 var(--nd-danger);
}
.nt-topo-node-card--warning {
  box-shadow: inset 3px 0 0 var(--nd-warning);
}
.nt-topo-diagram {
  border-radius: var(--nd-radius-lg, 14px);
  border: 1px solid color-mix(in srgb, var(--nd-border) 78%, transparent);
  background:
    radial-gradient(circle at 20% 0%, color-mix(in srgb, var(--nd-accent) 8%, transparent), transparent 42%),
    color-mix(in srgb, var(--nd-surface-2) 55%, var(--nd-surface-1));
}
html[data-nd-theme='light'] .nt-inventory__search,
html[data-nd-theme='light'] .nt-api-error,
html[data-nd-theme='light'] .nt-topo-node-card {
  background: linear-gradient(165deg, color-mix(in srgb, var(--nd-surface-0, white) 72%, var(--nd-surface-1)), var(--nd-surface-1));
}

/* ── ** ── ** Wave 20jh — ** chat cinema densify ── ** ── */
.nt-chat-col {
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-height: 0;
  min-width: 0;
}
.nt-chat-scroll {
  flex: 1;
  min-height: 0;
  overflow: auto;
  padding: 4px 2px 12px;
  scroll-behavior: smooth;
}
.nt-chat-bubble {
  max-width: min(560px, 92%);
  padding: 10px 12px;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 80%, transparent);
  line-height: 1.45;
  font-size: var(--nd-text-12, 12px);
}
.nt-chat-bubble--user {
  margin-left: auto;
  background:
    linear-gradient(165deg, color-mix(in srgb, var(--nd-accent) 18%, var(--nd-surface-2)), var(--nd-surface-2));
  border-color: color-mix(in srgb, var(--nd-accent) 28%, var(--nd-border));
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--nd-accent) 10%, transparent);
