/* ── ** ── ** Wave 20jx — ** pagination · device cinema · mist shell ── ** ── */
.nt-pagination.nd-pagination,
.nd-pagination.nt-pagination {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 6px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 70%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 70%, transparent);
}
.nt-pagebtn.nd-pagebtn,
.nd-pagebtn.nt-pagebtn {
  appearance: none;
  min-width: 32px;
  height: 32px;
  padding: 0 8px;
  border-radius: 999px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--nd-text-muted);
  font: inherit;
  font-size: var(--nd-text-12, 12px);
  font-variant-numeric: tabular-nums;
  cursor: pointer;
  transition: background 120ms var(--nd-ease, ease), color 120ms var(--nd-ease, ease), border-color 120ms var(--nd-ease, ease);
}
.nt-pagebtn:hover:not(:disabled),
.nd-pagebtn:hover:not(:disabled) {
