}
.nt-pagebtn:disabled,
.nd-pagebtn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.nt-pagebtn--current,
.nd-pagebtn--current {
  color: var(--nd-ink-on-accent, var(--nd-surface-0, white));
  background: color-mix(in srgb, var(--nd-accent) 88%, var(--nd-surface-2));
  border-color: color-mix(in srgb, var(--nd-accent) 50%, transparent);
  font-weight: 600;
}
.nt-pagination__gap {
  opacity: 0.45;
  padding: 0 4px;
  user-select: none;
}
.nt-device-detail-shell {
  min-width: 0;
  gap: 14px;
}
.nt-device-hero.nt-panel-glass {
  padding: 14px 16px;
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 72%, transparent);
  background:
    radial-gradient(ellipse 55% 80% at 0% 0%, color-mix(in srgb, var(--nd-accent) 10%, transparent), transparent 60%),
    color-mix(in srgb, var(--nd-surface-1) 85%, transparent);
  box-shadow: var(--nd-shadow-1, 0 8px 24px color-mix(in srgb, var(--nd-ink, black) 18%, transparent));
}
.nt-mist-shell {
  min-width: 0;
}
.nt-mist-shell > .nt-plane-theater {
  margin-bottom: 2px;
}
html[data-nd-theme='light'] .nt-device-hero.nt-panel-glass {
  background:
    radial-gradient(ellipse 55% 80% at 0% 0%, color-mix(in srgb, var(--nd-accent) 7%, transparent), transparent 60%),
    color-mix(in srgb, var(--nd-surface-0, white) 90%, var(--nd-surface-1));
}
html[data-nd-theme='light'] .nt-pagination.nd-pagination {
  background: color-mix(in srgb, var(--nd-surface-0, white) 80%, transparent);
}

/* ── ** ── ** Wave 20jy — ** tickets/clearpass shells · view menus ── ** ── */
.nt-clearpass-shell,
.nt-tickets-shell {
  min-width: 0;
}
.nt-tickets-shell .nt-severity-chips,
.nt-tickets-shell .nt-chip-row {
  margin-top: 2px;
}
.nd-viewopts.nt-view-options,
.nd-viewopts.nt-saved-views {
  position: relative;
  display: inline-flex;
  align-items: center;
}
.nd-viewopts__panel.nt-panel-glass {
  z-index: var(--nd-z-popover, 40);
  min-width: 240px;
  max-width: min(360px, 92vw);
  padding: 10px 10px 12px;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 72%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 88%, transparent);
  backdrop-filter: blur(14px) saturate(1.12);
  -webkit-backdrop-filter: blur(14px) saturate(1.12);
  box-shadow: var(--nd-shadow-3, 0 16px 40px color-mix(in srgb, var(--nd-ink, black) 32%, transparent));
}
.nd-viewopts__heading {
  font-size: var(--nd-text-11, 11px);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--nd-text-muted);
  font-weight: 600;
  padding: 2px 6px 8px;
}
.nd-viewopts__item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 4px 4px;
  border-radius: 8px;
}
.nd-viewopts__item:hover {
  background: color-mix(in srgb, var(--nd-surface-2) 55%, transparent);
}
.nt-saved-row {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  min-width: 0;
}
html[data-nd-theme='light'] .nd-viewopts__panel.nt-panel-glass {
  background: color-mix(in srgb, var(--nd-surface-0, white) 90%, transparent);
}

/* ── ** ── ** Wave 20jz — ** screen header glass · hotkey overlay ── ** ── */
.nt-screen-header.nt-toolbar-glass {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px 18px;
  padding: 10px 12px 12px;
  margin: 0 0 10px;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 68%, transparent);
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--nd-surface-2) 35%, transparent), transparent 70%),
    color-mix(in srgb, var(--nd-surface-1) 72%, transparent);
  backdrop-filter: blur(10px) saturate(1.08);
  -webkit-backdrop-filter: blur(10px) saturate(1.08);
  box-shadow: var(--nd-shadow-1, 0 6px 18px color-mix(in srgb, var(--nd-ink, black) 14%, transparent));
}
.nt-screen-header__brand {
  margin: 0 0 4px;
}
.nt-screen-header__overline {
  margin: 0;
  font-size: var(--nd-text-11, 11px);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--nd-text-muted);
}
.nt-screen-header__subtitle {
  margin: 6px 0 0;
  max-width: 62ch;
  color: var(--nd-text-muted);
  font-size: var(--nd-text-13, 13px);
  line-height: 1.45;
}
.nt-screen-header__actions {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-left: auto;
}
.nt-hotkey-trigger.nd-shortcuts__trigger {
  appearance: none;
  width: 28px;
  height: 28px;
  border-radius: 8px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 75%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2) 70%, transparent);
  color: var(--nd-text-muted);
  font: inherit;
  font-weight: 700;
  cursor: pointer;
  transition: border-color 120ms var(--nd-ease, ease), color 120ms var(--nd-ease, ease);
}
.nt-hotkey-trigger:hover {
  color: var(--nd-text);
  border-color: color-mix(in srgb, var(--nd-accent) 30%, var(--nd-border));
}
.nd-shortcuts.nt-hotkey-overlay.nt-panel-glass {
  border: 1px solid color-mix(in srgb, var(--nd-border) 70%, transparent);
  border-radius: 16px;
  background: color-mix(in srgb, var(--nd-surface-1) 90%, transparent);
  backdrop-filter: blur(16px) saturate(1.15);
  -webkit-backdrop-filter: blur(16px) saturate(1.15);
  box-shadow: var(--nd-shadow-4, 0 24px 64px color-mix(in srgb, var(--nd-ink, black) 40%, transparent));
}
.nd-shortcuts__brand {
  font-size: var(--nd-text-11, 11px);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--nd-accent) 70%, var(--nd-text-muted));
  font-weight: 600;
}
html[data-nd-theme='light'] .nt-screen-header.nt-toolbar-glass {
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--nd-surface-0, white) 40%, transparent), transparent 70%),
    color-mix(in srgb, var(--nd-surface-0, white) 86%, transparent);
}

/* ── ** ── ** Wave 20ka — ** inventory shells · drawer · switch ── ** ── */
.nt-site-detail-shell,
.nt-central-shell,
.nt-devices-shell,
.nt-topology-shell {
  min-width: 0;
}
.nt-drawer-root.nd-drawer-root {
  position: fixed;
  inset: 0;
  z-index: var(--nd-z-drawer, 50);
  pointer-events: none;
}
.nt-drawer-root.nd-drawer-root > * {
  pointer-events: auto;
}
.nt-drawer-overlay.nd-drawer-overlay {
  position: absolute;
  inset: 0;
  background: color-mix(in srgb, var(--nd-ink, black) 48%, transparent);
  backdrop-filter: blur(2px);
}
.nt-drawer.nd-drawer,
.nd-drawer__panel.nt-drawer__panel {
  border-left: 1px solid color-mix(in srgb, var(--nd-border) 70%, transparent);
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--nd-accent) 6%, transparent), transparent 28%),
    color-mix(in srgb, var(--nd-surface-1) 94%, transparent);
  box-shadow: var(--nd-shadow-4, 0 24px 64px color-mix(in srgb, var(--nd-ink, black) 40%, transparent));
  backdrop-filter: blur(12px) saturate(1.1);
  -webkit-backdrop-filter: blur(12px) saturate(1.1);
}
.nt-drawer__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 16px 10px;
  border-bottom: 1px solid color-mix(in srgb, var(--nd-border) 70%, transparent);
}
.nt-drawer-kicker {
  font-size: var(--nd-text-11, 11px);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--nd-accent) 70%, var(--nd-text-muted));
  font-weight: 600;
  margin-bottom: 4px;
}
.nt-drawer__title {
  font-size: var(--nd-text-16, 16px);
  font-weight: 650;
  letter-spacing: -0.01em;
}
.nt-drawer__description {
  margin-top: 4px;
  color: var(--nd-text-muted);
  font-size: var(--nd-text-12, 12px);
  line-height: 1.45;
  max-width: 42ch;
}
.nt-drawer__close {
  appearance: none;
  border: 0;
  background: transparent;
  color: var(--nd-text-muted);
  font-size: 20px;
  line-height: 1;
  cursor: pointer;
  border-radius: 8px;
  width: 32px;
  height: 32px;
}
.nt-drawer__close:hover {
  color: var(--nd-text);
  background: color-mix(in srgb, var(--nd-surface-2) 70%, transparent);
}
.nt-drawer__body {
  padding: 14px 16px 20px;
  overflow: auto;
  min-height: 0;
}
.nt-switch {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  user-select: none;
}
.nt-switch__track {
  position: relative;
  width: 36px;
  height: 20px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--nd-surface-3, var(--nd-surface-2)) 80%, var(--nd-border));
  border: 1px solid color-mix(in srgb, var(--nd-border) 80%, transparent);
  transition: background 140ms var(--nd-ease, ease), border-color 140ms var(--nd-ease, ease);
}
.nt-switch__track--sm {
  width: 28px;
  height: 16px;
}
.nt-switch__track--on {
  background: color-mix(in srgb, var(--nd-accent) 75%, var(--nd-surface-2));
  border-color: color-mix(in srgb, var(--nd-accent) 45%, transparent);
}
.nt-switch__knob {
  position: absolute;
  top: 50%;
  left: 2px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--nd-surface-0, white);
  transform: translateY(-50%);
  transition: transform 140ms var(--nd-ease, ease);
  box-shadow: 0 1px 3px color-mix(in srgb, var(--nd-ink, black) 30%, transparent);
}
.nt-switch__track--on .nt-switch__knob,
.nd-switch__track--on .nd-switch__knob {
  transform: translate(16px, -50%);
}
.nt-switch__track--sm.nt-switch__track--on .nt-switch__knob,
.nd-switch__track--sm.nd-switch__track--on .nd-switch__knob {
  transform: translate(12px, -50%);
}
.nt-switch__label {
  font-size: var(--nd-text-13, 13px);
}
html[data-nd-theme='light'] .nt-drawer.nd-drawer {
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--nd-accent) 4%, transparent), transparent 28%),
    color-mix(in srgb, var(--nd-surface-0, white) 94%, transparent);
}

/* ── ** ── ** Wave 20kb — ** overview · clients · sites shells ── ** ── */
.nt-overview-shell,
.nt-clients-shell,
.nt-sites-shell {
  min-width: 0;
}
.nt-overview-shell .nt-change-strip {
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 70%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2) 45%, transparent);
