  display: flex;
  flex-wrap: wrap;
  gap: 8px 14px;
  align-items: center;
}
.nt-overview-shell .nt-change-strip__kicker {
  font-size: var(--nd-text-11, 11px);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--nd-accent) 70%, var(--nd-text-muted));
  font-weight: 600;
}
.nt-clients-shell .nt-clients-table {
  border-radius: 12px;
