}
.nt-inventory-shell .nt-inventory-result:hover {
  background: color-mix(in srgb, var(--nd-surface-2) 65%, transparent);
}
.nt-api-error.nt-callout-glass {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 16px;
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--nd-danger) 28%, var(--nd-border));
  background:
    radial-gradient(ellipse 60% 50% at 0% 0%, color-mix(in srgb, var(--nd-danger) 12%, transparent), transparent 55%),
    color-mix(in srgb, var(--nd-surface-1) 88%, transparent);
  box-shadow: var(--nd-shadow-2, 0 12px 32px color-mix(in srgb, var(--nd-ink, black) 22%, transparent));
  max-width: 560px;
}
.nt-api-error__kicker {
  font-size: var(--nd-text-11, 11px);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--nd-danger) 70%, var(--nd-text-muted));
  font-weight: 600;
}
html[data-nd-theme='light'] .nt-api-error.nt-callout-glass {
  background:
    radial-gradient(ellipse 60% 50% at 0% 0%, color-mix(in srgb, var(--nd-danger) 8%, transparent), transparent 55%),
    color-mix(in srgb, var(--nd-surface-0, white) 92%, transparent);
}
html[data-nd-theme='light'] .nt-inventory-shell .nt-inventory__tree-panel,
html[data-nd-theme='light'] .nt-inventory-shell .nt-inventory__detail {
  background: color-mix(in srgb, var(--nd-surface-0, white) 88%, transparent);
}

