}
html[data-nd-theme='light'] .nt-sse-banner {
  background: color-mix(in srgb, var(--nd-surface-0, white) 80%, transparent);
}

/* ── ** ── ** Wave 20kf — ** diff cinema (tokenized line hues) ── ** ── */
.nt-diff-cinema.nt-backup-diff {
  border-radius: 12px;
