  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 72%, transparent);
}
.nt-code-frame.nd-code-block {
  padding: 12px 14px;
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--nd-accent) 8%, transparent);
}
.nt-kbd.nd-kbd {
  border-radius: 7px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 90%, transparent);
  background: linear-gradient(180deg, color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 90%, transparent), color-mix(in srgb, var(--nd-surface-1) 90%, transparent));
  box-shadow: 0 1px 0 color-mix(in srgb, var(--nd-ink, black) 18%, transparent);
  font-size: var(--nd-text-11, 11px);
