    linear-gradient(180deg, color-mix(in srgb, var(--nd-surface-1) 92%, transparent), color-mix(in srgb, var(--nd-surface-0, var(--nd-surface-1)) 88%, transparent));
  backdrop-filter: blur(12px) saturate(1.1);
  -webkit-backdrop-filter: blur(12px) saturate(1.1);
}
.nt-shift-strip[data-p1='true'] {
  box-shadow: inset 0 -2px 0 color-mix(in srgb, var(--nd-danger) 70%, transparent);
}
.nt-shift-strip[data-degraded='true'] {
  box-shadow: inset 0 -2px 0 color-mix(in srgb, var(--nd-warning) 65%, transparent);
}
.nt-shift-strip[data-p1='true'][data-degraded='true'] {
  box-shadow:
    inset 0 -2px 0 color-mix(in srgb, var(--nd-danger) 70%, transparent),
