}
.nt-site-section.nt-section-panel {
  background:
    linear-gradient(
      170deg,
      color-mix(in srgb, var(--nd-info, var(--nd-accent)) 6%, transparent),
      transparent 42%
    ),
    color-mix(in srgb, var(--nd-surface-1) 93%, transparent);
}

html[data-nd-theme='light'] .nt-central-section.nt-section-panel,
html[data-nd-theme='light'] .nt-mist-section.nt-section-panel,
html[data-nd-theme='light'] .nt-device-section.nt-section-panel,
html[data-nd-theme='light'] .nt-site-section.nt-section-panel {
  background:
    linear-gradient(
      160deg,
      color-mix(in srgb, var(--nd-accent) 4.5%, transparent),
      transparent 40%
    ),
    color-mix(in srgb, var(--nd-surface-0, white) 95%, transparent);
}

/* ── ** ── ** Wave 20lw — ** session cinema · plane-head residual · fact rows ── ** ── */
.nt-session-stack.nt-device-section {
  display: grid;
  gap: 10px;
}
.nt-session-log {
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 55%, transparent);
  padding: 8px 10px;
  max-height: 280px;
  overflow: auto;
  font-family: var(--nd-font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: var(--nd-text-11, 11px);
  line-height: 1.45;
}
.nt-sess-in { color: color-mix(in srgb, var(--nd-success) 82%, var(--nd-text)); }
.nt-sess-blocked { color: color-mix(in srgb, var(--nd-danger) 88%, var(--nd-text)); font-weight: 700; }
.nt-sess-quiet { color: var(--nd-text-muted); }
.nt-sess-default { color: var(--nd-text-secondary, var(--nd-text)); }
.nt-rule-bottom {
  border-bottom: 1px solid color-mix(in srgb, var(--nd-border) 80%, transparent);
}
.nt-rule-bottom:last-child { border-bottom: 0; }

.nt-plane-head.nt-toolbar-glass {
  border-radius: 14px;
  padding: 8px 12px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 14%, var(--nd-border));
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--nd-surface-1) 88%, transparent),
      color-mix(in srgb, var(--nd-surface-1) 72%, transparent)
    );
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--nd-accent) 12%, transparent);
}
.nt-plane-head__meta {
  font-variant-numeric: tabular-nums;
}
.nt-plane-head__link:hover {
  color: var(--nd-accent);
  text-decoration: none;
}

.nt-fact-start-row {
  display: grid;
  grid-template-columns: var(--nd-fact-key, 140px) minmax(0, 1fr);
  gap: 10px 14px;
  align-items: start;
  padding: 6px 0;
  border-bottom: 1px solid color-mix(in srgb, var(--nd-border) 72%, transparent);
}
.nt-fact-start-row:last-child { border-bottom: 0; }
.nt-fact-key {
  color: var(--nd-text-muted);
  font-size: var(--nd-text-11, 11px);
  letter-spacing: 0.04em;
  text-transform: uppercase;
  font-weight: 700;
  width: var(--nd-fact-key, 140px);
}

html[data-nd-theme='light'] .nt-session-log {
  background: color-mix(in srgb, var(--nd-surface-0, white) 92%, transparent);
}
html[data-nd-theme='light'] .nt-plane-head.nt-toolbar-glass {
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--nd-surface-0, white) 94%, transparent),
      color-mix(in srgb, var(--nd-surface-1) 70%, transparent)
    );
}

/* ── ** ── ** Wave 20lx — ** toast · tooltip · tabs · crumbs · skeleton cinema ── ** ── */
.nt-toast-region {
  position: fixed;
  right: 16px;
  bottom: 16px;
  z-index: var(--nd-z-toast, 60);
  display: grid;
  gap: 8px;
  width: min(360px, calc(100vw - 24px));
  pointer-events: none;
}
.nt-toast {
  pointer-events: auto;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 18%, var(--nd-border));
  background:
    linear-gradient(
      145deg,
      color-mix(in srgb, var(--nd-accent) 10%, transparent),
      transparent 48%
    ),
    color-mix(in srgb, var(--nd-surface-1) 96%, transparent);
  box-shadow: var(--nd-shadow-3, 0 18px 40px color-mix(in srgb, var(--nd-ink, black) 34%, transparent));
  padding: 10px 12px;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}
.nt-toast[data-tone='success'],
.nt-toast.nd-toast--success {
  border-color: color-mix(in srgb, var(--nd-success) 36%, var(--nd-border));
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--nd-success) 12%, transparent),
    var(--nd-shadow-3, 0 18px 40px color-mix(in srgb, var(--nd-ink, black) 34%, transparent));
}
.nt-toast[data-tone='danger'],
.nt-toast.nd-toast--danger {
  border-color: color-mix(in srgb, var(--nd-danger) 40%, var(--nd-border));
}
.nt-toast[data-tone='warning'],
.nt-toast.nd-toast--warning {
  border-color: color-mix(in srgb, var(--nd-warning) 40%, var(--nd-border));
}
.nt-toast__title {
  font-weight: 750;
  letter-spacing: 0.01em;
}
.nt-toast__desc {
  margin-top: 3px;
  color: var(--nd-text-muted);
  font-size: var(--nd-text-12, 12px);
  line-height: 1.4;
}

.nt-tooltip {
  position: relative;
  display: inline-flex;
}
.nt-tooltip__bubble {
  position: absolute;
  z-index: var(--nd-z-tooltip, 70);
  max-width: min(280px, 70vw);
  padding: 6px 9px;
  border-radius: 10px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 20%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-surface-1) 96%, transparent);
  color: var(--nd-text);
  font-size: var(--nd-text-12, 12px);
  line-height: 1.35;
  box-shadow: var(--nd-shadow-2, 0 10px 28px color-mix(in srgb, var(--nd-ink, black) 30%, transparent));
  pointer-events: none;
  white-space: normal;
}

.nt-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  padding: 4px;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 42%, transparent);
}
.nt-tabs__trigger {
  border: 1px solid transparent;
  background: transparent;
  color: var(--nd-text-muted);
  border-radius: 10px;
  padding: 7px 12px;
  font-weight: 650;
  cursor: pointer;
}
.nt-tabs__trigger:hover {
  color: var(--nd-text);
  background: color-mix(in srgb, var(--nd-accent) 8%, transparent);
}
.nt-tabs__trigger--active,
.nt-tabs__trigger.nd-tabs__trigger--active {
  color: var(--nd-accent);
  border-color: color-mix(in srgb, var(--nd-accent) 28%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-accent) 12%, transparent);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--nd-accent) 16%, transparent);
}

.nt-breadcrumbs {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  min-width: 0;
}
.nt-breadcrumbs__sep {
  color: color-mix(in srgb, var(--nd-text-muted) 70%, transparent);
  opacity: 0.7;
  user-select: none;
}
.nt-breadcrumbs__link {
  border: 0;
  background: transparent;
  color: var(--nd-text-muted);
  cursor: pointer;
  padding: 0;
  font: inherit;
}
.nt-breadcrumbs__link:hover {
  color: var(--nd-accent);
}
.nt-breadcrumbs__item--current {
  color: var(--nd-text);
  font-weight: 700;
}

.nt-skeleton-block {
  border-radius: 10px;
  background:
    linear-gradient(
      90deg,
      color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 70%, transparent) 0%,
      color-mix(in srgb, var(--nd-accent) 12%, var(--nd-surface-2, var(--nd-surface-1))) 50%,
      color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 70%, transparent) 100%
    );
  background-size: 200% 100%;
  animation: nt-skeleton-shimmer 1.4s ease-in-out infinite;
}
@keyframes nt-skeleton-shimmer {
  0% { background-position: 100% 0; }
  100% { background-position: -100% 0; }
}
@media (prefers-reduced-motion: reduce) {
  .nt-skeleton-block { animation: none; }
}

html[data-nd-theme='light'] .nt-toast,
html[data-nd-theme='light'] .nt-tooltip__bubble {
  background: color-mix(in srgb, var(--nd-surface-0, white) 96%, transparent);
}
html[data-nd-theme='light'] .nt-tabs {
  background: color-mix(in srgb, var(--nd-surface-1) 55%, transparent);
}

/* ── ** ── ** Wave 20ly — ** section panel compound fix · central lane densify ── ** ── */
.nt-central-section,
.nt-mist-section,
.nt-device-section,
.nt-site-section,
.nt-systems-section {
  position: relative;
}
.nt-central-section:not(.nt-section-panel),
.nt-mist-section:not(.nt-section-panel),
.nt-device-section:not(.nt-section-panel),
.nt-site-section:not(.nt-section-panel),
.nt-systems-section:not(.nt-section-panel) {
