html[data-nd-theme='light'] .nt-central-section:not(.nt-section-panel),
html[data-nd-theme='light'] .nt-mist-section:not(.nt-section-panel),
html[data-nd-theme='light'] .nt-device-section:not(.nt-section-panel),
html[data-nd-theme='light'] .nt-site-section:not(.nt-section-panel),
html[data-nd-theme='light'] .nt-systems-section:not(.nt-section-panel) {
  background:
    linear-gradient(
      160deg,
      color-mix(in srgb, var(--nd-accent) 4.5%, transparent),
