  color: color-mix(in srgb, var(--nd-accent) 78%, var(--nd-text-muted));
}
.nt-screen-header__overline {
  margin: 0 0 2px;
  font-size: var(--nd-text-11, 11px);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--nd-text-muted);
  font-weight: 700;
}
.nt-screen-header__title {
  margin: 0;
  letter-spacing: -0.02em;
}
.nt-screen-header__subtitle {
  margin: 4px 0 0;
  max-width: 62ch;
  color: var(--nd-text-muted);
  font-size: var(--nd-text-13, 13px);
  line-height: 1.45;
}
.nt-screen-header__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  justify-content: flex-end;
}

.nt-sticky-filters {
  position: sticky;
  top: 72px;
  z-index: 8;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  padding: 8px 10px;
  margin: 0 0 12px;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 88%, transparent);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--nd-accent) 8%, transparent);
}

.nt-bulk-glass,
.nt-configure-bulk-bar.nt-bulk-glass {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 14px;
  align-items: center;
  padding: 10px 12px;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 22%, var(--nd-border));
  background:
    linear-gradient(
      120deg,
      color-mix(in srgb, var(--nd-accent) 12%, transparent),
      transparent 55%
    ),
    color-mix(in srgb, var(--nd-surface-1) 92%, transparent);
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--nd-accent) 14%, transparent),
    0 12px 28px color-mix(in srgb, var(--nd-ink, black) 16%, transparent);
}
.nt-configure-bulk-bar__count {
  font-weight: 800;
  letter-spacing: 0.06em;
  font-size: var(--nd-text-11, 11px);
  color: var(--nd-accent);
  font-variant-numeric: tabular-nums;
}
.nt-configure-bulk-bar__hint {
  color: var(--nd-text-muted);
  font-size: var(--nd-text-12, 12px);
  flex: 1 1 180px;
}
.nt-configure-bulk-bar__actions {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-left: auto;
}

@media (max-width: 820px) {
  .nt-screen-header.nt-toolbar-glass {
    grid-template-columns: 1fr;
    align-items: start;
  }
  .nt-screen-header__actions {
    justify-content: flex-start;
  }
}

html[data-nd-theme='light'] .nt-screen-header.nt-toolbar-glass {
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--nd-surface-0, white) 96%, transparent),
      color-mix(in srgb, var(--nd-surface-1) 80%, transparent)
    );
}
html[data-nd-theme='light'] .nt-sticky-filters,
html[data-nd-theme='light'] .nt-bulk-glass,
html[data-nd-theme='light'] .nt-configure-bulk-bar.nt-bulk-glass {
  background: color-mix(in srgb, var(--nd-surface-0, white) 94%, transparent);
}

/* ── ** ── ** Wave 20mb — ** drawer cinema · modal copper · hotkey overlay ── ** ── */
.nt-drawer-overlay,
.nd-drawer-overlay {
  background: color-mix(in srgb, var(--nd-ink, black) 52%, transparent);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}
.nt-drawer,
.nd-drawer {
  border-left: 1px solid color-mix(in srgb, var(--nd-accent) 18%, var(--nd-border));
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--nd-accent) 7%, transparent),
      transparent 28%
    ),
    color-mix(in srgb, var(--nd-surface-1) 97%, transparent);
  box-shadow: -24px 0 64px color-mix(in srgb, var(--nd-ink, black) 36%, transparent);
}
.nt-drawer__kicker,
.nd-drawer__kicker {
  font-size: var(--nd-text-10, 10px);
  letter-spacing: 0.14em;
