  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 60%, transparent);
  box-shadow: inset 0 -1px 0 color-mix(in srgb, var(--nd-ink, black) 18%, transparent);
  font-family: var(--nd-font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: 11px;
  padding: 2px 6px;
}

html[data-nd-theme='light'] .nt-drawer,
html[data-nd-theme='light'] .nd-drawer,
html[data-nd-theme='light'] .nt-modal,
html[data-nd-theme='light'] .nd-modal,
html[data-nd-theme='light'] .nt-hotkey-overlay,
html[data-nd-theme='light'] .nd-hotkey-overlay {
  background: color-mix(in srgb, var(--nd-surface-0, white) 97%, transparent);
}

/* ── ** ── ** Wave 20mc — ** hotkey map cinema · war-room skeleton anatomy ── ** ── */
.nt-hotkey-root {
  position: fixed;
  inset: 0;
  z-index: var(--nd-z-modal, 80);
  display: grid;
  place-items: center;
  padding: 24px;
