  pointer-events: none;
}

/* clearpass residual */
.nt-clearpass-shell.nt-section-panel {
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 90%, transparent);
  background:
    linear-gradient(
      160deg,
      color-mix(in srgb, var(--nd-accent) 5%, transparent),
      transparent 40%
    ),
    color-mix(in srgb, var(--nd-surface-1) 94%, transparent);
}

html[data-nd-theme='light'] .nt-clearpass-shell.nt-section-panel {
  background:
    linear-gradient(
      160deg,
      color-mix(in srgb, var(--nd-accent) 4%, transparent),
      transparent 40%
    ),
    color-mix(in srgb, var(--nd-surface-0, white) 96%, transparent);
}

/* ── ** ── ** Wave 20mn — ** licenses · uxi · auth-events residual cinema ── ** ── */
.nt-licenses-shell.nt-section-panel,
.nt-uxi-shell.nt-section-panel,
.nt-auth-events-shell.nt-section-panel,
.nt-authevents-shell.nt-section-panel {
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 90%, transparent);
  background:
    linear-gradient(
      160deg,
      color-mix(in srgb, var(--nd-accent) 5%, transparent),
      transparent 42%
    ),
    color-mix(in srgb, var(--nd-surface-1) 94%, transparent);
