}
.nt-licenses-shell::before,
.nt-uxi-shell::before {
  content: "";
  display: block;
  height: 2px;
  margin: 0 2px 12px;
  border-radius: 999px;
  background: linear-gradient(
    90deg,
    transparent,
    color-mix(in srgb, var(--nd-accent) 55%, transparent),
    transparent
  );
  opacity: 0.65;
}

/* recommendations residual */
.nt-recommendations-shell.nt-section-panel {
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 90%, transparent);
  background:
    radial-gradient(
      90% 60% at 0% 0%,
      color-mix(in srgb, var(--nd-warning) 10%, transparent),
      transparent 55%
    ),
    color-mix(in srgb, var(--nd-surface-1) 94%, transparent);
  padding: 12px 14px;
}

/* saved views residual */
.nt-saved-views,
.nt-saved-views-shell {
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 92%, transparent);
  padding: 10px 12px;
}
.nt-saved-views__item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
  align-items: center;
  padding: 6px 8px;
  border-radius: 10px;
  border: 1px solid transparent;
}
.nt-saved-views__item:hover {
  background: color-mix(in srgb, var(--nd-accent) 8%, transparent);
  border-color: color-mix(in srgb, var(--nd-accent) 12%, transparent);
}

html[data-nd-theme='light'] .nt-licenses-shell.nt-section-panel,
html[data-nd-theme='light'] .nt-uxi-shell.nt-section-panel,
html[data-nd-theme='light'] .nt-recommendations-shell.nt-section-panel,
html[data-nd-theme='light'] .nt-saved-views {
  background: color-mix(in srgb, var(--nd-surface-0, white) 96%, transparent);
}

/* ── ** ── ** Wave 20mo — ** menu glass · popover · select panel residual ── ** ── */
.nt-menu,
.nt-menu-left,
.nd-menu,
.nd-popover,
.nt-popover {
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 16%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-surface-1) 96%, transparent);
  box-shadow: var(--nd-shadow-3, 0 18px 40px color-mix(in srgb, var(--nd-ink, black) 34%, transparent));
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  padding: 6px;
  z-index: var(--nd-z-popover, 50);
}
.nt-menu__item,
.nd-menu__item {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  border: 0;
  background: transparent;
  color: var(--nd-text);
  text-align: left;
  border-radius: 10px;
  padding: 8px 10px;
  cursor: pointer;
  font: inherit;
}
.nt-menu__item:hover,
.nd-menu__item:hover,
.nt-menu__item[data-active='true'] {
  background: color-mix(in srgb, var(--nd-accent) 10%, transparent);
  color: var(--nd-accent);
}
.nt-menu__sep {
  height: 1px;
  margin: 4px 6px;
  background: color-mix(in srgb, var(--nd-border) 88%, transparent);
}

/* select trigger glass */
.nd-select,
.nt-select {
  border-radius: 10px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 45%, transparent);
}
.nd-select:focus-within,
.nt-select:focus-within {
  border-color: color-mix(in srgb, var(--nd-accent) 40%, var(--nd-border));
  box-shadow: 0 0 0 3px var(--nd-focus-ring, color-mix(in srgb, var(--nd-accent) 24%, transparent));
}

/* input residual */
.nd-input,
.nt-input {
  border-radius: 10px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 40%, transparent);
  color: var(--nd-text);
}
.nd-input:focus-visible,
.nt-input:focus-visible {
  outline: none;
  border-color: color-mix(in srgb, var(--nd-accent) 40%, var(--nd-border));
  box-shadow: 0 0 0 3px var(--nd-focus-ring, color-mix(in srgb, var(--nd-accent) 24%, transparent));
}

html[data-nd-theme='light'] .nt-menu,
html[data-nd-theme='light'] .nt-menu-left,
html[data-nd-theme='light'] .nd-menu,
html[data-nd-theme='light'] .nt-popover {
  background: color-mix(in srgb, var(--nd-surface-0, white) 97%, transparent);
}

/* ── ** ── ** Wave 20mp — ** micro-label · ticket notes · alerts toolbar cinema ── ** ── */
.nd-micro-label.nt-micro-label,
.nt-micro-label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 10px;
  font-weight: 650;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--nd-text-muted, var(--nd-text-secondary)) 92%, transparent);
}

/* ticket notes stream */
.nt-ticket-note-row {
  display: grid;
  grid-template-columns: 10px minmax(0, 1fr);
  gap: 10px;
  padding: 10px 4px;
  position: relative;
}
.nt-ticket-note-row::before {
  content: "";
  width: 8px;
  height: 8px;
  margin-top: 5px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--nd-accent) 70%, transparent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--nd-accent) 14%, transparent);
}
.nt-ticket-note-row.nt-border-b::after {
  content: "";
  position: absolute;
  left: 3px;
  top: 22px;
  bottom: -2px;
  width: 1px;
  background: linear-gradient(
    180deg,
    color-mix(in srgb, var(--nd-accent) 35%, transparent),
    transparent
  );
}
.nt-ticket-note {
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 86%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2, var(--nd-surface-1)) 42%, transparent);
  padding: 8px 10px;
  color: var(--nd-text);
}
.nt-ticket-body {
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--nd-accent) 5%, transparent),
      transparent 40%
    ),
    color-mix(in srgb, var(--nd-surface-1) 92%, transparent);
  padding: 12px 14px;
}
.nt-ticket-row {
  display: grid;
  gap: 8px;
  padding: 8px 0;
}
.nt-ticket-meta {
  color: var(--nd-text-secondary);
