.nt-py-8 { padding-top: 8px; padding-bottom: 8px; }
.nt-mb-8 { margin-bottom: 8px; }
.nt-mb-10 { margin-bottom: 10px; }
.nt-mb-12 { margin-bottom: 12px; }
.nt-mb-14 { margin-bottom: 14px; }
.nt-rounded-12 { border-radius: 12px; }
.nt-rounded-14 { border-radius: 14px; }
.nt-rounded-16 { border-radius: 16px; }
.nt-truncate {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.nt-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
