}
@media (prefers-reduced-motion: reduce) {
  .nt-surface-hover { transition: none; }
}

/* ── ** ── ** Wave 20nz — ** licenses/uxi/auth-events polish residual ── ** ── */
.nt-licenses-shell .nt-progress-rail,
.nt-licenses-shell .nd-progress {
  height: 10px;
}
.nt-uxi-shell .nt-stat-band,
.nt-auth-events-shell .nt-stat-band {
  margin-bottom: 10px;
}

/* recommendations severity residual densify */
.nt-recommendations-shell .nt-chip-row {
  margin-bottom: 10px;
}

/* hop-free: ensure section panel default elevation */
.nt-section-panel {
  position: relative;
  isolation: isolate;
}
.nt-section-panel::after {
  content: "";
  pointer-events: none;
  position: absolute;
  inset: 0;
  border-radius: inherit;
  box-shadow: inset 0 1px 0 color-mix(in srgb, white 5%, transparent);
  opacity: 0.5;
}

html[data-nd-theme='light'] .nt-section-panel::after {
  box-shadow: inset 0 1px 0 color-mix(in srgb, white 55%, transparent);
  opacity: 0.8;
}

/* ── ** ── ** Wave 20oa — ** copper continuum keepalive ── ** ── */
.nt-configure-shell .nt-write-ritual,
.nt-greenlake-shell .nt-write-ritual,
.nt-alerts-shell .nt-write-ritual {
  position: relative;
}
.nt-configure-shell .nt-configure__queue.nt-write-ritual {
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--nd-warning) 28%, var(--nd-border));
  padding: 12px 12px 14px;
  background:
    radial-gradient(
      90% 60% at 100% 0%,
      color-mix(in srgb, var(--nd-warning) 10%, transparent),
      transparent 55%
    ),
    color-mix(in srgb, var(--nd-surface-1) 94%, transparent);
}
.nt-configure__queue-title.nt-write-ritual__title {
  font-size: 11px;
  font-weight: 750;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--nd-warning) 70%, var(--nd-text));
  margin-bottom: 6px;
}
.nt-plane-theater--compact {
  min-height: 22px;
  padding-bottom: 6px;
  font-size: 10.5px;
}
html[data-nd-theme='light'] .nt-configure__queue.nt-write-ritual {
  background: color-mix(in srgb, var(--nd-surface-0, white) 96%, transparent);
}

/* ── ** ── ** Wave 20ob — ** keepalive copper densify ── ** ── */
.nt-alerts-shell .nt-incident-spine,
.nt-tickets-shell .nt-incident-spine,
.nt-device-shell .nt-incident-spine {
  margin-bottom: 10px;
}
.nt-incident-spine {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 8px;
  padding: 8px 10px;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 86%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 90%, transparent);
}
.nt-incident-spine__step {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--nd-text-secondary);
  padding: 3px 8px;
  border-radius: 999px;
}
.nt-incident-spine__step[data-active='true'] {
  color: var(--nd-accent);
  background: color-mix(in srgb, var(--nd-accent) 12%, transparent);
  border: 1px solid color-mix(in srgb, var(--nd-accent) 28%, transparent);
}

html[data-nd-theme='light'] .nt-incident-spine {
  background: color-mix(in srgb, var(--nd-surface-0, white) 96%, transparent);
}

/* ── ** ── ** Wave 20oc — ** topo · tree · spacer · overlay tokens ── ** ── */
.nt-topo-lane {
  position: relative;
  min-height: var(--nd-topo-h, 320px);
}
.nt-topo-layer-label {
  position: absolute;
  left: 0;
  top: var(--nd-topo-y, 0);
  transform: translateY(-50%);
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--nd-text-tertiary);
  opacity: 0.85;
  pointer-events: none;
}
.nt-topo-diagram {
  min-width: var(--nd-topo-min-w, 100%);
  height: var(--nd-topo-h, 320px);
  position: relative;
}
.nt-topo-edge-label {
  position: absolute;
  left: var(--nd-topo-x, 50%);
  top: var(--nd-topo-y, 50%);
  transform: translate(-50%, -50%);
  font-size: 10px;
  font-variant-numeric: tabular-nums;
  color: var(--nd-text-tertiary);
  padding: 1px 5px;
  border-radius: 6px;
  background: color-mix(in srgb, var(--nd-surface-1) 88%, transparent);
  border: 1px solid color-mix(in srgb, var(--nd-border) 70%, transparent);
  pointer-events: none;
}
.nt-topo-edge-label[data-lit='true'] {
  color: var(--nd-accent);
  border-color: color-mix(in srgb, var(--nd-accent) 36%, transparent);
  box-shadow: 0 0 12px color-mix(in srgb, var(--nd-accent) 18%, transparent);
}

.nt-inventory-tree__row,
.nt-inventory-tree__loading,
.nt-inventory-tree__more {
  --_tree-pad: calc(var(--nd-tree-level, 0) * 14px + 8px);
  padding-left: var(--_tree-pad);
}
.nt-inventory-tree__row {
  display: flex;
  align-items: center;
  gap: 6px;
  min-height: 30px;
  border-radius: 8px;
  border: 1px solid transparent;
  color: var(--nd-text-primary);
  transition: background 120ms ease, border-color 120ms ease;
}
.nt-inventory-tree__row:hover {
  background: color-mix(in srgb, var(--nd-surface-2) 72%, transparent);
}
.nt-inventory-tree__row[data-active='true'] {
  background: color-mix(in srgb, var(--nd-accent) 10%, transparent);
  border-color: color-mix(in srgb, var(--nd-accent) 28%, transparent);
}
.nt-inventory-tree__loading,
.nt-inventory-tree__more {
  font-size: 11px;
  color: var(--nd-text-tertiary);
  padding-top: 4px;
  padding-bottom: 4px;
}
.nt-inventory-tree__more {
  background: none;
  border: 0;
  color: var(--nd-accent);
  cursor: pointer;
  text-align: left;
}
.nt-inventory-tree__more:hover {
  text-decoration: underline;
}

.nd-table-spacer,
.nt-table-spacer {
  height: var(--nd-spacer-h, auto);
  padding: 0 !important;
  border: 0 !important;
  background: transparent !important;
  line-height: 0;
}

.nd-modal,
.nt-modal,
.nd-menu__panel {
  width: min(100%, var(--nd-overlay-w, 480px));
}
.nd-menu__panel {
  min-width: min(100%, var(--nd-overlay-w, 220px));
}

/* Incident spine polish — chev only, no pseudo arrows */
.nt-incident-spine {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 2px;
  padding: 8px 10px;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 84%, transparent);
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--nd-surface-2) 40%, transparent), transparent),
    color-mix(in srgb, var(--nd-surface-1) 92%, transparent);
  box-shadow: inset 0 1px 0 color-mix(in srgb, white 4%, transparent);
}
.nt-incident-spine__step {
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--nd-text-tertiary);
  padding: 4px 9px;
  border-radius: 999px;
  border: 1px solid transparent;
}
.nt-incident-spine__step[data-active='true'] {
  color: var(--nd-accent);
  background: color-mix(in srgb, var(--nd-accent) 12%, transparent);
  border-color: color-mix(in srgb, var(--nd-accent) 30%, transparent);
  box-shadow: 0 0 14px color-mix(in srgb, var(--nd-accent) 14%, transparent);
}
.nt-incident-spine__chev,
.nt-incident-spine__arrow,
.nt-incident-spine__sep {
  opacity: 0.42;
