}

html[data-nd-theme='light'] .nt-incident-spine {
  background: color-mix(in srgb, var(--nd-surface-0, white) 96%, transparent);
  box-shadow: none;
}
html[data-nd-theme='light'] .nt-topo-edge-label {
  background: color-mix(in srgb, white 94%, transparent);
}

/* ── ** ── ** Wave 20od — ** war-room · cmdk · notify · status cinema ── ** ── */
.nt-route-fallback.nt-war-room-wake {
  min-height: min(70vh, 640px);
  display: grid;
  place-items: center;
  padding: 24px;
  background:
    radial-gradient(ellipse 80% 55% at 50% 0%, color-mix(in srgb, var(--nd-accent) 10%, transparent), transparent 70%),
    radial-gradient(ellipse 60% 40% at 80% 100%, color-mix(in srgb, var(--nd-info) 6%, transparent), transparent 65%),
    var(--nd-surface-0);
}
.nt-route-fallback__card {
  width: min(420px, 100%);
  padding: 22px 24px;
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 92%, transparent);
  box-shadow:
    0 18px 48px color-mix(in srgb, black 35%, transparent),
    inset 0 1px 0 color-mix(in srgb, white 5%, transparent);
}
.nt-route-fallback__kicker {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--nd-accent);
  margin-bottom: 10px;
}
.nt-route-fallback__card::after {
  content: "";
  display: block;
  margin-top: 16px;
  height: 3px;
  border-radius: 999px;
  background: linear-gradient(90deg, transparent, var(--nd-accent), transparent);
  background-size: 200% 100%;
  animation: nd-wake-sheen 1.6s ease-in-out infinite;
}
@keyframes nd-wake-sheen {
  0% { background-position: 100% 0; opacity: 0.35; }
  50% { opacity: 1; }
  100% { background-position: -100% 0; opacity: 0.35; }
}

.nt-cmdk,
.nd-cmdk {
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 80%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 94%, transparent);
  box-shadow:
    0 28px 80px color-mix(in srgb, black 48%, transparent),
    0 0 0 1px color-mix(in srgb, var(--nd-accent) 10%, transparent),
    inset 0 1px 0 color-mix(in srgb, white 6%, transparent);
  backdrop-filter: blur(18px) saturate(1.15);
}
.nt-cmdk__input,
.nd-cmdk__input {
  font-size: 15px;
  letter-spacing: 0.01em;
}
.nt-cmdk__item[data-active='true'],
.nd-cmdk__item[aria-selected='true'],
.nt-cmdk [cmdk-item][data-selected='true'] {
  background: color-mix(in srgb, var(--nd-accent) 14%, transparent);
  color: var(--nd-text-primary);
  box-shadow: inset 3px 0 0 var(--nd-accent);
}

.nt-toast,
.nd-toast,
.nt-notify-toast {
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 82%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 94%, transparent);
  box-shadow: 0 12px 32px color-mix(in srgb, black 32%, transparent);
  backdrop-filter: blur(12px);
}
.nt-toast[data-tone='success'],
.nd-toast[data-tone='success'] {
  border-color: color-mix(in srgb, var(--nd-success) 40%, transparent);
}
.nt-toast[data-tone='danger'],
.nd-toast[data-tone='danger'],
.nt-toast[data-tone='error'] {
  border-color: color-mix(in srgb, var(--nd-danger) 42%, transparent);
}
.nt-toast[data-tone='warning'] {
  border-color: color-mix(in srgb, var(--nd-warning) 42%, transparent);
}

.nt-status-pill,
.nd-status-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 650;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  border: 1px solid color-mix(in srgb, var(--nd-border) 80%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2) 70%, transparent);
}
.nt-status-pill::before,
.nd-status-pill::before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--nd-health, var(--nd-text-tertiary));
  box-shadow: 0 0 8px var(--nd-health, transparent);
}
.nt-status-pill[data-tone='up'],
.nt-status-pill[data-tone='ok'],
.nt-status-pill[data-tone='success'] { --nd-health: var(--nd-success); }
.nt-status-pill[data-tone='degraded'],
.nt-status-pill[data-tone='warning'] { --nd-health: var(--nd-warning); }
.nt-status-pill[data-tone='down'],
.nt-status-pill[data-tone='danger'],
.nt-status-pill[data-tone='error'] { --nd-health: var(--nd-danger); }
.nt-status-pill[data-tone='unknown'],
.nt-status-pill[data-tone='neutral'] { --nd-health: var(--nd-text-tertiary); }

/* table spacer height via token */
.nd-table-spacer,
.nt-table-spacer {
  height: var(--nd-spacer-h, 0) !important;
}

@media (prefers-reduced-motion: reduce) {
  .nt-route-fallback__card::after {
    animation: none;
    opacity: 0.55;
  }
}

html[data-nd-theme='light'] .nt-route-fallback.nt-war-room-wake {
  background:
    radial-gradient(ellipse 80% 55% at 50% 0%, color-mix(in srgb, var(--nd-accent) 8%, transparent), transparent 70%),
    var(--nd-surface-0, white);
}
html[data-nd-theme='light'] .nt-cmdk,
html[data-nd-theme='light'] .nd-cmdk,
html[data-nd-theme='light'] .nt-toast,
html[data-nd-theme='light'] .nd-toast {
  box-shadow: 0 16px 40px color-mix(in srgb, black 12%, transparent);
  backdrop-filter: blur(10px);
}

/* ── ** ── ** Wave 20oe — ** overview theater · launchpad · change strip ── ** ── */
.nt-overview-shell.nt-section-panel {
  position: relative;
  isolation: isolate;
}
.nt-overview-shell.nt-section-panel::before {
  content: "";
  position: absolute;
  inset: 0 0 auto 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--nd-accent) 45%, transparent), transparent);
  opacity: 0.7;
  pointer-events: none;
  z-index: 1;
}
.nt-plane-theater {
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--nd-text-tertiary);
  padding: 6px 10px;
  border-radius: 10px;
  border: 1px dashed color-mix(in srgb, var(--nd-border) 78%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 55%, transparent);
  margin-bottom: 10px;
}

.nt-change-strip {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 10px;
  padding: 10px 12px;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 84%, transparent);
  background:
    linear-gradient(105deg, color-mix(in srgb, var(--nd-accent) 7%, transparent), transparent 42%),
    color-mix(in srgb, var(--nd-surface-1) 90%, transparent);
  box-shadow: inset 0 1px 0 color-mix(in srgb, white 4%, transparent);
  margin-bottom: 12px;
}
.nt-change-strip__kicker {
  font-size: 10.5px;
  font-weight: 750;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--nd-accent);
}
.nt-change-strip__chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 9px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 650;
  border: 1px solid color-mix(in srgb, var(--nd-border) 80%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2) 65%, transparent);
  color: var(--nd-text-secondary);
}
.nt-change-strip__chip--up,
.nt-change-strip__chip--ok,
.nt-change-strip__chip--success {
  border-color: color-mix(in srgb, var(--nd-success) 38%, transparent);
  color: var(--nd-success);
}
.nt-change-strip__chip--down,
.nt-change-strip__chip--danger,
.nt-change-strip__chip--error {
  border-color: color-mix(in srgb, var(--nd-danger) 40%, transparent);
  color: var(--nd-danger);
}
.nt-change-strip__chip--warn,
.nt-change-strip__chip--warning,
.nt-change-strip__chip--degraded {
  border-color: color-mix(in srgb, var(--nd-warning) 40%, transparent);
  color: var(--nd-warning);
}
.nt-change-strip__note {
  margin-left: auto;
  font-size: 11px;
  color: var(--nd-text-tertiary);
}

.nt-launchpad {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 10px;
}
.nt-launchpad__tile,
.nt-launchpad-row {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
  padding: 12px 14px;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 84%, transparent);
  background:
    linear-gradient(160deg, color-mix(in srgb, var(--nd-surface-2) 55%, transparent), transparent 55%),
    color-mix(in srgb, var(--nd-surface-1) 88%, transparent);
  color: inherit;
  text-decoration: none;
  transition: border-color 140ms ease, transform 140ms ease, box-shadow 140ms ease;
  box-shadow: inset 0 1px 0 color-mix(in srgb, white 4%, transparent);
}
.nt-launchpad__tile:hover,
.nt-launchpad-row:hover {
  border-color: color-mix(in srgb, var(--nd-accent) 36%, transparent);
  transform: translateY(-1px);
  box-shadow:
    0 10px 24px color-mix(in srgb, black 22%, transparent),
    inset 0 1px 0 color-mix(in srgb, white 5%, transparent);
}
.nt-launchpad-row__label {
  font-size: 13px;
  font-weight: 650;
  color: var(--nd-text-primary);
}

.nt-recon-reveal {
  animation: nd-recon-in 420ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
@keyframes nd-recon-in {
  from {
    opacity: 0;
    transform: translateY(6px);
    filter: saturate(0.85);
  }
  to {
    opacity: 1;
    transform: none;
    filter: none;
  }
}

.nt-plane-ecg {
  position: relative;
  overflow: hidden;
}
.nt-plane-ecg__fill {
  transition: width 480ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.nt-plane-ecg::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, transparent, color-mix(in srgb, white 18%, transparent), transparent);
  transform: translateX(-120%);
  animation: nd-ecg-sweep 2.8s ease-in-out infinite;
  pointer-events: none;
  opacity: 0.35;
}
@keyframes nd-ecg-sweep {
  0%, 40% { transform: translateX(-120%); }
  70%, 100% { transform: translateX(120%); }
}

.nt-device-hero.nt-hero-split {
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 84%, transparent);
  background:
    radial-gradient(ellipse 70% 80% at 0% 0%, color-mix(in srgb, var(--nd-accent) 10%, transparent), transparent 55%),
    color-mix(in srgb, var(--nd-surface-1) 92%, transparent);
  box-shadow:
    0 16px 40px color-mix(in srgb, black 24%, transparent),
    inset 0 1px 0 color-mix(in srgb, white 5%, transparent);
  padding: 16px 18px;
}

.nt-write-ritual--banner {
  height: 3px;
  border-radius: 999px 999px 0 0;
  background: linear-gradient(90deg,
    color-mix(in srgb, var(--nd-warning) 70%, transparent),
    color-mix(in srgb, var(--nd-accent) 80%, transparent),
    color-mix(in srgb, var(--nd-warning) 70%, transparent));
  background-size: 200% 100%;
  animation: nd-ritual-flow 2.4s linear infinite;
}
@keyframes nd-ritual-flow {
  to { background-position: 200% 0; }
}
.nt-write-ritual {
  position: relative;
}
.nd-drawer--write-ritual,
.nt-write-ritual.nd-drawer,
.nt-config-queue.nt-write-ritual {
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--nd-warning) 22%, transparent),
    0 18px 48px color-mix(in srgb, black 30%, transparent);
}

.nt-cmdk-cinema {
  border-radius: 16px;
}
.nt-cmdk-cinema__input {
  border-radius: 12px 12px 0 0;
}

.nt-screen-kicker {
  font-size: 11px;
  font-weight: 750;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--nd-accent);
}

@media (prefers-reduced-motion: reduce) {
  .nt-recon-reveal,
  .nt-plane-ecg::after,
  .nt-write-ritual--banner {
    animation: none !important;
  }
  .nt-launchpad__tile:hover,
  .nt-launchpad-row:hover {
    transform: none;
  }
}

html[data-nd-theme='light'] .nt-change-strip,
html[data-nd-theme='light'] .nt-launchpad__tile,
