.nd-alert[data-tone='success']::before { background: var(--nd-success); }
.nd-alert--warning.nt-callout-glass::before,
.nd-alert[data-tone='warning']::before { background: var(--nd-warning); }
.nd-alert--danger.nt-callout-glass::before,
.nd-alert--error.nt-callout-glass::before,
.nd-alert[data-tone='danger']::before,
