  color: var(--nd-text);
}
.nt-callout-glass__body,
.nd-alert__body {
  color: var(--nd-text-secondary);
  font-size: 13px;
  line-height: 1.45;
}
.nt-callout-glass__dismiss,
.nd-alert__dismiss {
  border: 0;
  background: transparent;
  color: var(--nd-text-tertiary);
