  border-radius: 6px;
  padding: 2px 6px;
}
.nt-callout-glass__dismiss:hover,
.nd-alert__dismiss:hover {
  color: var(--nd-text);
  background: color-mix(in srgb, var(--nd-surface-2) 55%, transparent);
}

/* ── ** ── ** Wave 20yv — ** drawer root/panel/body cinema ── ** ── */
.nd-drawer-root.nt-drawer-root,
.nt-drawer-root {
