  backdrop-filter: blur(6px);
  font-size: 11px;
  font-weight: 750;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--nd-text-tertiary);
  border-bottom: 1px solid color-mix(in srgb, var(--nd-border) 75%, transparent);
}
.nd-table--compact td,
.nd-table--compact th,
html[data-nd-density='compact'] .nd-table td,
html[data-nd-density='compact'] .nd-table th {
  padding-top: 6px;
  padding-bottom: 6px;
}

/* ── ** ── ** Wave 20aay — ** forced-colors / contrast harden ── ** ── */
@media (forced-colors: active) {
  .nt-btn,
  .nd-btn,
  .nt-badge,
  .nd-badge,
  .nt-shift-strip__chip,
  .nt-plane-chip,
  .nt-tickets__queue-item,
  .nt-nav__item {
    border: 1px solid ButtonText;
  }
  .nt-nav__item[aria-current='page'],
  .nd-tabs__trigger--active,
  .nt-tickets__queue-item--active {
    outline: 2px solid Highlight;
  }
  .nt-health-bar__fill,
  .nd-progress__fill,
  .nt-empty-wake__mark,
  .nt-brand-mark {
    forced-color-adjust: none;
  }
}
@media (prefers-contrast: more) {
  .nt-section-panel,
  .nt-filter-bar,
  .nt-toast,
  .nd-toast,
  .nt-drawer,
  .nd-modal {
    border-width: 2px;
  }
  .nt-text-secondary,
  .nd-empty__desc {
    color: var(--nd-text);
  }
}

/* ── ** ── ** Wave 20aaz — ** root vignette soft NOC ── ** ── */
html[data-nd-theme] body::before {
  content: '';
  pointer-events: none;
  position: fixed;
  inset: 0;
  z-index: 0;
  background:
    radial-gradient(120% 80% at 50% -10%,
      color-mix(in srgb, var(--nd-accent) 6%, transparent),
      transparent 45%),
    radial-gradient(80% 60% at 100% 100%,
      color-mix(in srgb, black 28%, transparent),
      transparent 50%);
}
html[data-nd-theme] #root,
html[data-nd-theme] .nt-app-root {
  position: relative;
  z-index: 1;
}

/* ── ** ── ** Wave 20aba — ** client signal bars ── ** ── */
.nt-signal,
.nd-signal,
.nt-client-signal {
  display: inline-flex;
  align-items: flex-end;
  gap: 2px;
  height: 14px;
  width: 18px;
}
.nt-signal span,
.nd-signal span,
.nt-client-signal span {
  flex: 1 1 auto;
  border-radius: 1px;
  background: color-mix(in srgb, var(--nd-text-tertiary) 45%, transparent);
  min-width: 3px;
}
.nt-signal span:nth-child(1),
.nt-client-signal span:nth-child(1) { height: 30%; }
.nt-signal span:nth-child(2),
.nt-client-signal span:nth-child(2) { height: 55%; }
.nt-signal span:nth-child(3),
.nt-client-signal span:nth-child(3) { height: 75%; }
.nt-signal span:nth-child(4),
.nt-client-signal span:nth-child(4) { height: 100%; }
.nt-signal[data-level='1'] span:nth-child(-n+1),
.nt-signal[data-level='2'] span:nth-child(-n+2),
.nt-signal[data-level='3'] span:nth-child(-n+3),
.nt-signal[data-level='4'] span:nth-child(-n+4),
.nt-client-signal[data-level='1'] span:nth-child(-n+1),
.nt-client-signal[data-level='2'] span:nth-child(-n+2),
.nt-client-signal[data-level='3'] span:nth-child(-n+3),
.nt-client-signal[data-level='4'] span:nth-child(-n+4) {
  background: var(--nd-success);
}
.nt-signal[data-level='0'] span,
.nt-client-signal[data-level='0'] span,
.nt-signal[data-level='weak'] span:nth-child(-n+1),
.nt-client-signal[data-level='weak'] span:nth-child(-n+1) {
  background: var(--nd-warning);
}

/* ── ** ── ** Wave 20abb — ** compliance / auth panels ── ** ── */
.nt-compliance-card,
.nt-auth-panel {
  padding: 14px 16px;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 78%, transparent);
  background:
    linear-gradient(160deg,
      color-mix(in srgb, var(--nd-surface-2) 24%, transparent),
      color-mix(in srgb, var(--nd-surface-1) 90%, transparent));
  box-shadow: inset 0 1px 0 color-mix(in srgb, white 4%, transparent);
}
.nt-compliance-card[data-state='fail'] {
  border-color: color-mix(in srgb, var(--nd-danger) 32%, var(--nd-border));
  box-shadow: inset 3px 0 0 var(--nd-danger);
}
.nt-compliance-card[data-state='warn'] {
  border-color: color-mix(in srgb, var(--nd-warning) 32%, var(--nd-border));
  box-shadow: inset 3px 0 0 var(--nd-warning);
}
.nt-compliance-card[data-state='pass'] {
  box-shadow: inset 3px 0 0 var(--nd-success);
}

/* ── ** ── ** Wave 20abc — ** overview war board ── ** ── */
.nt-overview-board,
.nt-war-board {
  display: grid;
  grid-template-columns: repeat(12, 1fr);
  gap: 12px;
}
.nt-overview-board > .nt-span-3,
.nt-war-board > .nt-span-3 { grid-column: span 3; }
.nt-overview-board > .nt-span-4,
.nt-war-board > .nt-span-4 { grid-column: span 4; }
.nt-overview-board > .nt-span-6,
.nt-war-board > .nt-span-6 { grid-column: span 6; }
.nt-overview-board > .nt-span-8,
.nt-war-board > .nt-span-8 { grid-column: span 8; }
.nt-overview-board > .nt-span-12,
.nt-war-board > .nt-span-12 { grid-column: span 12; }
@media (max-width: 1100px) {
  .nt-overview-board > .nt-span-3,
  .nt-overview-board > .nt-span-4,
  .nt-war-board > .nt-span-3,
  .nt-war-board > .nt-span-4 { grid-column: span 6; }
}
@media (max-width: 720px) {
  .nt-overview-board > *,
  .nt-war-board > * { grid-column: span 12; }
}

/* ── ** ── ** Wave 20abd — ** notify popover list ── ** ── */
.nt-notify-panel,
.nd-notify-panel {
  width: min(360px, 92vw);
  max-height: min(480px, 70vh);
  display: flex;
  flex-direction: column;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 78%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 96%, transparent);
  box-shadow: 0 20px 48px color-mix(in srgb, black 30%, transparent);
  overflow: hidden;
}
.nt-notify-panel__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 12px 14px;
  border-bottom: 1px solid color-mix(in srgb, var(--nd-border) 70%, transparent);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--nd-text-tertiary);
}
.nt-notify-list {
  overflow: auto;
  flex: 1;
  min-height: 0;
}
.nt-notify-item {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 10px;
  padding: 12px 14px;
  border-bottom: 1px solid color-mix(in srgb, var(--nd-border) 55%, transparent);
  cursor: pointer;
}
.nt-notify-item:hover {
  background: color-mix(in srgb, var(--nd-surface-2) 35%, transparent);
}
.nt-notify-item[data-unread='true'] {
  box-shadow: inset 3px 0 0 var(--nd-accent);
  background: color-mix(in srgb, var(--nd-accent) 6%, transparent);
}
.nt-notify-item__title {
  font-size: 13px;
  font-weight: 650;
  color: var(--nd-text);
}
.nt-notify-item__meta {
  font-size: 11px;
  color: var(--nd-text-tertiary);
  margin-top: 2px;
}

/* ── ** ── ** Wave 20abe — ** platforms nav collapsed group ── ** ── */
.nt-nav-platforms,
.nt-platforms-group {
  margin-top: 4px;
}
.nt-nav-platforms__toggle,
.nt-platforms-group__toggle {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 8px 12px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: var(--nd-text-tertiary);
  font: inherit;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  cursor: pointer;
}
.nt-nav-platforms__toggle:hover,
.nt-platforms-group__toggle:hover {
  color: var(--nd-text-secondary);
  background: color-mix(in srgb, var(--nd-surface-2) 30%, transparent);
}
.nt-nav-platforms__list[data-open='false'],
.nt-platforms-group__list[hidden] {
  display: none;
}
.nt-nav-platforms__list {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding-left: 8px;
}

/* ── ** ── ** Wave 20abf — ** visual ref / diagnostics shell ── ** ── */
.nt-visual-ref,
.nt-diagnostics {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.nt-visual-ref__frame {
  border-radius: 12px;
  border: 1px dashed color-mix(in srgb, var(--nd-border) 75%, transparent);
  background: color-mix(in srgb, var(--nd-surface-0) 50%, transparent);
  min-height: 180px;
  overflow: hidden;
}
.nt-diagnostics__row {
  display: grid;
  grid-template-columns: 140px 1fr auto;
  gap: 10px;
  align-items: center;
  padding: 8px 10px;
  border-radius: 8px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 65%, transparent);
  font-size: 12px;
}
@media (max-width: 640px) {
  .nt-diagnostics__row { grid-template-columns: 1fr; }
}

/* ── ** ── ** Wave 20abg — ** skeleton block polish ── ** ── */
.nd-skeleton,
.nt-skeleton {
  display: block;
  border-radius: 8px;
  background:
    linear-gradient(90deg,
      color-mix(in srgb, var(--nd-surface-2) 55%, transparent) 0%,
      color-mix(in srgb, var(--nd-surface-1) 80%, transparent) 50%,
      color-mix(in srgb, var(--nd-surface-2) 55%, transparent) 100%);
  background-size: 200% 100%;
  animation: nt-skel-shimmer 1.4s ease-in-out infinite;
}
.nd-skeleton--text,
.nt-skeleton--text {
  height: 12px;
  width: var(--nd-skel-w, 60%);
  border-radius: 6px;
}
.nd-skeleton--circle,
.nt-skeleton--circle {
  width: var(--nd-skel-s, 32px);
  height: var(--nd-skel-s, 32px);
  border-radius: 50%;
}
.nd-skeleton--card,
.nt-skeleton--card {
  height: var(--nd-skel-h, 88px);
  width: 100%;
  border-radius: 12px;
}
@keyframes nt-skel-shimmer {
  0% { background-position: 100% 0; }
  100% { background-position: -100% 0; }
}
@media (prefers-reduced-motion: reduce) {
  .nd-skeleton,
  .nt-skeleton { animation: none; }
}

/* ── ** ── ** Wave 20abh — ** form field stack ── ** ── */
.nt-field-stack,
.nd-field-stack {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.nt-field-label,
.nd-field-label {
  font-size: 11px;
  font-weight: 750;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--nd-text-tertiary);
}
.nt-field-hint,
.nd-field-hint {
  font-size: 12px;
  color: var(--nd-text-tertiary);
  line-height: 1.35;
}
.nt-field-error,
.nd-field-error {
  font-size: 12px;
  color: var(--nd-danger);
  font-weight: 600;
}
.nt-form-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 12px 14px;
}

/* ── ** ── ** Wave 20abi — ** select / checkbox / switch ── ** ── */
.nt-select,
.nd-select {
  appearance: none;
  width: 100%;
  border-radius: 9px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 80%, transparent);
  background:
    linear-gradient(45deg, transparent 50%, var(--nd-text-tertiary) 50%) calc(100% - 14px) calc(50% - 2px) / 5px 5px no-repeat,
    linear-gradient(135deg, var(--nd-text-tertiary) 50%, transparent 50%) calc(100% - 10px) calc(50% - 2px) / 5px 5px no-repeat,
    color-mix(in srgb, var(--nd-surface-0) 60%, transparent);
  color: var(--nd-text);
  font: inherit;
  font-size: 13px;
  padding: 8px 28px 8px 10px;
}
.nt-select:focus-visible,
.nd-select:focus-visible {
  outline: none;
  border-color: color-mix(in srgb, var(--nd-accent) 45%, var(--nd-border));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--nd-focus-ring, var(--nd-accent)) 22%, transparent);
}
.nt-checkbox,
.nd-checkbox {
  width: 16px;
  height: 16px;
  accent-color: var(--nd-accent);
  border-radius: 4px;
}
.nt-switch,
.nd-switch {
  position: relative;
  width: 40px;
  height: 22px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 75%, transparent);
  background: color-mix(in srgb, var(--nd-surface-0) 70%, transparent);
  cursor: pointer;
  transition: background 120ms ease, border-color 120ms ease;
}
.nt-switch::after,
.nd-switch::after {
  content: '';
  position: absolute;
  top: 2px;
  left: 2px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--nd-text-secondary);
  transition: transform 120ms ease, background 120ms ease;
}
.nt-switch[aria-checked='true'],
.nt-switch[data-checked='true'],
.nd-switch[aria-checked='true'] {
  background: color-mix(in srgb, var(--nd-accent) 55%, var(--nd-surface-1));
  border-color: color-mix(in srgb, var(--nd-accent) 40%, var(--nd-border));
}
.nt-switch[aria-checked='true']::after,
.nt-switch[data-checked='true']::after,
.nd-switch[aria-checked='true']::after {
  transform: translateX(18px);
  background: var(--nd-accent-fg, white);
}
@media (prefers-reduced-motion: reduce) {
  .nt-switch, .nd-switch, .nt-switch::after, .nd-switch::after { transition: none; }
}

/* ── ** ── ** Wave 20abj — ** menu / dropdown cinema ── ** ── */
.nt-menu,
.nd-menu {
  min-width: 180px;
  padding: 6px;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 78%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 96%, transparent);
  box-shadow: 0 16px 40px color-mix(in srgb, black 30%, transparent);
  backdrop-filter: blur(10px);
  z-index: var(--nd-z-dropdown, 30);
}
.nt-menu__item,
.nd-menu__item {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 8px 10px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--nd-text-secondary);
  font: inherit;
  font-size: 13px;
  text-align: left;
  cursor: pointer;
}
.nt-menu__item:hover,
.nt-menu__item[data-highlighted='true'],
.nd-menu__item:hover {
  color: var(--nd-text);
  background: color-mix(in srgb, var(--nd-surface-2) 50%, transparent);
}
.nt-menu__item[data-danger='true'],
.nd-menu__item--danger {
  color: var(--nd-danger);
}
.nt-menu__sep,
.nd-menu__sep {
  height: 1px;
  margin: 6px 4px;
  background: color-mix(in srgb, var(--nd-border) 70%, transparent);
  border: 0;
}

/* ── ** ── ** Wave 20abk — ** code / mono block ── ** ── */
.nt-code,
.nd-code,
.nt-mono-block {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 12px;
  line-height: 1.45;
  padding: 12px 14px;
  border-radius: 10px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 75%, transparent);
  background: color-mix(in srgb, var(--nd-surface-0) 70%, transparent);
  color: var(--nd-text-secondary);
  overflow: auto;
  white-space: pre;
}
.nt-inline-code {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 0.92em;
  padding: 1px 6px;
  border-radius: 5px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 65%, transparent);
  background: color-mix(in srgb, var(--nd-surface-0) 55%, transparent);
  color: color-mix(in srgb, var(--nd-accent) 55%, var(--nd-text));
}

/* ── ** ── ** Wave 20abl — ** safe-area shell padding ── ** ── */
.nt-app-root,
.nd-app-root {
  padding-left: env(safe-area-inset-left, 0px);
  padding-right: env(safe-area-inset-right, 0px);
}
.nt-topbar,
.nd-topbar {
  padding-left: max(14px, env(safe-area-inset-left, 0px));
  padding-right: max(14px, env(safe-area-inset-right, 0px));
}
.nt-shell-main,
.nd-shell-main,
.nt-main {
  padding-bottom: max(28px, env(safe-area-inset-bottom, 0px));
}

/* ── ** ── ** Wave 20abm — ** shell brand block ── ** ── */
.nt-shell-brand {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  padding: 4px 0;
}
.nt-shell-brand__mark.nt-brand-mark,
.nt-shell-brand__mark {
  width: 32px;
  height: 32px;
  border-radius: 9px;
  display: grid;
  place-items: center;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.04em;
  color: var(--nd-accent-fg, var(--nd-surface-0));
  background: linear-gradient(145deg, var(--nd-accent), color-mix(in srgb, var(--nd-accent) 55%, black));
  box-shadow:
    0 8px 18px color-mix(in srgb, var(--nd-accent) 28%, transparent),
    inset 0 1px 0 color-mix(in srgb, white 22%, transparent);
  flex: 0 0 auto;
}
.nt-logo-mark {
  display: none; /* dual mark fallback hidden when brand mark present */
}
.nt-shell-brand__copy {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 1px;
}
.nt-shell-brand__kicker {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--nd-text-tertiary);
}
.nt-shell-brand__name {
  font-size: 15px;
  font-weight: 850;
  letter-spacing: -0.02em;
  color: var(--nd-text);
  line-height: 1.1;
}
.nt-shell-brand__tagline {
  font-size: 11px;
  color: color-mix(in srgb, var(--nd-accent) 55%, var(--nd-text-secondary));
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ── ** ── ** Wave 20abn — ** shell navitem dual-class ── ** ── */
.nd-navitem.nt-navitem,
.nt-sidebar-nav__item.nt-navitem,
.nt-navitem {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 8px 10px;
  border-radius: 10px;
  border: 0;
  background: transparent;
  color: var(--nd-text-secondary);
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  text-align: left;
  text-decoration: none;
  cursor: pointer;
  transition: background 120ms ease, color 120ms ease, box-shadow 120ms ease;
}
.nd-navitem:hover,
.nt-navitem:hover {
  color: var(--nd-text);
  background: color-mix(in srgb, var(--nd-surface-2) 42%, transparent);
}
.nd-navitem--active.nt-navitem--active,
.nt-navitem--active,
.nd-navitem[aria-current='page'] {
  color: var(--nd-text);
  background: color-mix(in srgb, var(--nd-accent) 11%, var(--nd-surface-1));
  box-shadow: inset 3px 0 0 var(--nd-accent);
}
.nd-navitem__icon.nt-navitem__icon,
.nt-navitem__icon {
  width: 18px;
  display: inline-grid;
  place-items: center;
  opacity: 0.85;
  flex: 0 0 auto;
}
.nd-navitem__label.nt-navitem__label,
.nt-navitem__label {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ── ** ── ** Wave 20abo — ** platforms navgroup collapse ── ** ── */
.nt-shell-navgroup {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin-bottom: 8px;
}
.nt-shell-navgroup__label,
.nt-micro-label.nd-micro-label {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--nd-text-tertiary);
}
.nt-shell-navgroup__toggle.nt-platforms-group__toggle {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 8px 10px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  cursor: pointer;
  color: var(--nd-text-tertiary);
}
.nt-shell-navgroup__toggle:hover {
  color: var(--nd-text-secondary);
  background: color-mix(in srgb, var(--nd-surface-2) 30%, transparent);
}
.nt-shell-navgroup__chev {
  font-size: 10px;
  opacity: 0.7;
  transition: transform 120ms ease;
}
.nt-shell-navgroup--collapsed .nt-shell-navgroup__chev {
  transform: rotate(-90deg);
}
.nt-shell-navgroup--platforms.nt-shell-navgroup--collapsed > :not(.nt-shell-navgroup__toggle):not(.nt-shell-navgroup__label) {
  display: none;
}
@media (prefers-reduced-motion: reduce) {
  .nt-shell-navgroup__chev { transition: none; }
}

/* ── ** ── ** Wave 20abp — ** notify popover live ── ** ── */
.nt-notify-anchor {
  position: relative;
}
.nt-notify-bell--hot {
  color: var(--nd-danger);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--nd-danger) 18%, transparent);
  border-radius: 8px;
}
.nt-notify-popover.nt-panel-glass,
.nt-notify-popover {
  position: absolute;
  right: 0;
