  border: 1px solid color-mix(in srgb, var(--nd-border) 70%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 80%, transparent);
  font-size: 11px;
  color: var(--nd-text-secondary);
}
.nt-topo-legend__swatch {
  width: 10px;
  height: 10px;
  border-radius: 3px;
  display: inline-block;
  margin-right: 6px;
  background: var(--nd-accent);
  vertical-align: -1px;
}
.nt-topo-legend__item[data-tone='danger'] .nt-topo-legend__swatch { background: var(--nd-danger); }
.nt-topo-legend__item[data-tone='warning'] .nt-topo-legend__swatch { background: var(--nd-warning); }
.nt-topo-legend__item[data-tone='success'] .nt-topo-legend__swatch { background: var(--nd-success); }

/* ── ** ── ** Wave 20acf — ** settings / coach shell ── ** ── */
.nt-settings-shell,
.nt-coach-shell {
  display: grid;
  grid-template-columns: minmax(200px, 240px) minmax(0, 1fr);
  gap: 16px;
}
@media (max-width: 840px) {
  .nt-settings-shell,
  .nt-coach-shell { grid-template-columns: 1fr; }
}
.nt-settings-nav {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 8px;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 75%, transparent);
  background: color-mix(in srgb, var(--nd-surface-0) 50%, transparent);
  height: fit-content;
  position: sticky;
  top: 48px;
}
.nt-settings-nav__item {
  padding: 8px 10px;
  border-radius: 8px;
  border: 0;
  background: transparent;
  color: var(--nd-text-secondary);
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  text-align: left;
  cursor: pointer;
}
.nt-settings-nav__item:hover {
  color: var(--nd-text);
  background: color-mix(in srgb, var(--nd-surface-2) 40%, transparent);
}
.nt-settings-nav__item[aria-current='page'],
.nt-settings-nav__item[data-active='true'] {
  color: var(--nd-text);
  background: color-mix(in srgb, var(--nd-accent) 10%, var(--nd-surface-1));
  box-shadow: inset 3px 0 0 var(--nd-accent);
}
.nt-settings-panel {
  padding: 16px;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 78%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 85%, transparent);
}

/* ── ** ── ** Wave 20acg — ** overview KPI board density ── ** ── */
.nt-overview-kpis,
.nt-kpi-board {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 10px;
}
.nt-overview-kpis .nt-kpi,
.nt-kpi-board .nt-kpi {
  min-height: 88px;
}
.nt-kpi__label {
  font-size: 11px;
  font-weight: 750;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--nd-text-tertiary);
}
.nt-kpi__value {
  margin-top: 6px;
  font-size: 24px;
  font-weight: 850;
  letter-spacing: -0.03em;
  font-variant-numeric: tabular-nums;
  color: var(--nd-text);
  line-height: 1.1;
}
.nt-kpi__delta {
  margin-top: 4px;
  font-size: 12px;
  font-weight: 650;
  font-variant-numeric: tabular-nums;
  color: var(--nd-text-tertiary);
}
.nt-kpi__delta[data-tone='positive'] { color: var(--nd-success); }
.nt-kpi__delta[data-tone='negative'] { color: var(--nd-danger); }

/* ── ** ── ** Wave 20ach — ** alert list row cinema ── ** ── */
.nt-alert-row,
.nt-alerts__row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 10px 12px;
  align-items: center;
  padding: 10px 12px;
  border-radius: 10px;
  border: 1px solid transparent;
  background: transparent;
  cursor: pointer;
  transition: background 120ms ease, border-color 120ms ease, box-shadow 120ms ease;
}
.nt-alert-row:hover,
.nt-alerts__row:hover {
  background: color-mix(in srgb, var(--nd-surface-1) 70%, transparent);
  border-color: color-mix(in srgb, var(--nd-border) 60%, transparent);
}
.nt-alert-row[aria-selected='true'],
.nt-alert-row--active,
.nt-alerts__row[aria-selected='true'] {
  background: color-mix(in srgb, var(--nd-accent) 9%, var(--nd-surface-1));
  border-color: color-mix(in srgb, var(--nd-accent) 28%, var(--nd-border));
  box-shadow: inset 3px 0 0 var(--nd-accent);
}
.nt-alert-row[data-sev='p1'],
.nt-alerts__row[data-sev='p1'] {
  box-shadow: inset 3px 0 0 var(--nd-danger);
}
.nt-alert-row__title {
  font-size: 13px;
  font-weight: 650;
  color: var(--nd-text);
  line-height: 1.3;
}
.nt-alert-row__meta {
  font-size: 11px;
  color: var(--nd-text-tertiary);
  margin-top: 2px;
}
@media (prefers-reduced-motion: reduce) {
  .nt-alert-row,
  .nt-alerts__row { transition: none; }
}

/* ── ** ── ** Wave 20aci — ** client row signal densify ── ** ── */
.nt-client-row {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr) auto auto;
  gap: 10px;
  align-items: center;
  padding: 10px 12px;
  border-radius: 10px;
  border: 1px solid transparent;
}
.nt-client-row:hover {
  background: color-mix(in srgb, var(--nd-surface-1) 65%, transparent);
  border-color: color-mix(in srgb, var(--nd-border) 55%, transparent);
}
.nt-client-row__name {
  font-size: 13px;
  font-weight: 650;
  color: var(--nd-text);
}
.nt-client-row__sub {
  font-size: 11px;
  color: var(--nd-text-tertiary);
  margin-top: 2px;
}
@media (max-width: 720px) {
  .nt-client-row { grid-template-columns: 1fr auto; }
}

/* ── ** ── ** Wave 20acj — ** configure queue sticky ── ** ── */
.nt-configure-queue {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 75%, transparent);
  background: color-mix(in srgb, var(--nd-surface-0) 50%, transparent);
  max-height: min(60vh, 560px);
  overflow: auto;
}
.nt-configure-queue__item {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  padding: 10px 12px;
  border-radius: 10px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 65%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 75%, transparent);
}
.nt-configure-queue__item[data-state='pending'] {
  box-shadow: inset 3px 0 0 var(--nd-warning);
}
.nt-configure-queue__item[data-state='ready'] {
  box-shadow: inset 3px 0 0 var(--nd-accent);
}
.nt-configure-queue__item[data-state='done'] {
  box-shadow: inset 3px 0 0 var(--nd-success);
  opacity: 0.78;
}

/* ── ** ── ** Wave 20ack — ** inventory tree cinema ── ** ── */
.nt-inventory-tree,
.nt-tree {
  display: flex;
  flex-direction: column;
  gap: 2px;
  font-size: 13px;
}
.nt-tree__node {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 8px;
  border-radius: 8px;
  color: var(--nd-text-secondary);
  cursor: pointer;
}
.nt-tree__node:hover {
  color: var(--nd-text);
  background: color-mix(in srgb, var(--nd-surface-2) 40%, transparent);
}
.nt-tree__node[aria-selected='true'],
.nt-tree__node--active {
  color: var(--nd-text);
  background: color-mix(in srgb, var(--nd-accent) 10%, var(--nd-surface-1));
  box-shadow: inset 3px 0 0 var(--nd-accent);
}
.nt-tree__children {
  padding-left: 16px;
  border-left: 1px solid color-mix(in srgb, var(--nd-border) 55%, transparent);
  margin-left: 12px;
}

/* ── ** ── ** Wave 20acl — ** webhook / integration cards ── ** ── */
.nt-webhook-card,
.nt-integration-card {
  padding: 14px;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 75%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 88%, transparent);
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.nt-webhook-card[data-state='disabled'],
.nt-integration-card[data-state='disabled'] {
  opacity: 0.7;
}
.nt-webhook-card[data-state='error'],
.nt-integration-card[data-state='error'] {
  border-color: color-mix(in srgb, var(--nd-danger) 32%, var(--nd-border));
  box-shadow: inset 3px 0 0 var(--nd-danger);
}
.nt-webhook-card__url {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 11px;
  color: var(--nd-text-tertiary);
  word-break: break-all;
}

/* ── ** ── ** Wave 20acm — ** data freshness / poll age ── ** ── */
.nt-freshness,
.nd-freshness,
.nt-poll-age {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  font-weight: 650;
  font-variant-numeric: tabular-nums;
  color: var(--nd-text-tertiary);
}
.nt-freshness[data-state='fresh'],
.nt-poll-age[data-state='fresh'] { color: var(--nd-success); }
.nt-freshness[data-state='stale'],
.nt-poll-age[data-state='stale'] { color: var(--nd-warning); }
.nt-freshness[data-state='dead'],
.nt-poll-age[data-state='dead'] { color: var(--nd-danger); }
.nt-freshness__dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}

/* ── ** ── ** Wave 20acn — ** action bar sticky bottom ── ** ── */
.nt-action-bar,
.nd-action-bar {
  position: sticky;
  bottom: 0;
  z-index: var(--nd-z-sticky, 10);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 12px;
  padding: 10px 14px;
  border-radius: 12px 12px 0 0;
  border: 1px solid color-mix(in srgb, var(--nd-border) 78%, transparent);
  border-bottom: 0;
  background: color-mix(in srgb, var(--nd-surface-1) 92%, transparent);
  backdrop-filter: blur(10px);
  box-shadow: 0 -12px 28px color-mix(in srgb, black 16%, transparent);
}
.nt-action-bar__grow { flex: 1 1 auto; min-width: 8px; }

/* ── ** ── ** Wave 20aco — ** tag / chip input ── ** ── */
.nt-chip-input,
.nd-chip-input {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
  min-height: 38px;
  padding: 6px 8px;
  border-radius: 9px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 80%, transparent);
  background: color-mix(in srgb, var(--nd-surface-0) 55%, transparent);
}
.nt-chip-input:focus-within,
.nd-chip-input:focus-within {
  border-color: color-mix(in srgb, var(--nd-accent) 45%, var(--nd-border));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--nd-focus-ring, var(--nd-accent)) 22%, transparent);
}
.nt-chip,
.nd-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 650;
  border: 1px solid color-mix(in srgb, var(--nd-border) 70%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2) 45%, transparent);
  color: var(--nd-text-secondary);
}
.nt-chip__remove,
.nd-chip__remove {
  border: 0;
  background: transparent;
  color: var(--nd-text-tertiary);
  cursor: pointer;
  padding: 0 2px;
  border-radius: 4px;
  line-height: 1;
}
.nt-chip__remove:hover,
.nd-chip__remove:hover { color: var(--nd-text); }

/* ── ** ── ** Wave 20acp — ** metric spark + label ── ** ── */
.nt-metric,
.nd-metric {
  display: inline-flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}
.nt-metric__label {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--nd-text-tertiary);
}
.nt-metric__value {
  font-size: 16px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.02em;
  color: var(--nd-text);
}
.nt-metric__row {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

/* ── ** ── ** Wave 20acq — ** split button / button group ── ** ── */
.nt-btn-group,
.nd-btn-group {
  display: inline-flex;
  align-items: stretch;
}
.nt-btn-group > .nt-btn,
.nt-btn-group > .nd-btn,
.nd-btn-group > .nd-btn {
  border-radius: 0;
}
.nt-btn-group > :first-child,
.nd-btn-group > :first-child {
  border-top-left-radius: 9px;
  border-bottom-left-radius: 9px;
}
.nt-btn-group > :last-child,
.nd-btn-group > :last-child {
  border-top-right-radius: 9px;
  border-bottom-right-radius: 9px;
}
.nt-btn-group > :not(:first-child),
.nd-btn-group > :not(:first-child) {
  margin-left: -1px;
}

/* ── ** ── ** Wave 20acr — ** prose / help content ── ** ── */
.nt-prose,
.nd-prose {
  font-size: 13px;
  line-height: 1.55;
  color: var(--nd-text-secondary);
  max-width: 68ch;
}
.nt-prose h1, .nt-prose h2, .nt-prose h3,
.nd-prose h1, .nd-prose h2, .nd-prose h3 {
  color: var(--nd-text);
  letter-spacing: -0.02em;
  line-height: 1.25;
  margin: 1.2em 0 0.45em;
}
.nt-prose p, .nd-prose p { margin: 0.55em 0; }
.nt-prose ul, .nd-prose ol,
.nd-prose ul, .nd-prose ol {
  padding-left: 1.25em;
  margin: 0.55em 0;
}
.nt-prose a, .nd-prose a {
  color: color-mix(in srgb, var(--nd-accent) 75%, var(--nd-text));
  text-underline-offset: 2px;
}
.nt-prose code, .nd-prose code {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 0.92em;
  padding: 1px 5px;
  border-radius: 4px;
  background: color-mix(in srgb, var(--nd-surface-0) 60%, transparent);
  border: 1px solid color-mix(in srgb, var(--nd-border) 60%, transparent);
}

/* ── ** ── ** Wave 20acs — ** empty filter / zero results ── ** ── */
.nt-zero-results,
.nd-zero-results {
  padding: 28px 16px;
  text-align: center;
  border-radius: 12px;
  border: 1px dashed color-mix(in srgb, var(--nd-border) 70%, transparent);
  background: color-mix(in srgb, var(--nd-surface-0) 40%, transparent);
  color: var(--nd-text-secondary);
  font-size: 13px;
}
.nt-zero-results__title {
  font-weight: 750;
  color: var(--nd-text);
  margin-bottom: 4px;
}
.nt-zero-results__hint {
  font-size: 12px;
  color: var(--nd-text-tertiary);
}

/* ── ** ── ** Wave 20act — ** link / ghost / icon buttons ── ** ── */
.nd-btn--ghost.nt-btn,
.nd-btn.nd-btn--ghost,
.nt-btn--ghost {
  background: transparent;
  border-color: transparent;
  color: var(--nd-text-secondary);
  box-shadow: none;
}
.nd-btn--ghost:hover:not(:disabled),
.nt-btn--ghost:hover:not(:disabled) {
  color: var(--nd-text);
  background: color-mix(in srgb, var(--nd-surface-2) 45%, transparent);
  filter: none;
}
.nd-btn--link.nt-btn,
.nd-btn.nd-btn--link,
.nt-btn--link {
  background: transparent;
  border-color: transparent;
  color: color-mix(in srgb, var(--nd-accent) 80%, var(--nd-text));
  box-shadow: none;
  padding-left: 4px;
  padding-right: 4px;
}
.nd-btn--link:hover:not(:disabled),
.nt-btn--link:hover:not(:disabled) {
  text-decoration: underline;
  text-underline-offset: 2px;
  filter: none;
  background: transparent;
}
.nd-btn--icon.nt-btn,
.nd-btn.nd-btn--icon,
.nt-btn--icon {
  width: 34px;
  height: 34px;
  padding: 0;
  border-radius: 9px;
}

/* ── ** ── ** Wave 20acu — ** panel header / toolbar ── ** ── */
.nt-panel-header,
.nd-panel-header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding-bottom: 10px;
  margin-bottom: 10px;
  border-bottom: 1px solid color-mix(in srgb, var(--nd-border) 65%, transparent);
}
.nt-panel-header__title {
  font-size: 14px;
  font-weight: 750;
  color: var(--nd-text);
  letter-spacing: -0.01em;
}
.nt-panel-header__meta {
  font-size: 12px;
  color: var(--nd-text-tertiary);
}
.nt-toolbar,
.nd-toolbar,
.nt-toolbar-glass {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}
.nt-toolbar-glass {
  padding: 6px 8px;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 70%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 70%, transparent);
  backdrop-filter: blur(8px);
}

/* ── ** ── ** Wave 20acv — ** status strip / banner tones ── ** ── */
.nt-status-strip,
.nd-status-strip {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 12px;
  padding: 8px 12px;
  border-radius: 10px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 75%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 80%, transparent);
  font-size: 12px;
  color: var(--nd-text-secondary);
}
.nt-status-strip[data-tone='success'],
.nd-status-strip[data-tone='success'] {
  border-color: color-mix(in srgb, var(--nd-success) 30%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-success) 8%, var(--nd-surface-1));
}
.nt-status-strip[data-tone='warning'],
.nd-status-strip[data-tone='warning'] {
  border-color: color-mix(in srgb, var(--nd-warning) 30%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-warning) 8%, var(--nd-surface-1));
}
.nt-status-strip[data-tone='danger'],
.nd-status-strip[data-tone='danger'] {
  border-color: color-mix(in srgb, var(--nd-danger) 30%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-danger) 8%, var(--nd-surface-1));
}
.nt-status-strip[data-tone='info'],
.nd-status-strip[data-tone='info'] {
  border-color: color-mix(in srgb, var(--nd-info, var(--nd-accent)) 30%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-info, var(--nd-accent)) 8%, var(--nd-surface-1));
}

/* ── ** ── ** Wave 20acw — ** file dropzone ── ** ── */
.nt-dropzone,
.nd-dropzone {
  display: grid;
  place-items: center;
  text-align: center;
  gap: 8px;
  padding: 28px 16px;
  border-radius: 14px;
  border: 1px dashed color-mix(in srgb, var(--nd-border) 80%, transparent);
  background: color-mix(in srgb, var(--nd-surface-0) 45%, transparent);
  color: var(--nd-text-secondary);
  font-size: 13px;
  transition: border-color 120ms ease, background 120ms ease, box-shadow 120ms ease;
}
.nt-dropzone[data-active='true'],
.nd-dropzone[data-active='true'],
.nt-dropzone:focus-within {
  border-color: color-mix(in srgb, var(--nd-accent) 45%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-accent) 8%, var(--nd-surface-1));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--nd-accent) 16%, transparent);
}
.nt-dropzone__title {
  font-weight: 750;
  color: var(--nd-text);
}

/* ── ** ── ** Wave 20acx — ** step wizard ── ** ── */
.nt-wizard,
.nd-wizard {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.nt-wizard__steps {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}
.nt-wizard__step {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 70%, transparent);
  background: color-mix(in srgb, var(--nd-surface-0) 45%, transparent);
  font-size: 12px;
  font-weight: 650;
  color: var(--nd-text-tertiary);
}
.nt-wizard__step[data-state='done'] {
  color: var(--nd-success);
  border-color: color-mix(in srgb, var(--nd-success) 30%, var(--nd-border));
}
.nt-wizard__step[data-state='active'] {
  color: var(--nd-text);
  border-color: color-mix(in srgb, var(--nd-accent) 35%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-accent) 10%, var(--nd-surface-1));
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--nd-accent) 18%, transparent);
}
.nt-wizard__index {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 10px;
  font-weight: 800;
  background: color-mix(in srgb, var(--nd-surface-2) 55%, transparent);
  color: inherit;
}

/* ── ** ── ** Wave 20acy — ** avatar stack ── ** ── */
.nt-avatar-stack,
.nd-avatar-stack {
  display: inline-flex;
  flex-direction: row-reverse;
  justify-content: flex-end;
}
.nt-avatar-stack .nt-avatar,
