  .nt-shell-main,
  .nt-main-canvas,
  .nd-shell__content {
    padding-top: 10px;
    padding-bottom: 16px;
  }
}

/* ── ** ── ** Wave 20aee — ** copper rule variants ── ** ── */
.nt-copper-rule--accent {
  height: 2px;
  border: 0;
  background: linear-gradient(
    90deg,
    transparent,
    var(--nd-accent),
    transparent
  );
  margin: 14px 0;
  opacity: 0.85;
}
.nt-copper-rule--subtle {
  height: 1px;
  border: 0;
  background: color-mix(in srgb, var(--nd-border) 80%, transparent);
  margin: 10px 0;
}

/* ── ** ── ** Wave 20aef — ** status LED row ── ** ── */
.nt-led-row {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.nt-led {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--nd-text-tertiary);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--nd-text-tertiary) 12%, transparent);
  flex: 0 0 auto;
}
.nt-led--ok { background: var(--nd-success); box-shadow: 0 0 0 3px color-mix(in srgb, var(--nd-success) 18%, transparent); }
.nt-led--warn { background: var(--nd-warning); box-shadow: 0 0 0 3px color-mix(in srgb, var(--nd-warning) 18%, transparent); }
.nt-led--bad { background: var(--nd-danger); box-shadow: 0 0 0 3px color-mix(in srgb, var(--nd-danger) 18%, transparent); }
.nt-led--live {
  background: var(--nd-success);
  animation: nt-sync-ping 1.6s ease-out infinite;
}

/* ── ** ── ** Wave 20aeg — ** continuum marker 20aeg ── ** ── */
.nt-wave-20aeg {
  --nd-wave: '20aeg';
}

/* ── ** ── ** Wave 20aeh — ** number / tabular helpers ── ** ── */
.nt-tabular,
.nt-num {
  font-variant-numeric: tabular-nums;
  font-feature-settings: 'tnum' 1;
}
.nt-mono {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
}
.nt-uppercase-track {
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-weight: 800;
  font-size: 10px;
}

/* ── ** ── ** Wave 20aei — ** pill filter group ── ** ── */
.nt-pill-group {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
}
.nt-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 10px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 75%, transparent);
  background: color-mix(in srgb, var(--nd-surface-0) 50%, transparent);
  color: var(--nd-text-secondary);
  font: inherit;
  font-size: 12px;
  font-weight: 650;
  cursor: pointer;
  transition: background 120ms ease, border-color 120ms ease, color 120ms ease;
}
.nt-pill:hover {
  color: var(--nd-text);
  border-color: color-mix(in srgb, var(--nd-accent) 28%, var(--nd-border));
}
.nt-pill[aria-pressed='true'],
.nt-pill--active {
  color: var(--nd-text);
  border-color: color-mix(in srgb, var(--nd-accent) 38%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-accent) 12%, var(--nd-surface-1));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--nd-accent) 12%, transparent);
}
@media (prefers-reduced-motion: reduce) {
  .nt-pill { transition: none; }
}

/* ── ** ── ** Wave 20aej — ** inset panel / well ── ** ── */
.nt-well,
.nd-well {
  padding: 12px 14px;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 70%, transparent);
  background:
    linear-gradient(180deg,
      color-mix(in srgb, black 10%, transparent),
      transparent 40%),
    color-mix(in srgb, var(--nd-surface-0) 70%, transparent);
  box-shadow: inset 0 1px 0 color-mix(in srgb, black 12%, transparent);
}

/* ── ** ── ** Wave 20aek — ** floating action cluster ── ** ── */
.nt-fab-cluster {
  position: fixed;
  right: max(16px, env(safe-area-inset-right, 0px));
  bottom: max(16px, env(safe-area-inset-bottom, 0px));
  z-index: var(--nd-z-overlay, 40);
  display: flex;
  flex-direction: column-reverse;
  gap: 8px;
  align-items: flex-end;
}
.nt-fab {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  border: 0;
  display: grid;
  place-items: center;
  cursor: pointer;
  color: var(--nd-accent-fg, var(--nd-surface-0));
  background: linear-gradient(180deg, color-mix(in srgb, var(--nd-accent) 92%, white), var(--nd-accent));
  box-shadow:
    0 10px 28px color-mix(in srgb, var(--nd-accent) 35%, transparent),
    inset 0 1px 0 color-mix(in srgb, white 20%, transparent);
}
.nt-fab:hover { filter: brightness(1.06); }
.nt-fab:focus-visible {
  outline: 2px solid var(--nd-focus-ring, var(--nd-accent));
  outline-offset: 3px;
}

/* ── ** ── ** Wave 20ael — ** divider with label ── ** ── */
.nt-divider-label {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  gap: 10px;
  align-items: center;
  color: var(--nd-text-tertiary);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.nt-divider-label::before,
.nt-divider-label::after {
  content: '';
  height: 1px;
  background: color-mix(in srgb, var(--nd-border) 80%, transparent);
}

/* ── ** ── ** Wave 20aem — ** stacked meta pairs ── ** ── */
.nt-meta-pair {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
.nt-meta-pair__k {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--nd-text-tertiary);
}
.nt-meta-pair__v {
  font-size: 13px;
  font-weight: 650;
  color: var(--nd-text);
  word-break: break-word;
}

/* ── ** ── ** Wave 20aen — ** continuum 20aen ── ** ── */
.nt-wave-20aen {
  --nd-wave: '20aen';
}

/* ── ** ── ** Wave 20aeo — ** responsive container queries shell ── ** ── */
.nt-cq,
.nd-cq {
  container-type: inline-size;
}
@container (max-width: 520px) {
  .nt-cq-hide-sm { display: none !important; }
  .nt-hero-split { grid-template-columns: 1fr; }
  .nt-master-detail,
  .nd-master-detail { grid-template-columns: 1fr; }
}
@container (min-width: 900px) {
  .nt-cq-show-lg { display: initial; }
}

/* ── ** ── ** Wave 20aep — ** skeleton text block stack ── ** ── */
.nt-skel-stack {
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: 100%;
}
.nt-skel-stack > .nd-skeleton,
.nt-skel-stack > .nt-skeleton {
  width: 100%;
}
.nt-skel-stack > .nd-skeleton:nth-child(2),
.nt-skel-stack > .nt-skeleton:nth-child(2) { width: 82%; }
.nt-skel-stack > .nd-skeleton:nth-child(3),
.nt-skel-stack > .nt-skeleton:nth-child(3) { width: 64%; }

/* ── ** ── ** Wave 20aeq — ** inline alert strip ── ** ── */
.nt-inline-alert {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 10px 12px;
  border-radius: 10px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 75%, transparent);
  background: color-mix(in srgb, var(--nd-surface-1) 85%, transparent);
  font-size: 13px;
  color: var(--nd-text-secondary);
  line-height: 1.4;
}
.nt-inline-alert[data-tone='warning'] {
  border-color: color-mix(in srgb, var(--nd-warning) 32%, var(--nd-border));
  box-shadow: inset 3px 0 0 var(--nd-warning);
}
.nt-inline-alert[data-tone='danger'] {
  border-color: color-mix(in srgb, var(--nd-danger) 32%, var(--nd-border));
  box-shadow: inset 3px 0 0 var(--nd-danger);
}
.nt-inline-alert[data-tone='success'] {
  box-shadow: inset 3px 0 0 var(--nd-success);
}
.nt-inline-alert[data-tone='info'] {
  box-shadow: inset 3px 0 0 var(--nd-info, var(--nd-accent));
}

/* ── ** ── ** Wave 20aer — ** copyable mono field ── ** ── */
.nt-copy-field {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
  align-items: center;
  padding: 8px 10px;
  border-radius: 10px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 75%, transparent);
  background: color-mix(in srgb, var(--nd-surface-0) 55%, transparent);
}
.nt-copy-field__value {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 12px;
  color: var(--nd-text-secondary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ── ** ── ** Wave 20aes — ** hop latency spark ticks ── ** ── */
.nt-hop-ticks {
  display: inline-flex;
  align-items: flex-end;
  gap: 2px;
  height: 16px;
}
.nt-hop-ticks > i {
  display: block;
  width: 3px;
  border-radius: 1px;
  background: color-mix(in srgb, var(--nd-accent) 55%, transparent);
  height: var(--nd-tick, 40%);
}
.nt-hop-ticks[data-tone='warn'] > i { background: color-mix(in srgb, var(--nd-warning) 65%, transparent); }
.nt-hop-ticks[data-tone='bad'] > i { background: color-mix(in srgb, var(--nd-danger) 65%, transparent); }

/* ── ** ── ** Wave 20aet — ** estate summary strip ── ** ── */
.nt-estate-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 14px;
  align-items: center;
  padding: 10px 12px;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 75%, transparent);
  background:
    linear-gradient(90deg,
      color-mix(in srgb, var(--nd-accent) 8%, transparent),
      transparent 42%),
    color-mix(in srgb, var(--nd-surface-1) 88%, transparent);
}
.nt-estate-strip__item {
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
  font-size: 12px;
  color: var(--nd-text-secondary);
}
.nt-estate-strip__value {
  font-size: 14px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  color: var(--nd-text);
}

/* ── ** ── ** Wave 20aeu — ** continuum 20aeu ── ** ── */
.nt-wave-20aeu {
  --nd-wave: '20aeu';
}

/* ── ** ── ** Wave 20aev — ** dark-only copper bloom accents ── ** ── */
html:not([data-nd-theme='light']) .nt-empty-wake__mark,
html:not([data-nd-theme='light']) .nt-brand-mark,
html:not([data-nd-theme='light']) .nt-shell-brand__mark {
  box-shadow:
    0 10px 28px color-mix(in srgb, var(--nd-accent) 32%, transparent),
    0 0 24px color-mix(in srgb, var(--nd-accent) 18%, transparent),
    inset 0 1px 0 color-mix(in srgb, white 22%, transparent);
}
html:not([data-nd-theme='light']) .nt-shift-strip--hot {
  box-shadow:
    inset 0 -2px 0 color-mix(in srgb, var(--nd-danger) 75%, transparent),
    0 8px 24px color-mix(in srgb, var(--nd-danger) 10%, transparent);
}

/* ── ** ── ** Wave 20aew — ** operator handoff card ── ** ── */
.nt-handoff-card {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 14px;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 78%, transparent);
  background:
    linear-gradient(145deg,
      color-mix(in srgb, var(--nd-accent) 9%, transparent),
      color-mix(in srgb, var(--nd-surface-1) 92%, transparent));
}
.nt-handoff-card__title {
  font-size: 14px;
  font-weight: 750;
  color: var(--nd-text);
}
.nt-handoff-card__path {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 12px;
  color: var(--nd-text-secondary);
  word-break: break-all;
}

/* ── ** ── ** Wave 20aex — ** severity heatmap cells ── ** ── */
.nt-heatcell {
  display: inline-grid;
  place-items: center;
  min-width: 28px;
  height: 22px;
  padding: 0 6px;
  border-radius: 6px;
  font-size: 11px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  border: 1px solid color-mix(in srgb, var(--nd-border) 65%, transparent);
  background: color-mix(in srgb, var(--nd-surface-0) 55%, transparent);
  color: var(--nd-text-secondary);
}
.nt-heatcell[data-level='0'] { opacity: 0.55; }
.nt-heatcell[data-level='1'] {
  background: color-mix(in srgb, var(--nd-success) 14%, var(--nd-surface-1));
  color: var(--nd-success);
}
.nt-heatcell[data-level='2'] {
  background: color-mix(in srgb, var(--nd-warning) 16%, var(--nd-surface-1));
  color: var(--nd-warning);
}
.nt-heatcell[data-level='3'] {
  background: color-mix(in srgb, var(--nd-danger) 16%, var(--nd-surface-1));
  color: var(--nd-danger);
}
.nt-heatcell[data-level='4'] {
  background: color-mix(in srgb, var(--nd-danger) 28%, var(--nd-surface-1));
  color: var(--nd-danger);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--nd-danger) 25%, transparent);
}

/* ── ** ── ** Wave 20aey — ** operator keycap ── ** ── */
.nt-kbd,
.nd-kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 1.4em;
  padding: 1px 6px;
  border-radius: 6px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 80%, transparent);
  background:
    linear-gradient(180deg,
      color-mix(in srgb, var(--nd-surface-2) 50%, transparent),
      color-mix(in srgb, var(--nd-surface-0) 70%, transparent));
  box-shadow:
    0 1px 0 color-mix(in srgb, black 18%, transparent),
    inset 0 1px 0 color-mix(in srgb, white 6%, transparent);
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 11px;
  font-weight: 700;
  color: var(--nd-text-secondary);
  line-height: 1.4;
}

/* ── ** ── ** Wave 20aez — ** surface nest elevation ── ** ── */
.nt-nest-0 { background: var(--nd-surface-0); }
.nt-nest-1 { background: var(--nd-surface-1); }
.nt-nest-2 { background: var(--nd-surface-2); }
.nt-nest-3 { background: var(--nd-surface-3, var(--nd-surface-2)); }
.nt-border-hair {
  border: 1px solid color-mix(in srgb, var(--nd-border) 75%, transparent);
}
.nt-radius-sm { border-radius: 8px; }
.nt-radius-md { border-radius: 12px; }
.nt-radius-lg { border-radius: 16px; }
.nt-radius-pill { border-radius: 999px; }

/* ── ** ── ** Wave 20afa — ** continuum 20afa seal ── ** ── */
.nt-wave-20afa {
  --nd-wave: '20afa';
}

/* ── ** ── ** Wave 20afb — ** quiet hover lift cards ── ** ── */
.nt-lift,
.nd-lift {
  transition: transform 140ms ease, box-shadow 140ms ease, border-color 140ms ease;
}
.nt-lift:hover,
.nd-lift:hover {
  transform: translateY(-2px);
  box-shadow: 0 14px 32px color-mix(in srgb, black 16%, transparent);
  border-color: color-mix(in srgb, var(--nd-accent) 22%, var(--nd-border));
}
@media (prefers-reduced-motion: reduce) {
  .nt-lift, .nd-lift, .nt-lift:hover, .nd-lift:hover {
    transition: none;
    transform: none;
  }
}

/* ── ** ── ** Wave 20afc — ** operator timeline rail ── ** ── */
.nt-ops-timeline {
  position: relative;
  padding-left: 18px;
}
.nt-ops-timeline::before {
  content: '';
  position: absolute;
  left: 5px;
  top: 4px;
  bottom: 4px;
  width: 2px;
  background: color-mix(in srgb, var(--nd-border) 80%, transparent);
  border-radius: 2px;
}
.nt-ops-timeline__item {
  position: relative;
  padding: 0 0 14px 8px;
}
.nt-ops-timeline__item::before {
  content: '';
  position: absolute;
  left: -15px;
  top: 6px;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--nd-surface-1);
  border: 2px solid color-mix(in srgb, var(--nd-accent) 55%, var(--nd-border));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--nd-surface-1) 90%, transparent);
}
.nt-ops-timeline__item[data-state='done']::before {
  background: var(--nd-success);
  border-color: var(--nd-success);
}
.nt-ops-timeline__item[data-state='alert']::before {
  background: var(--nd-danger);
  border-color: var(--nd-danger);
}

/* ── ** ── ** Wave 20afd — ** dual-tone metric delta ── ** ── */
.nt-delta {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  font-weight: 750;
  font-variant-numeric: tabular-nums;
  color: var(--nd-text-tertiary);
}
.nt-delta[data-tone='positive'] { color: var(--nd-success); }
.nt-delta[data-tone='negative'] { color: var(--nd-danger); }
.nt-delta[data-tone='neutral'] { color: var(--nd-text-tertiary); }
.nt-delta::before {
  content: '';
  width: 0;
  height: 0;
  border-left: 4px solid transparent;
  border-right: 4px solid transparent;
}
.nt-delta[data-tone='positive']::before {
  border-bottom: 6px solid currentColor;
}
.nt-delta[data-tone='negative']::before {
  border-top: 6px solid currentColor;
}

/* ── ** ── ** Wave 20afe — ** filter chip dismiss ── ** ── */
.nt-filter-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 8px 4px 10px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 28%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-accent) 10%, var(--nd-surface-1));
  color: var(--nd-text);
  font-size: 12px;
  font-weight: 650;
}
.nt-filter-chip__x {
  border: 0;
  background: transparent;
  color: var(--nd-text-tertiary);
  cursor: pointer;
  border-radius: 4px;
  line-height: 1;
  padding: 0 2px;
  font-size: 14px;
}
.nt-filter-chip__x:hover { color: var(--nd-text); }

/* ── ** ── ** Wave 20aff — ** panel empty mini ── ** ── */
.nt-empty-mini {
  padding: 18px 12px;
  text-align: center;
  font-size: 12px;
  color: var(--nd-text-tertiary);
  border-radius: 10px;
  border: 1px dashed color-mix(in srgb, var(--nd-border) 65%, transparent);
}

/* ── ** ── ** Wave 20afg — ** continuum 20afg ── ** ── */
.nt-wave-20afg {
  --nd-wave: '20afg';
}

/* ── ** ── ** Wave 20afh — ** glass contain isolation ── ** ── */
.nt-glass-contain {
  contain: layout paint style;
  isolation: isolate;
}
.nt-panel-glass.nt-glass-contain,
.nt-section-panel.nt-glass-contain {
  transform: translateZ(0);
}

/* ── ** ── ** Wave 20afi — ** progress indeterminate ── ** ── */
.nt-progress-indeterminate,
.nd-progress-indeterminate {
  position: relative;
  height: 3px;
  overflow: hidden;
  border-radius: 999px;
  background: color-mix(in srgb, var(--nd-surface-0) 70%, transparent);
}
.nt-progress-indeterminate::after,
.nd-progress-indeterminate::after {
  content: '';
  position: absolute;
  inset: 0 auto 0 0;
  width: 40%;
  border-radius: inherit;
  background: linear-gradient(90deg, transparent, var(--nd-accent), transparent);
  animation: nt-indet 1.2s ease-in-out infinite;
}
@keyframes nt-indet {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(350%); }
}
@media (prefers-reduced-motion: reduce) {
  .nt-progress-indeterminate::after,
  .nd-progress-indeterminate::after {
    animation: none;
    width: 100%;
    opacity: 0.45;
    transform: none;
  }
}

/* ── ** ── ** Wave 20afj — ** resizable handle row ── ** ── */
.nt-resize-row {
  display: flex;
  align-items: stretch;
  min-height: 0;
}
.nt-resize-row__pane {
  min-width: 0;
  min-height: 0;
  overflow: auto;
}
.nt-resize-row__handle {
  flex: 0 0 6px;
  cursor: col-resize;
  position: relative;
  background: transparent;
}
.nt-resize-row__handle::after {
  content: '';
  position: absolute;
  inset: 12% 2px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--nd-border) 70%, transparent);
}
.nt-resize-row__handle:hover::after,
.nt-resize-row__handle:focus-visible::after {
  background: color-mix(in srgb, var(--nd-accent) 55%, transparent);
  box-shadow: 0 0 12px color-mix(in srgb, var(--nd-accent) 28%, transparent);
}

/* ── ** ── ** Wave 20afk — ** tag cloud ── ** ── */
.nt-tag-cloud {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.nt-tag {
  display: inline-flex;
  align-items: center;
  padding: 3px 8px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  border: 1px solid color-mix(in srgb, var(--nd-border) 70%, transparent);
  background: color-mix(in srgb, var(--nd-surface-0) 55%, transparent);
  color: var(--nd-text-secondary);
}
.nt-tag[data-tone='accent'] {
  color: color-mix(in srgb, var(--nd-accent) 75%, var(--nd-text));
  border-color: color-mix(in srgb, var(--nd-accent) 30%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-accent) 10%, transparent);
}

