  box-shadow:
    0 12px 28px color-mix(in srgb, black 22%, transparent),
    inset 0 1px 0 color-mix(in srgb, white 6%, transparent);
}
html[data-nd-theme='light'] .nt-toast,
html[data-nd-theme='light'] .nd-toast {
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

/* ── ** ── ** Wave 20aha — ** continuum seal 20aha ── ** ── */
.nt-wave-20aha {
  --nd-wave: '20aha';
}

/* ── ** ── ** Wave 20ahb — ** lightbox / compare frames ── ** ── */
.nt-lightbox {
  border-radius: 16px;
  border: 1px solid var(--nd-border);
  background: color-mix(in srgb, var(--nd-surface-0) 92%, black 8%);
  box-shadow: 0 28px 64px color-mix(in srgb, black 36%, transparent);
  overflow: hidden;
}
.nt-compare {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}
@media (max-width: 800px) {
  .nt-compare { grid-template-columns: 1fr; }
}
.nt-compare__pane {
  border: 1px solid var(--nd-border);
  border-radius: 12px;
  background: color-mix(in srgb, var(--nd-surface-1) 94%, transparent);
  overflow: auto;
  min-height: 160px;
}
.nt-compare__pane-head {
  position: sticky;
  top: 0;
  z-index: 1;
  padding: 8px 12px;
  border-bottom: 1px solid var(--nd-border);
  background: color-mix(in srgb, var(--nd-surface-1) 88%, var(--nd-surface-0));
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--nd-text-secondary);
}

/* ── ** ── ** Wave 20ahc — ** handoff / pinboard ── ** ── */
.nt-handoff {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 12px 14px;
  border-radius: 14px;
  border: 1px dashed color-mix(in srgb, var(--nd-accent) 30%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-accent) 6%, var(--nd-surface-1));
}
.nt-pinboard {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 10px;
}
.nt-pinboard__card {
  padding: 12px;
  border-radius: 12px;
  border: 1px solid var(--nd-border);
  background: color-mix(in srgb, var(--nd-surface-2) 88%, var(--nd-surface-0));
  box-shadow: 0 8px 18px color-mix(in srgb, black 10%, transparent);
  min-height: 88px;
}

/* ── ** ── ** Wave 20ahd — ** SLA path ── ** ── */
.nt-sla-path {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
}
.nt-sla-path__node {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 10px;
  border-radius: 999px;
  border: 1px solid var(--nd-border);
  background: var(--nd-surface-2);
  font-size: 11px;
  font-weight: 700;
  color: var(--nd-text-secondary);
}
.nt-sla-path__node[data-state='breached'] {
  color: var(--nd-danger);
  border-color: color-mix(in srgb, var(--nd-danger) 40%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-danger) 10%, var(--nd-surface-2));
}
.nt-sla-path__node[data-state='ok'] {
  color: var(--nd-success);
  border-color: color-mix(in srgb, var(--nd-success) 35%, var(--nd-border));
}

/* ── ** ── ** Wave 20ahe — ** continuum seal 20ahe ── ** ── */
.nt-wave-20ahe {
  --nd-wave: '20ahe';
}

/* ── ** ── ** Wave 20ahf — ** bulk glass bar densify ── ** ── */
.nt-bulk-glass,
.nt-configure-bulk-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 10px;
  padding: 10px 12px;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 22%, var(--nd-border));
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--nd-accent) 10%, transparent),
      transparent 70%
    ),
    color-mix(in srgb, var(--nd-surface-1) 90%, var(--nd-surface-0));
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  box-shadow: 0 10px 24px color-mix(in srgb, black 12%, transparent);
}

/* ── ** ── ** Wave 20ahg — ** filter sticky seal ── ** ── */
.nt-filter-bar--sticky,
.nt-filters.nt-sticky {
  position: sticky;
  top: 0;
  z-index: var(--nd-z-sticky, 10);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

/* ── ** ── ** Wave 20ahh — ** ECG spark polish ── ** ── */
.nt-plane-ecg,
.nt-ecg {
  border-radius: 12px;
  border: 1px solid var(--nd-border);
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--nd-surface-2) 40%, transparent),
      transparent
    ),
    var(--nd-surface-1);
  padding: 8px 10px;
  overflow: hidden;
}
.nt-plane-ecg__trace,
.nt-ecg__trace {
  stroke: color-mix(in srgb, var(--nd-accent) 80%, white 10%);
  stroke-width: 1.5;
  fill: none;
  filter: drop-shadow(0 0 4px color-mix(in srgb, var(--nd-accent) 35%, transparent));
}

/* ── ** ── ** Wave 20ahi — ** KPI delta ladder ── ** ── */
.nt-kpi__delta[data-tone='positive'],
.nd-stat__delta[data-tone='positive'] {
  color: var(--nd-success);
}
.nt-kpi__delta[data-tone='negative'],
.nd-stat__delta[data-tone='negative'] {
  color: var(--nd-danger);
}
.nt-kpi__delta[data-tone='neutral'],
.nd-stat__delta[data-tone='neutral'] {
  color: var(--nd-text-tertiary);
}

/* ── ** ── ** Wave 20ahj — ** continuum seal 20ahj ── ** ── */
.nt-wave-20ahj {
  --nd-wave: '20ahj';
}

/* ── ** ── ** Wave 20ahk — ** secret field veil ── ** ── */
.nt-secret-field,
.nd-input[type='password'],
input.nd-input[type='password'] {
  font-family: var(--nd-font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  letter-spacing: 0.08em;
}
.nt-secret-veil {
  position: relative;
}
.nt-secret-veil::after {
  content: '';
  pointer-events: none;
  position: absolute;
  inset: 0;
  border-radius: inherit;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--nd-warning) 22%, transparent);
}

/* ── ** ── ** Wave 20ahl — ** coachmark copper ── ** ── */
.nt-coachmark {
  max-width: 280px;
  padding: 12px 14px;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 35%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-surface-1) 92%, var(--nd-accent) 6%);
  box-shadow: 0 16px 36px color-mix(in srgb, black 24%, transparent);
  font-size: 12px;
  color: var(--nd-text-secondary);
  line-height: 1.45;
}
.nt-coachmark__title {
  font-size: 12px;
  font-weight: 800;
  color: var(--nd-text);
  margin-bottom: 4px;
}

/* ── ** ── ** Wave 20ahm — ** war-room empty wake ── ** ── */
.nt-war-room,
.nt-empty--war-room {
  position: relative;
  overflow: hidden;
}
.nt-war-room::before,
.nt-empty--war-room::before {
  content: '';
  position: absolute;
  inset: -20% -10% auto;
  height: 55%;
  background:
    radial-gradient(
      ellipse at 30% 20%,
      color-mix(in srgb, var(--nd-accent) 18%, transparent),
      transparent 55%
    ),
    radial-gradient(
      ellipse at 80% 0%,
      color-mix(in srgb, var(--nd-danger) 10%, transparent),
      transparent 50%
    );
  pointer-events: none;
}

/* ── ** ── ** Wave 20ahn — ** brand mark ND pulse ── ** ── */
.nt-brand-mark {
  display: inline-grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: 8px;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.04em;
  color: var(--nd-accent-fg, var(--nd-surface-0));
  background: linear-gradient(
    145deg,
    color-mix(in srgb, var(--nd-accent) 92%, white 8%),
    color-mix(in srgb, var(--nd-accent) 70%, black 18%)
  );
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--nd-accent) 40%, transparent),
    0 8px 18px color-mix(in srgb, var(--nd-accent) 22%, transparent);
}

/* ── ** ── ** Wave 20aho — ** continuum seal 20aho ── ** ── */
.nt-wave-20aho {
  --nd-wave: '20aho';
}

/* ── ** ── ** Wave 20ahp — ** GreenLake write card phase ── ** ── */
.nt-card--write-ritual {
  position: relative;
  overflow: hidden;
  border-color: color-mix(in srgb, var(--nd-accent) 28%, var(--nd-border));
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, white 5%, transparent),
    0 14px 32px color-mix(in srgb, black 14%, transparent);
}
.nt-card--write-ritual[data-phase='executing'] {
  animation: nt-write-pulse 1.2s ease-in-out infinite;
}
.nt-card--write-ritual[data-phase='confirm'] {
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--nd-accent) 40%, transparent),
    0 0 0 5px color-mix(in srgb, var(--nd-accent) 10%, transparent),
    0 16px 36px color-mix(in srgb, black 16%, transparent);
}
@media (prefers-reduced-motion: reduce) {
  .nt-card--write-ritual[data-phase='executing'] { animation: none; }
}

/* ── ** ── ** Wave 20ahq — ** traceroute hop rail ── ** ── */
.nt-traceroute {
  display: flex;
  flex-direction: column;
  gap: 0;
  position: relative;
  padding-left: 14px;
}
.nt-traceroute::before {
  content: '';
  position: absolute;
  left: 5px;
  top: 8px;
  bottom: 8px;
  width: 2px;
  background: linear-gradient(
    180deg,
    color-mix(in srgb, var(--nd-accent) 50%, transparent),
    color-mix(in srgb, var(--nd-border) 80%, transparent)
  );
  border-radius: 2px;
}
.nt-traceroute__hop {
  position: relative;
  padding: 8px 10px 8px 16px;
  font-size: 12px;
  color: var(--nd-text-secondary);
}
.nt-traceroute__hop::before {
  content: '';
  position: absolute;
  left: -11px;
  top: 14px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--nd-accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--nd-accent) 18%, transparent);
}

/* ── ** ── ** Wave 20ahr — ** port matrix cell ── ** ── */
.nt-port-matrix {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(28px, 1fr));
  gap: 4px;
}
.nt-port-matrix__cell {
  aspect-ratio: 1;
  border-radius: 6px;
  border: 1px solid var(--nd-border);
  background: var(--nd-surface-2);
  font-size: 9px;
  font-weight: 700;
  display: grid;
  place-items: center;
  color: var(--nd-text-tertiary);
}
.nt-port-matrix__cell[data-state='up'] {
  background: color-mix(in srgb, var(--nd-success) 22%, var(--nd-surface-2));
  border-color: color-mix(in srgb, var(--nd-success) 40%, var(--nd-border));
  color: var(--nd-success);
}
.nt-port-matrix__cell[data-state='down'] {
  background: color-mix(in srgb, var(--nd-danger) 16%, var(--nd-surface-2));
  border-color: color-mix(in srgb, var(--nd-danger) 35%, var(--nd-border));
  color: var(--nd-danger);
}
.nt-port-matrix__cell[data-state='disabled'] {
  opacity: 0.45;
}

/* ── ** ── ** Wave 20ahs — ** vlan chip strip ── ** ── */
.nt-vlan-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.nt-vlan-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 8px;
  border-radius: 999px;
  border: 1px solid var(--nd-border);
  background: color-mix(in srgb, var(--nd-surface-2) 88%, transparent);
  font-size: 11px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--nd-text-secondary);
}
.nt-vlan-chip__id {
  color: var(--nd-accent);
  font-family: var(--nd-font-mono, ui-monospace, monospace);
}

/* ── ** ── ** Wave 20aht — ** continuum seal 20aht ── ** ── */
.nt-wave-20aht {
  --nd-wave: '20aht';
}

/* ── ** ── ** Wave 20ahu — ** firmware rail ── ** ── */
.nt-firmware-rail {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 10px;
  align-items: center;
  padding: 10px 12px;
  border-radius: 12px;
  border: 1px solid var(--nd-border);
  background: color-mix(in srgb, var(--nd-surface-1) 94%, transparent);
}
.nt-firmware-rail__ver {
  font-family: var(--nd-font-mono, ui-monospace, monospace);
  font-size: 12px;
  font-weight: 700;
  color: var(--nd-text);
}
.nt-firmware-rail__bar {
  height: 6px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--nd-surface-3) 80%, transparent);
  overflow: hidden;
}
.nt-firmware-rail__bar > i {
  display: block;
  height: 100%;
  width: var(--nd-fw-pct, 0%);
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--nd-accent) 70%, transparent),
    var(--nd-accent)
  );
  border-radius: inherit;
}

/* ── ** ── ** Wave 20ahv — ** correlation cluster ── ** ── */
.nt-correlation {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.nt-correlation__edge {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  gap: 8px;
  align-items: center;
  font-size: 12px;
  color: var(--nd-text-secondary);
}
.nt-correlation__link {
  height: 2px;
  border-radius: 2px;
  background: linear-gradient(
    90deg,
    transparent,
    color-mix(in srgb, var(--nd-accent) 55%, transparent),
    transparent
  );
}

/* ── ** ── ** Wave 20ahw — ** blast radius ring ── ** ── */
.nt-blast {
  display: grid;
  place-items: center;
  aspect-ratio: 1;
  max-width: 220px;
  margin-inline: auto;
  border-radius: 50%;
  border: 1px solid color-mix(in srgb, var(--nd-danger) 35%, var(--nd-border));
  background:
    radial-gradient(
      circle at 50% 50%,
      color-mix(in srgb, var(--nd-danger) 16%, transparent) 0%,
      color-mix(in srgb, var(--nd-warning) 10%, transparent) 42%,
      transparent 68%
    ),
    var(--nd-surface-1);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, white 4%, transparent);
}
.nt-blast__core {
  text-align: center;
  padding: 12px;
}
.nt-blast__n {
  font-size: 28px;
  font-weight: 900;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.03em;
  color: var(--nd-text);
}
.nt-blast__label {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--nd-text-tertiary);
}

/* ── ** ── ** Wave 20ahx — ** runbook steps ── ** ── */
.nt-runbook {
  display: flex;
  flex-direction: column;
  gap: 0;
  counter-reset: nd-run;
}
.nt-runbook__step {
  display: grid;
  grid-template-columns: 28px 1fr;
  gap: 10px;
  padding: 10px 0;
  border-bottom: 1px solid color-mix(in srgb, var(--nd-border) 80%, transparent);
  counter-increment: nd-run;
}
.nt-runbook__step:last-child { border-bottom: 0; }
.nt-runbook__n {
  width: 28px;
  height: 28px;
  border-radius: 8px;
  display: grid;
  place-items: center;
  font-size: 11px;
  font-weight: 900;
  color: var(--nd-accent-fg, var(--nd-surface-0));
  background: color-mix(in srgb, var(--nd-accent) 85%, black 10%);
}
.nt-runbook__n::before { content: counter(nd-run); }
.nt-runbook__body {
  font-size: 13px;
  color: var(--nd-text-secondary);
  line-height: 1.45;
}

/* ── ** ── ** Wave 20ahy — ** continuum seal 20ahy ── ** ── */
.nt-wave-20ahy {
  --nd-wave: '20ahy';
}

/* ── ** ── ** Wave 20ahz — ** SLO ring ── ** ── */
.nt-slo {
  display: inline-grid;
  grid-template-columns: auto 1fr;
  gap: 10px;
  align-items: center;
  padding: 10px 12px;
  border-radius: 12px;
  border: 1px solid var(--nd-border);
  background: color-mix(in srgb, var(--nd-surface-1) 94%, transparent);
  min-width: 160px;
}
.nt-slo__ring {
  --nd-slo: 0.98;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background:
    conic-gradient(
      var(--nd-success) calc(var(--nd-slo) * 1turn),
      color-mix(in srgb, var(--nd-surface-3) 80%, transparent) 0
    );
  mask: radial-gradient(circle at center, transparent 56%, black 58%);
  -webkit-mask: radial-gradient(circle at center, transparent 56%, black 58%);
}
.nt-slo__meta {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.nt-slo__label {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--nd-text-tertiary);
}
.nt-slo__value {
  font-size: 16px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  color: var(--nd-text);
}

/* ── ** ── ** Wave 20aia — ** on-call badge ── ** ── */
.nt-oncall {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 28%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-accent) 10%, var(--nd-surface-2));
  font-size: 12px;
  font-weight: 700;
  color: var(--nd-text);
}
.nt-oncall__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--nd-success);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--nd-success) 22%, transparent);
}
.nt-oncall[data-state='paging'] .nt-oncall__dot {
  background: var(--nd-danger);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--nd-danger) 25%, transparent);
}

/* ── ** ── ** Wave 20aib — ** latency bars ── ** ── */
.nt-latency {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.nt-latency__row {
  display: grid;
  grid-template-columns: 72px 1fr 48px;
  gap: 8px;
  align-items: center;
  font-size: 11px;
  color: var(--nd-text-secondary);
}
.nt-latency__bar {
  height: 6px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--nd-surface-3) 85%, transparent);
  overflow: hidden;
}
.nt-latency__bar > i {
  display: block;
  height: 100%;
  width: var(--nd-lat, 0%);
  border-radius: inherit;
  background: color-mix(in srgb, var(--nd-accent) 80%, white 5%);
}
.nt-latency__row[data-tone='warn'] .nt-latency__bar > i {
  background: var(--nd-warning);
}
.nt-latency__row[data-tone='danger'] .nt-latency__bar > i {
  background: var(--nd-danger);
}
.nt-latency__ms {
  font-variant-numeric: tabular-nums;
  font-weight: 700;
  text-align: right;
  color: var(--nd-text);
}

/* ── ** ── ** Wave 20aic — ** capacity channel bars ── ** ── */
.nt-capacity {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.nt-capacity__row {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 8px;
  align-items: center;
  font-size: 11px;
}
.nt-capacity__track {
  grid-column: 1 / -1;
  height: 8px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--nd-surface-3) 80%, transparent);
  overflow: hidden;
}
.nt-capacity__track > i {
  display: block;
  height: 100%;
  width: var(--nd-cap, 0%);
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--nd-accent) 55%, transparent),
    var(--nd-accent)
  );
}
.nt-capacity__row[data-tone='hot'] .nt-capacity__track > i {
  background: linear-gradient(90deg, var(--nd-warning), var(--nd-danger));
}

/* ── ** ── ** Wave 20aid — ** continuum seal 20aid ── ** ── */
.nt-wave-20aid {
  --nd-wave: '20aid';
}

/* ── ** ── ** Wave 20aie — ** client write toolbar phase ── ** ── */
.nt-client-toolbar.nt-write-ritual {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 12px;
  padding: 12px 14px;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 28%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-surface-1) 92%, var(--nd-accent) 5%);
  position: relative;
  overflow: hidden;
}
.nt-client-toolbar.nt-write-ritual[data-phase='confirm'] {
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--nd-accent) 35%, transparent),
    0 0 0 5px color-mix(in srgb, var(--nd-accent) 10%, transparent);
}
.nt-client-toolbar.nt-write-ritual[data-phase='executing'] {
  animation: nt-write-pulse 1.2s ease-in-out infinite;
}
@media (prefers-reduced-motion: reduce) {
  .nt-client-toolbar.nt-write-ritual[data-phase='executing'] { animation: none; }
}

/* ── ** ── ** Wave 20aif — ** identity chip / workspace ── ** ── */
.nt-identity {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  max-width: 220px;
}
.nt-identity__avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 10px;
  font-weight: 900;
  color: var(--nd-text);
  background: color-mix(in srgb, var(--nd-surface-3) 80%, var(--nd-accent) 12%);
  border: 1px solid var(--nd-border);
  flex: 0 0 auto;
}
.nt-identity__name {
  font-size: 12px;
  font-weight: 700;
  color: var(--nd-text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.nt-identity__meta {
  font-size: 10px;
  color: var(--nd-text-tertiary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ── ** ── ** Wave 20aig — ** notify popover densify ── ** ── */
.nt-notify-popover {
  width: min(360px, 92vw);
  border-radius: 14px;
  border: 1px solid var(--nd-border);
  background: color-mix(in srgb, var(--nd-surface-1) 94%, var(--nd-surface-0));
  box-shadow: 0 20px 48px color-mix(in srgb, black 28%, transparent);
  overflow: hidden;
}
.nt-notify-popover__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 10px 12px;
  border-bottom: 1px solid var(--nd-border);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--nd-text-secondary);
}
.nt-notify-popover__item {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 10px;
  padding: 10px 12px;
  border-bottom: 1px solid color-mix(in srgb, var(--nd-border) 75%, transparent);
  font-size: 12px;
  color: var(--nd-text-secondary);
}
.nt-notify-popover__item:last-child { border-bottom: 0; }
.nt-notify-popover__item[data-unread='true'] {
  background: color-mix(in srgb, var(--nd-accent) 8%, transparent);
}

/* ── ** ── ** Wave 20aih — ** continuum seal 20aih ── ** ── */
.nt-wave-20aih {
  --nd-wave: '20aih';
}

/* ── ** ── ** Wave 20aii — ** floorplan marker ── ** ── */
.nt-floorplan {
  position: relative;
  border-radius: 16px;
  border: 1px solid var(--nd-border);
  background:
    linear-gradient(
      135deg,
      color-mix(in srgb, var(--nd-surface-2) 40%, transparent) 25%,
      transparent 25%
    ) 0 0 / 24px 24px,
    var(--nd-surface-1);
  min-height: 240px;
  overflow: hidden;
}
.nt-floorplan__marker {
  position: absolute;
  transform: translate(-50%, -50%);
  width: 14px;
  height: 14px;
  border-radius: 50%;
  border: 2px solid color-mix(in srgb, white 55%, transparent);
  background: var(--nd-accent);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--nd-accent) 22%, transparent);
  cursor: pointer;
}
.nt-floorplan__marker[data-tone='danger'] {
  background: var(--nd-danger);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--nd-danger) 25%, transparent);
}
.nt-floorplan__marker[data-tone='warning'] {
  background: var(--nd-warning);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--nd-warning) 25%, transparent);
}
.nt-floorplan__marker:focus-visible {
  outline: none;
  box-shadow:
    0 0 0 4px color-mix(in srgb, var(--nd-accent) 22%, transparent),
    0 0 0 2px var(--nd-focus-ring);
}

/* ── ** ── ** Wave 20aij — ** compliance score band ── ** ── */
.nt-compliance-band {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 8px 12px;
  padding: 12px 14px;
  border-radius: 14px;
  border: 1px solid var(--nd-border);
  background: color-mix(in srgb, var(--nd-surface-1) 94%, transparent);
}
.nt-compliance-band__score {
  font-size: 28px;
  font-weight: 900;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.03em;
  color: var(--nd-text);
}
.nt-compliance-band__bar {
  grid-column: 1 / -1;
  height: 8px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--nd-surface-3) 85%, transparent);
  overflow: hidden;
}
.nt-compliance-band__bar > i {
  display: block;
  height: 100%;
  width: var(--nd-comp, 0%);
  border-radius: inherit;
  background: linear-gradient(90deg, var(--nd-warning), var(--nd-success));
}

/* ── ** ── ** Wave 20aik — ** license expiry heat ── ** ── */
.nt-license-row[data-expiry='soon'] {
  background: color-mix(in srgb, var(--nd-warning) 9%, transparent);
}
.nt-license-row[data-expiry='expired'] {
  background: color-mix(in srgb, var(--nd-danger) 10%, transparent);
}
.nt-license-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  border: 1px solid var(--nd-border);
  color: var(--nd-text-secondary);
  background: var(--nd-surface-2);
}
.nt-license-chip[data-expiry='soon'] {
  color: var(--nd-warning);
  border-color: color-mix(in srgb, var(--nd-warning) 40%, var(--nd-border));
}
.nt-license-chip[data-expiry='expired'] {
  color: var(--nd-danger);
  border-color: color-mix(in srgb, var(--nd-danger) 40%, var(--nd-border));
}

/* ── ** ── ** Wave 20ail — ** auth gate glass ── ** ── */
.nt-auth-gate {
  max-width: 420px;
  margin: 8vh auto;
  padding: 28px 28px 24px;
  border-radius: 18px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 22%, var(--nd-border));
  background:
    linear-gradient(
      165deg,
      color-mix(in srgb, var(--nd-accent) 10%, transparent),
      transparent 42%
    ),
    color-mix(in srgb, var(--nd-surface-1) 94%, var(--nd-surface-0));
  box-shadow:
    0 28px 64px color-mix(in srgb, black 30%, transparent),
    inset 0 1px 0 color-mix(in srgb, white 6%, transparent);
}
.nt-auth-gate__brand {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 18px;
  font-size: 14px;
  font-weight: 800;
  letter-spacing: 0.04em;
  color: var(--nd-text);
}

/* ── ** ── ** Wave 20aim — ** continuum seal 20aim ── ** ── */
.nt-wave-20aim {
  --nd-wave: '20aim';
}

/* ── ** ── ** Wave 20ain — ** calendar day cells ── ** ── */
.nt-cal {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 4px;
}
.nt-cal__dow {
  text-align: center;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--nd-text-tertiary);
  padding: 4px 0;
}
.nt-cal__day {
  aspect-ratio: 1.15;
  border-radius: 10px;
  border: 1px solid color-mix(in srgb, var(--nd-border) 80%, transparent);
  background: color-mix(in srgb, var(--nd-surface-2) 70%, transparent);
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: flex-start;
  padding: 6px;
  font-size: 11px;
  font-weight: 700;
  color: var(--nd-text-secondary);
  cursor: pointer;
}
.nt-cal__day[data-today='true'] {
  border-color: color-mix(in srgb, var(--nd-accent) 45%, var(--nd-border));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--nd-accent) 25%, transparent);
}
.nt-cal__day[data-selected='true'] {
  background: color-mix(in srgb, var(--nd-accent) 18%, var(--nd-surface-2));
  color: var(--nd-text);
}
.nt-cal__day:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--nd-focus-ring);
}

/* ── ** ── ** Wave 20aio — ** JSON / diff panes ── ** ── */
.nt-json,
.nt-diff {
  font-family: var(--nd-font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: 12px;
  line-height: 1.5;
  border-radius: 12px;
  border: 1px solid var(--nd-border);
  background: color-mix(in srgb, var(--nd-surface-0) 88%, var(--nd-surface-1));
  padding: 12px 14px;
  overflow: auto;
  max-height: min(60vh, 520px);
  color: var(--nd-text-secondary);
}
.nt-diff__add {
  background: color-mix(in srgb, var(--nd-success) 12%, transparent);
  color: color-mix(in srgb, var(--nd-success) 70%, var(--nd-text));
}
.nt-diff__del {
  background: color-mix(in srgb, var(--nd-danger) 12%, transparent);
  color: color-mix(in srgb, var(--nd-danger) 70%, var(--nd-text));
}

/* ── ** ── ** Wave 20aip — ** composer dock ── ** ── */
.nt-composer {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 10px;
  align-items: end;
  padding: 12px;
  border-radius: 16px;
  border: 1px solid var(--nd-border);
  background: color-mix(in srgb, var(--nd-surface-1) 94%, var(--nd-surface-0));
  box-shadow:
    0 -8px 28px color-mix(in srgb, black 12%, transparent),
    inset 0 1px 0 color-mix(in srgb, white 5%, transparent);
}
.nt-composer__input {
  min-height: 44px;
}
.nt-composer__actions {
  display: flex;
  gap: 8px;
  align-items: center;
}

/* ── ** ── ** Wave 20aiq — ** scope pin bar ── ** ── */
.nt-scope-pin {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 8px;
  padding: 8px 10px;
  border-radius: 12px;
  border: 1px dashed color-mix(in srgb, var(--nd-accent) 30%, var(--nd-border));
  background: color-mix(in srgb, var(--nd-accent) 6%, var(--nd-surface-1));
  font-size: 12px;
  color: var(--nd-text-secondary);
}
.nt-scope-pin__chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 2px 8px;
  border-radius: 999px;
  border: 1px solid var(--nd-border);
  background: var(--nd-surface-2);
  font-size: 11px;
  font-weight: 700;
  color: var(--nd-text);
}

/* ── ** ── ** Wave 20air — ** continuum seal 20air ── ** ── */
.nt-wave-20air {
  --nd-wave: '20air';
}

/* ── ** ── ** Wave 20ais — ** mobile nav sheet ── ** ── */
.nt-mobile-nav {
  position: fixed;
  inset: 0;
  z-index: var(--nd-z-overlay, 40);
  display: grid;
  grid-template-rows: auto 1fr;
  background: color-mix(in srgb, var(--nd-surface-0) 92%, transparent);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
}
.nt-mobile-nav__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 16px;
  border-bottom: 1px solid var(--nd-border);
}
.nt-mobile-nav__list {
  overflow: auto;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

/* ── ** ── ** Wave 20ait — ** skip link copper ── ** ── */
.nt-skip-link {
  position: absolute;
  left: 12px;
  top: 8px;
  z-index: calc(var(--nd-z-overlay, 40) + 1);
  padding: 8px 12px;
  border-radius: 10px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 40%, var(--nd-border));
  background: var(--nd-surface-1);
  color: var(--nd-text);
  font-size: 12px;
  font-weight: 800;
  transform: translateY(-200%);
  transition: transform 120ms ease;
}
.nt-skip-link:focus {
  transform: translateY(0);
  outline: none;
  box-shadow: 0 0 0 2px var(--nd-focus-ring);
}

/* ── ** ── ** Wave 20aiu — ** ticket queue row ── ** ── */
.nt-tickets__row {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 10px;
  align-items: start;
  padding: 10px 12px;
  border-bottom: 1px solid color-mix(in srgb, var(--nd-border) 80%, transparent);
  cursor: pointer;
}
.nt-tickets__row:hover {
  background: color-mix(in srgb, var(--nd-accent) 7%, transparent);
}
.nt-tickets__row[data-active='true'] {
  background: color-mix(in srgb, var(--nd-accent) 12%, transparent);
  box-shadow: inset 3px 0 0 var(--nd-accent);
}
.nt-tickets__row:focus-visible {
  outline: none;
  box-shadow: inset 0 0 0 2px var(--nd-focus-ring);
}

/* ── ** ── ** Wave 20aiv — ** section recon reveal ── ** ── */
.nt-recon-reveal {
  animation: nt-recon-in 280ms ease both;
}
@keyframes nt-recon-in {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@media (prefers-reduced-motion: reduce) {
  .nt-recon-reveal { animation: none; }
}

/* ── ** ── ** Wave 20aiw — ** continuum seal 20aiw ── ** ── */
.nt-wave-20aiw {
  --nd-wave: '20aiw';
}

/* ── ** ── ** Wave 20aix — ** chat write mode seal ── ** ── */
.nt-chat-drawer.nt-write-ritual,
.nd-drawer--write-ritual.nt-chat {
  border-color: color-mix(in srgb, var(--nd-accent) 30%, var(--nd-border));
}
.nt-chat-msg {
  display: grid;
  gap: 6px;
  padding: 10px 12px;
  border-radius: 12px;
  max-width: min(640px, 100%);
  font-size: 13px;
  line-height: 1.45;
}
.nt-chat-msg--user {
  margin-left: auto;
  background: color-mix(in srgb, var(--nd-accent) 16%, var(--nd-surface-2));
  border: 1px solid color-mix(in srgb, var(--nd-accent) 25%, var(--nd-border));
  color: var(--nd-text);
}
.nt-chat-msg--assistant {
  margin-right: auto;
  background: color-mix(in srgb, var(--nd-surface-2) 88%, transparent);
  border: 1px solid var(--nd-border);
  color: var(--nd-text-secondary);
}
.nt-chat-msg--system {
  margin-inline: auto;
  text-align: center;
  font-size: 11px;
  color: var(--nd-text-tertiary);
  background: transparent;
  border: 0;
}

/* ── ** ── ** Wave 20aiy — ** estate strip LEDs ── ** ── */
.nt-estate-strip {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 12px;
  padding: 8px 12px;
  border-radius: 12px;
  border: 1px solid var(--nd-border);
  background: color-mix(in srgb, var(--nd-surface-1) 92%, transparent);
}
.nt-estate-strip__led {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--nd-text-tertiary);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--nd-text-tertiary) 15%, transparent);
}
.nt-estate-strip__led[data-state='ok'] {
  background: var(--nd-success);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--nd-success) 20%, transparent);
}
.nt-estate-strip__led[data-state='degraded'] {
  background: var(--nd-warning);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--nd-warning) 22%, transparent);
}
.nt-estate-strip__led[data-state='down'] {
  background: var(--nd-danger);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--nd-danger) 22%, transparent);
}

/* ── ** ── ** Wave 20aiz — ** heatcell matrix ── ** ── */
.nt-heatcell {
  display: grid;
  place-items: center;
  min-height: 28px;
  border-radius: 6px;
  font-size: 10px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  color: var(--nd-text-secondary);
  background: color-mix(in srgb, var(--nd-surface-2) 90%, transparent);
  border: 1px solid color-mix(in srgb, var(--nd-border) 80%, transparent);
}
.nt-heatcell[data-heat='1'] { background: color-mix(in srgb, var(--nd-accent) 10%, var(--nd-surface-2)); }
.nt-heatcell[data-heat='2'] { background: color-mix(in srgb, var(--nd-accent) 18%, var(--nd-surface-2)); }
.nt-heatcell[data-heat='3'] { background: color-mix(in srgb, var(--nd-warning) 22%, var(--nd-surface-2)); color: var(--nd-text); }
.nt-heatcell[data-heat='4'] { background: color-mix(in srgb, var(--nd-danger) 28%, var(--nd-surface-2)); color: var(--nd-text); }

/* ── ** ── ** Wave 20aja — ** continuum seal 20aja ── ** ── */
.nt-wave-20aja {
  --nd-wave: '20aja';
}

/* ── ** ── ** Wave 20ajb — ** platforms collapse densify ── ** ── */
.nt-platforms {
  margin-top: 6px;
  border-top: 1px solid color-mix(in srgb, var(--nd-border) 80%, transparent);
  padding-top: 8px;
}
.nt-platforms__toggle {
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 8px 10px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: var(--nd-text-secondary);
  font: inherit;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  cursor: pointer;
}
.nt-platforms__toggle:hover {
  background: color-mix(in srgb, var(--nd-surface-2) 70%, transparent);
  color: var(--nd-text);
}
.nt-platforms__toggle:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--nd-focus-ring);
}
.nt-platforms__body {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 4px 0 8px;
}
.nt-platforms[data-open='false'] .nt-platforms__body {
  display: none;
}

/* ── ** ── ** Wave 20ajc — ** nav item active copper rail ── ** ── */
.nt-navitem,
.nd-nav-item {
  position: relative;
}
.nt-navitem[aria-current='page'],
.nt-navitem[data-active='true'],
.nd-nav-item[aria-current='page'],
.nd-nav-item[data-active='true'] {
  background: color-mix(in srgb, var(--nd-accent) 12%, var(--nd-surface-2));
  color: var(--nd-text);
  box-shadow: inset 3px 0 0 var(--nd-accent);
}

/* ── ** ── ** Wave 20ajd — ** topbar glass densify ── ** ── */
.nt-topbar,
.nd-topbar {
  backdrop-filter: blur(14px) saturate(1.15);
  -webkit-backdrop-filter: blur(14px) saturate(1.15);
  border-bottom-color: color-mix(in srgb, var(--nd-border) 88%, transparent);
  box-shadow: 0 10px 28px color-mix(in srgb, black 10%, transparent);
}
html[data-nd-theme='light'] .nt-topbar,
html[data-nd-theme='light'] .nd-topbar {
  backdrop-filter: blur(12px) saturate(1.05);
  -webkit-backdrop-filter: blur(12px) saturate(1.05);
}

/* ── ** ── ** Wave 20aje — ** fab copper ── ** ── */
.nt-fab {
  position: fixed;
  right: max(16px, env(safe-area-inset-right));
  bottom: max(16px, env(safe-area-inset-bottom));
  z-index: var(--nd-z-toast, 50);
  width: 48px;
  height: 48px;
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--nd-accent) 40%, transparent);
  background: linear-gradient(
    145deg,
    color-mix(in srgb, var(--nd-accent) 92%, white 8%),
    color-mix(in srgb, var(--nd-accent) 72%, black 16%)
  );
  color: var(--nd-accent-fg, var(--nd-surface-0));
  box-shadow:
    0 14px 32px color-mix(in srgb, var(--nd-accent) 28%, transparent),
    inset 0 1px 0 color-mix(in srgb, white 25%, transparent);
  display: grid;
  place-items: center;
  cursor: pointer;
}
.nt-fab:focus-visible {
  outline: none;
  box-shadow:
    0 0 0 2px var(--nd-focus-ring),
    0 14px 32px color-mix(in srgb, var(--nd-accent) 28%, transparent);
}

/* ── ** ── ** Wave 20ajf — ** continuum seal 20ajf ── ** ── */
.nt-wave-20ajf {
  --nd-wave: '20ajf';
}

/* ── ** ── ** Wave 20ajg — ** kbd chip densify ── ** ── */
.nt-kbd,
.nd-kbd,
kbd.nt-kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 1.4em;
  padding: 2px 6px;
  border-radius: 6px;
  border: 1px solid var(--nd-border);
  background: color-mix(in srgb, var(--nd-surface-2) 88%, var(--nd-surface-0));
  box-shadow: 0 1px 0 color-mix(in srgb, black 18%, transparent);
  font-family: var(--nd-font-mono, ui-monospace, monospace);
  font-size: 10px;
  font-weight: 700;
  line-height: 1.2;
  color: var(--nd-text-secondary);
}

/* ── ** ── ** Wave 20ajh — ** copper rule utility ── ** ── */
.nt-copper-rule {
  height: 1px;
  border: 0;
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--nd-accent) 55%, transparent),
    color-mix(in srgb, var(--nd-border) 80%, transparent) 48%,
    transparent
  );
}

/* ── ** ── ** Wave 20aji — ** elev ladder utilities ── ** ── */
.nt-elev-0 { box-shadow: none; }
.nt-elev-1 {
  box-shadow:
    0 1px 0 color-mix(in srgb, white 4%, transparent),
    0 6px 14px color-mix(in srgb, black 10%, transparent);
}
.nt-elev-2 {
  box-shadow:
    0 1px 0 color-mix(in srgb, white 5%, transparent),
    0 12px 28px color-mix(in srgb, black 16%, transparent);
}
.nt-elev-3 {
  box-shadow:
    0 1px 0 color-mix(in srgb, white 6%, transparent),
    0 20px 48px color-mix(in srgb, black 24%, transparent);
}
