}

/* ── ** ── ** Wave 20ajr — ** continuum seal 20ajr ── ** ── */
.nt-wave-20ajr {
  --nd-wave: '20ajr';
}

/* ── ** ── ** Wave 20ajs — ** maintenance window chip ── ** ── */
.nt-maint-chip {
