}
.nt-channel-bars__bar {
  height: var(--nd-ch, 20%);
  border-radius: 3px 3px 1px 1px;
  background: color-mix(in srgb, var(--nd-accent) 55%, var(--nd-surface-3));
  min-height: 4px;
}
.nt-channel-bars__bar[data-tone='hot'] {
  background: linear-gradient(180deg, var(--nd-danger), var(--nd-warning));
}

/* ── ** ── ** Wave 20ajv — ** continuum seal 20ajv ── ** ── */
.nt-wave-20ajv {
  --nd-wave: '20ajv';
}

/* ── ** ── ** Wave 20ajw — ** overview KPI mosaic ── ** ── */
.nt-kpi-mosaic {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 10px;
}
.nt-kpi-mosaic__tile {
  padding: 14px 14px 12px;
  border-radius: 14px;
  border: 1px solid var(--nd-border);
  background:
    linear-gradient(
      160deg,
      color-mix(in srgb, var(--nd-accent) 8%, transparent),
