}
.nt-kpi-mosaic__label {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--nd-text-tertiary);
}
.nt-kpi-mosaic__value {
  margin-top: 6px;
  font-size: 26px;
  font-weight: 900;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.03em;
