  background: color-mix(in srgb, var(--nd-warning) 12%, var(--nd-surface-2));
}
.nt-sev[data-sev='P3'],
.nt-sev--p3 {
  color: var(--nd-text);
  border-color: color-mix(in srgb, var(--nd-accent) 30%, var(--nd-border));
