}

/* ── ** ── ** Wave 20akl — ** continuum seal 20akl ── ** ── */
.nt-wave-20akl {
  --nd-wave: '20akl';
}

/* ── ** ── ** Wave 20akm — ** scrollbar copper ── ** ── */
.nt-table-scroll,
.nd-table-scroll,
.nt-drawer__body,
