.nd-table-scroll::-webkit-scrollbar-thumb,
.nt-drawer__body::-webkit-scrollbar-thumb,
.nd-drawer__body::-webkit-scrollbar-thumb {
  background: color-mix(in srgb, var(--nd-accent) 32%, var(--nd-border));
