  border: 2px solid transparent;
  background-clip: padding-box;
}
.nt-table-scroll::-webkit-scrollbar-thumb:hover,
.nd-table-scroll::-webkit-scrollbar-thumb:hover,
.nt-drawer__body::-webkit-scrollbar-thumb:hover,
.nd-drawer__body::-webkit-scrollbar-thumb:hover {
