    color: black !important;
  }
}

/* ── ** ── ** Wave 20ako — ** forced colors seal ── ** ── */
@media (forced-colors: active) {
  .nt-brand-mark,
  .nt-fab,
  .nt-sev,
  .nt-pill,
  .nt-plane-chip,
  .nd-badge {
    forced-color-adjust: none;
    border: 1px solid ButtonText;
  }
  .nt-navitem[aria-current='page'],
  .nd-nav-item[aria-current='page'] {
    outline: 2px solid Highlight;
  }
}

/* ── ** ── ** Wave 20akp — ** continuum seal 20akp ── ** ── */
.nt-wave-20akp {
  --nd-wave: '20akp';
}

/* ── ** ── ** Wave 20akq — ** reduced transparency seal ── ** ── */
@media (prefers-reduced-transparency: reduce) {
  .nt-topbar,
  .nd-topbar,
  .nt-glass,
  .nt-panel-glass,
  .nt-bulk-glass,
