/* ── WAVE 20BCB · utility ladder · a11y · print · forced-colors ────────── */

.nt-sr-only,
.nd-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
