}

.nt-scroll-thin::-webkit-scrollbar { width: 8px; height: 8px; }
.nt-scroll-thin::-webkit-scrollbar-thumb {
  background: color-mix(in srgb, var(--nd-border) 70%, var(--nd-accent) 30%);
  border-radius: 999px;
}

::selection {
  background: color-mix(in srgb, var(--nd-accent) 35%, transparent);
  color: var(--nd-text);
}

@media (forced-colors: active) {
