}

.nt-stack-1 { display: flex; flex-direction: column; gap: var(--nd-space-1, 0.25rem); }
.nt-stack-2 { display: flex; flex-direction: column; gap: var(--nd-space-2, 0.5rem); }
.nt-stack-3 { display: flex; flex-direction: column; gap: var(--nd-space-3, 0.75rem); }
