.nt-row-1 { display: flex; flex-wrap: wrap; align-items: center; gap: var(--nd-space-1, 0.25rem); }
.nt-row-2 { display: flex; flex-wrap: wrap; align-items: center; gap: var(--nd-space-2, 0.5rem); }
.nt-row-3 { display: flex; flex-wrap: wrap; align-items: center; gap: var(--nd-space-3, 0.75rem); }

/* end wave 20bbx–20bcb */

/* ── WAVE 20BCC · dual-class badge/card/tabs · empty wake mark ─────────── */

