.nt-badge--warning,
.nd-badge--warning { color: var(--nd-warning, var(--nd-accent)); border-color: color-mix(in srgb, var(--nd-warning, var(--nd-accent)) 35%, var(--nd-border)); background: color-mix(in srgb, var(--nd-surface-1) 82%, var(--nd-warning, var(--nd-accent)) 18%); }
.nt-badge--danger,
.nd-badge--danger { color: var(--nd-danger, var(--nd-accent)); border-color: color-mix(in srgb, var(--nd-danger, var(--nd-accent)) 35%, var(--nd-border)); background: color-mix(in srgb, var(--nd-surface-1) 82%, var(--nd-danger, var(--nd-accent)) 18%); }
.nt-badge--accent,
.nd-badge--accent { color: var(--nd-accent); border-color: color-mix(in srgb, var(--nd-accent) 35%, var(--nd-border)); background: color-mix(in srgb, var(--nd-surface-1) 82%, var(--nd-accent) 18%); }
