  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--nd-text-tertiary) 78%, var(--nd-accent) 22%);
}

.nt-screen-header__overline,
.nd-screen-header__overline {
  margin: 0;
  font-size: var(--nd-text-xs, 0.75rem);
