    linear-gradient(105deg, color-mix(in srgb, var(--nd-surface-1) 92%, var(--nd-accent) 8%), var(--nd-surface-1));
}

.nt-change-strip--hot,
.nd-change-strip--hot,
.nt-change-strip[data-hot='1'] {
  border-color: color-mix(in srgb, var(--nd-danger, var(--nd-accent)) 40%, var(--nd-border));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--nd-danger, var(--nd-accent)) 12%, transparent);
}

.nt-change-strip__kicker,
.nd-change-strip__kicker {
  margin-right: 0.25rem;
}

.nt-change-strip__chip,
.nd-change-strip__chip {
  appearance: none;
  border: 1px solid var(--nd-border);
  background: var(--nd-surface-2);
  color: var(--nd-text);
  border-radius: 999px;
  padding: 0.28rem 0.65rem;
  font: inherit;
  font-size: var(--nd-text-xs, 0.75rem);
  font-weight: 650;
  cursor: pointer;
}

.nt-change-strip__chip--positive,
.nd-change-strip__chip--positive {
  border-color: color-mix(in srgb, var(--nd-success, var(--nd-accent)) 40%, var(--nd-border));
  color: var(--nd-success, var(--nd-accent));
}

.nt-change-strip__chip--negative,
.nd-change-strip__chip--negative {
  border-color: color-mix(in srgb, var(--nd-danger, var(--nd-accent)) 40%, var(--nd-border));
  color: var(--nd-danger, var(--nd-accent));
  background: color-mix(in srgb, var(--nd-surface-1) 82%, var(--nd-danger, var(--nd-accent)) 18%);
}

.nt-change-strip__chip--neutral,
.nd-change-strip__chip--neutral {
  color: var(--nd-text-secondary, var(--nd-text-tertiary));
}

.nt-change-strip__note,
.nd-change-strip__note {
  margin-left: auto;
  font-size: var(--nd-text-2xs, 0.625rem);
}

/* ── WAVE 20BCU · API fault panel · section panel glass ────────────────── */

.nt-api-error,
.nd-api-error {
  display: grid;
  gap: var(--nd-space-3, 0.75rem);
  padding: var(--nd-space-4, 1rem);
  border-radius: var(--nd-radius-lg, 0.75rem);
  border: 1px solid color-mix(in srgb, var(--nd-border) 70%, var(--nd-danger, var(--nd-accent)) 30%);
  background:
    radial-gradient(90% 70% at 0% 0%, color-mix(in srgb, var(--nd-danger, var(--nd-accent)) 12%, transparent), transparent 55%),
    var(--nd-surface-1);
}

.nt-api-error__kicker,
.nd-api-error__kicker {
  margin: 0;
}

.nt-section-panel {
  border-radius: var(--nd-radius-lg, 0.75rem);
  border: 1px solid var(--nd-border);
  background: var(--nd-surface-1);
  padding: var(--nd-space-3, 0.75rem);
}

.nt-panel-skel {
  border-radius: var(--nd-radius-md, 0.5rem);
  border: 1px dashed color-mix(in srgb, var(--nd-border) 80%, var(--nd-accent) 20%);
  padding: var(--nd-space-3, 0.75rem);
  background: color-mix(in srgb, var(--nd-surface-1) 92%, transparent);
}

.nt-webhooks-panel,
.nt-webhooks-shell {
  display: grid;
  gap: var(--nd-space-3, 0.75rem);
}

.nt-mono-11 {
  font-family: var(--nd-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  font-variant-numeric: tabular-nums;
}

.nt-row { display: flex; align-items: center; }
.nt-row-between-12 { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 0.75rem; }
.nt-row-center { display: flex; align-items: center; }
.nt-gap-6 { gap: 0.375rem; }
.nt-gap-8 { gap: 0.5rem; }
.nt-stack { display: flex; flex-direction: column; }
.nt-stack-8 { display: flex; flex-direction: column; gap: 0.5rem; }
.nt-stack-14 { display: flex; flex-direction: column; gap: 0.875rem; }
.nt-inline-gap-4 { display: inline-flex; align-items: center; gap: 0.25rem; }
.nt-flex-wrap { flex-wrap: wrap; }
.nt-fs-115-muted { font-size: 0.71875rem; color: var(--nd-text-tertiary); }
.nt-fs-125-primary { font-size: 0.78125rem; color: var(--nd-text); font-weight: 600; }

/* ── WAVE 20BCV · light theme screen header + change strip ─────────────── */

html[data-nd-theme='light'] .nt-screen-header,
html[data-nd-theme='light'] .nd-screen-header {
  background: color-mix(in srgb, var(--nd-surface-0) 92%, transparent);
}

html[data-nd-theme='light'] .nt-change-strip,
html[data-nd-theme='light'] .nd-change-strip {
  box-shadow: 0 1px 2px color-mix(in srgb, var(--nd-text) 5%, transparent);
}

html[data-nd-theme='light'] .nt-api-error,
html[data-nd-theme='light'] .nd-api-error {
  background:
    radial-gradient(90% 70% at 0% 0%, color-mix(in srgb, var(--nd-danger, var(--nd-accent)) 8%, transparent), transparent 55%),
    var(--nd-surface-0);
}

/* end wave 20bcs–20bcv */

/* ── WAVE 20BCW · 78k seal · copper NOC residual utilities ─────────────── */

.nt-panel-glass,
.nd-panel-glass {
  background: color-mix(in srgb, var(--nd-surface-1) 90%, transparent);
  backdrop-filter: blur(10px) saturate(1.08);
  -webkit-backdrop-filter: blur(10px) saturate(1.08);
  border: 1px solid color-mix(in srgb, var(--nd-border) 88%, var(--nd-accent) 12%);
}

.nt-table-toolbar__meta,
.nd-section-header__meta {
  font-size: var(--nd-text-xs, 0.75rem);
  color: var(--nd-text-tertiary);
  font-variant-numeric: tabular-nums;
}

.nt-heading,
.nd-heading {
  margin: 0;
  color: var(--nd-text);
  letter-spacing: -0.015em;
  font-weight: 750;
}

.nt-heading--1,
.nd-heading--1 { font-size: var(--nd-text-2xl, 1.5rem); }
.nt-heading--2,
.nd-heading--2 { font-size: var(--nd-text-xl, 1.25rem); }
.nt-heading--3,
.nd-heading--3 { font-size: var(--nd-text-lg, 1.125rem); }

.nt-heading__overline,
.nd-heading__overline {
  display: block;
  margin-bottom: 0.25rem;
}

.nt-root,
.nd-root {
  color: var(--nd-text);
  background: var(--nd-surface-0);
  min-height: 100%;
}

.nt-avatar,
.nd-avatar {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  background: color-mix(in srgb, var(--nd-surface-2) 70%, var(--nd-accent) 30%);
  color: var(--nd-text);
  font-weight: 700;
  font-size: 0.7rem;
  letter-spacing: 0.04em;
}

.nt-avatar[data-size='sm'],
.nd-avatar--sm { width: 1.5rem; height: 1.5rem; }
.nt-avatar[data-size='md'],
.nd-avatar--md { width: 2rem; height: 2rem; font-size: 0.75rem; }

.nt-spinner,
.nd-spinner {
  display: inline-block;
  width: 1rem;
  height: 1rem;
  border-radius: 999px;
  border: 2px solid color-mix(in srgb, var(--nd-border) 70%, transparent);
  border-top-color: var(--nd-accent);
  animation: nt-spin 0.7s linear infinite;
  vertical-align: middle;
}

.nd-spinner--md,
.nt-spinner[data-size='md'] { width: 1.35rem; height: 1.35rem; }

@keyframes nt-spin {
  to { transform: rotate(360deg); }
}

@media (prefers-reduced-motion: reduce) {
  .nt-spinner,
  .nd-spinner { animation: none; border-top-color: var(--nd-text-tertiary); }
}

.nt-skeleton-block,
.nd-skeleton {
  display: block;
  border-radius: var(--nd-radius-sm, 0.375rem);
}

.nt-page-skeleton,
.nd-page-skeleton {
  display: grid;
  gap: var(--nd-space-3, 0.75rem);
  padding: var(--nd-space-3, 0.75rem);
}

.nt-page-skeleton__header,
.nd-page-skeleton__header {
  display: grid;
  gap: 0.45rem;
}

.nt-page-skeleton__stats,
.nd-page-skeleton__stats {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(7rem, 1fr));
  gap: 0.5rem;
}

.nt-page-skeleton__grid,
.nd-page-skeleton__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.75rem;
}

@media (max-width: 720px) {
  .nt-page-skeleton__grid,
  .nd-page-skeleton__grid { grid-template-columns: 1fr; }
}

/* ── WAVE 20BCX · toast dual-tone · menu item danger ───────────────────── */

.nt-toast--success,
.nd-toast--success {
  border-color: color-mix(in srgb, var(--nd-success, var(--nd-accent)) 40%, var(--nd-border));
